-- ══════════════════════════════════════════════════════════════════════════
-- 0003_views.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- Funnel OS — the 29 metrics.
--
-- Every view is the same spine with different columns, so the metric maths lives
-- in ONE function and each view only decides how to cut the data.
--
-- The two rules the PRD calls out are encoded here and nowhere else:
--
--   BLANK vs ZERO   a cut with no ads_performance rows has no spend, so spend,
--                   reach, frequency, impressions, clicks, CTR, lead-gen, every
--                   CP* and every ROAS return NULL — not 0. A class doesn't buy
--                   traffic; the round does. Organic has no spend. Not zero,
--                   not infinite — absent.
--
--   ZERO-DENOM      every ratio divides by NULLIF(denominator, 0), so a missing
--                   denominator renders '—' instead of 0%, and never #DIV/0!.
--
-- The frontend receives NULL and prints '—'. It never decides which is which.
-- ═══════════════════════════════════════════════════════════════════════════

drop function if exists fo_metrics cascade;

-- Parameters are p_-prefixed deliberately: inside a SQL function body, a column
-- name from the FROM clause outranks a same-named parameter, so a parameter
-- called `spend` would be silently shadowed by the blanked `spend` column (or
-- worse, the other way round) and blank-vs-zero would stop working.
create or replace function fo_metrics(
  p_has_ads           boolean,          -- does this cut have ANY ads_performance rows?
  p_spend             numeric,
  p_reach             bigint,
  p_impressions       bigint,
  p_clicks            bigint,
  p_leads             bigint,
  p_attendance        bigint,
  p_preview_purchases bigint,
  p_middle_purchases  bigint,
  p_preview_revenue   numeric,
  p_middle_revenue    numeric,
  p_preview_price     numeric,          -- configured unit price, from client_journey_config
  p_middle_price      numeric
) returns jsonb
language sql
immutable
as $$
  with m as (
    select
      -- blank-vs-zero: no ads rows for this cut => the ads metrics do not exist
      case when p_has_ads then p_spend       end as spend,
      case when p_has_ads then p_reach       end as reach,
      case when p_has_ads then p_impressions end as impressions,
      case when p_has_ads then p_clicks      end as clicks,
      coalesce(p_leads, 0)             as leads,
      coalesce(p_attendance, 0)        as attendance,
      coalesce(p_preview_purchases, 0) as prev_buy,
      coalesce(p_middle_purchases, 0)  as mid_buy,
      coalesce(p_preview_revenue, 0)   as prev_rev,
      coalesce(p_middle_revenue, 0)    as mid_rev
  )
  select jsonb_build_object(
    -- ── METRICS (1–14) ────────────────────────────────────────────────────
    'spend',      spend,
    'reach',      reach,
    'freq',       impressions::numeric / nullif(reach, 0),
    'impr',       impressions,
    'clicks',     clicks,
    'leads',      leads,
    'att',        attendance,
    'prevBuy',    prev_buy,
    'midBuy',     mid_buy,
    'prevRev',    prev_rev,
    'midRev',     mid_rev,
    -- selling price is the configured unit price, shown only where the cut
    -- actually has purchases of that product ('—' otherwise, per the mockup)
    'prevPrice',  case when prev_buy > 0 then p_preview_price end,
    'midPrice',   case when mid_buy  > 0 then p_middle_price  end,
    'rev',        prev_rev + mid_rev,

    -- ── FUNNEL METRICS (15–19) ────────────────────────────────────────────
    'ctr',        clicks::numeric  * 100 / nullif(impressions, 0),
    'leadgen',    leads::numeric   * 100 / nullif(clicks, 0),
    'attPct',     attendance::numeric * 100 / nullif(leads, 0),
    'prevPct',    prev_buy::numeric   * 100 / nullif(attendance, 0),
    'midPct',     mid_buy::numeric    * 100 / nullif(prev_buy, 0),

    -- ── UNIT OF ECONOMICS (20–29) ─────────────────────────────────────────
    'cpm',        spend * 1000 / nullif(impressions, 0),
    'cpc',        spend / nullif(clicks, 0),
    'cpl',        spend / nullif(leads, 0),
    'cpAtt',      spend / nullif(attendance, 0),
    -- CPA is cost per *acquired customer*, and the mockup measures that against
    -- preview purchases (12,897.14 / 39 = 330.70), not preview+middle. The middle
    -- offer is sold to people already acquired by the preview.
    'cpa',        spend / nullif(prev_buy, 0),
    'prevAov',    prev_rev / nullif(prev_buy, 0),
    'prevRoas',   prev_rev / nullif(spend, 0),
    'midAov',     mid_rev / nullif(mid_buy, 0),
    'midRoas',    mid_rev / nullif(spend, 0),
    'roas',       (prev_rev + mid_rev) / nullif(spend, 0)
  )
  from m;
$$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Building blocks
-- ═══════════════════════════════════════════════════════════════════════════

-- Configured unit prices, one row per client.
-- A journey whose purchase stage is 'checkout' rather than 'preview' (ecommerce)
-- still records its sales as product = 'preview' — the first purchase in the
-- journey — so the checkout price stands in as the preview price for that client.
create or replace view v_client_prices as
select
  client_id,
  coalesce(
    max(unit_price) filter (where stage_slug = 'preview'),
    max(unit_price) filter (where stage_slug = 'checkout')
  ) as preview_price,
  max(unit_price) filter (where stage_slug = 'middle')   as middle_price,
  max(unit_price) filter (where stage_slug = 'checkout') as checkout_price
from client_journey_config
group by client_id;

-- Clients, for the switcher. Derived from the journey config — client is a
-- dimension, and the journey is what makes a client real to this app.
--
-- Ordered by how much history each client has, so the app opens on the account
-- with something to look at rather than on whichever name sorts first.
create or replace view v_clients as
select
  j.client_id,
  min(j.client_name)        as client_name,
  min(j.client_note)        as client_note,
  count(*)                  as stage_count,
  coalesce(r.round_count, 0) as round_count
from client_journey_config j
left join (
  select client_id, count(*) as round_count from rounds group by client_id
) r on r.client_id = j.client_id
group by j.client_id, r.round_count
order by coalesce(r.round_count, 0) desc, j.client_id;

-- Journey stages, in order. Drives the Customer Journey strip AND the Compare nav
-- group — change a client's journey and the views change with it.
create or replace view v_journey as
select
  client_id, stage_order, stage_name, stage_slug,
  compare_dimension, stage_metric, stage_rate_label, unit_price
from client_journey_config
order by client_id, stage_order;

-- Every ads_performance row with its client attached (ads_performance scopes
-- through round_id — there's no client_id on the table).
create or replace view v_ads as
select r.client_id, a.*
from ads_performance a
join rounds r on r.round_id = a.round_id;

-- Every event with its client, plus the derived attribution bucket.
--
-- "Previous Paid Ads" is not a source. It's the sales where the round that
-- produced the lead isn't the round whose class closed it — AND the source is
-- Paid Ads. An Organic lead from August buying in October is still Organic.
create or replace view v_events as
select
  r.client_id,
  e.*,
  case
    when e.source = 'Paid Ads'
     and coalesce(e.close_round_id, e.round_id) is distinct from e.lead_round_id
      then 'Previous Paid Ads'
    else e.source
  end as attribution_bucket
from events e
join rounds r on r.round_id = e.round_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND  — Overview / By round     (fully wired)
--
-- Note the deliberate asymmetry, straight from the schema doc:
--   leads + attendance are counted on round_id      — whose class was this?
--   revenue + purchases are counted on lead_round_id — whose spend produced it?
-- So a lead from 0526-02 who attends 0526-03's class and buys there is counted
-- in 0526-03's attendance and in 0526-02's revenue. Both true, same total.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    sales.prev_buy, sales.mid_buy, sales.prev_rev, sales.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS  — Compare / Targeted views     (fully wired)
--
-- The bridge is events.utm_campaign -> ads_performance.ad_set: the audience the
-- lead came from. People with no utm (organic, previous-round) have no audience,
-- so they land in the client total but in none of the audience columns — which
-- is exactly right, they cost nothing.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads where ad_set is not null group by client_id, ad_set
),
ev as (
  select client_id, utm_campaign as ad_set,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events where utm_campaign is not null group by client_id, utm_campaign
)
select
  coalesce(ads.client_id, ev.client_id) as client_id,
  coalesce(ads.ad_set, ev.ad_set)       as cut_key,
  coalesce(ads.ad_set, ev.ad_set)       as cut_label,
  null::text                            as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m,
  coalesce(ads.spend, 0) as sort_spend
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, sort_spend desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL — the "Total" column that leads every comparison view
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column that never scrolls away.
-- The mockup pins a single historical round as the yardstick; we pin the client's
-- earliest round that has both spend and sales, so it stays meaningful as rounds
-- are added rather than drifting to whatever is first alphabetically.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_baseline as
select distinct on (client_id)
  client_id, cut_key, cut_label, cut_sub, m
from v_metrics_by_round
where (m->>'spend') is not null and (m->>'rev')::numeric > 0
order by client_id, start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- CUSTOMER JOURNEY STRIP — one card per stage, values straight off the total.
-- Stage -> metric mapping is data (client_journey_config.stage_metric), so an
-- ecommerce client's strip is built by the same query with no branching.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_journey_strip as
select
  j.client_id, j.stage_order, j.stage_name, j.stage_slug, j.stage_rate_label,
  case j.stage_metric
    when 'impressions'       then (t.m->>'impr')
    when 'clicks'            then (t.m->>'clicks')
    when 'leads'             then (t.m->>'leads')
    when 'attendance'        then (t.m->>'att')
    when 'preview_purchases' then (t.m->>'prevBuy')
    when 'middle_purchases'  then (t.m->>'midBuy')
  end as value,
  case j.stage_metric
    when 'clicks'            then (t.m->>'ctr')
    when 'leads'             then (t.m->>'leadgen')
    when 'attendance'        then (t.m->>'attPct')
    when 'preview_purchases' then (t.m->>'prevPct')
    when 'middle_purchases'  then (t.m->>'midPct')
  end as rate
from v_journey j
left join v_metrics_total t on t.client_id = j.client_id
order by j.client_id, j.stage_order;

-- ═══════════════════════════════════════════════════════════════════════════
-- IMPORT + UNMATCHED — the Data group, and the staleness flag the header carries.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_import_status as
select
  client_id, source, imported_at, coverage_start, coverage_end, row_count,
  column_map, expected_cadence,
  stale_flag or (now() - imported_at) > coalesce(expected_cadence, interval '1 day') * 2
    as is_stale,
  extract(day from now() - imported_at)::int as days_since
from import_batches
order by client_id, source;

create or replace view v_unmatched_summary as
select
  client_id,
  count(*) filter (where not auto_resolved and resolved_at is null) as waiting,
  count(*) filter (where auto_resolved)                             as auto_resolved,
  coalesce(sum(revenue_held) filter (where resolved_at is null), 0) as revenue_held,
  count(*) filter (where resolved_at is null and revenue_held > 0)  as sales_held,
  count(distinct source) filter (where not auto_resolved and resolved_at is null) as source_count
from unmatched_rows
group by client_id;

create or replace view v_unmatched_by_reason as
select
  client_id, reason,
  count(*)                as rows_waiting,
  sum(revenue_held)       as revenue_held
from unmatched_rows
where not auto_resolved and resolved_at is null
group by client_id, reason
order by client_id, count(*) desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- Grants — PostgREST serves these views to the anon key. Views run with the
-- owner's rights (security_invoker is off by default), so base-table RLS isn't
-- re-evaluated per row here; read access is what's granted.
-- ═══════════════════════════════════════════════════════════════════════════
grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0004_client_default.sql
-- ══════════════════════════════════════════════════════════════════════════

-- Funnel OS — patch 0004
-- 1. v_clients now orders by how much history a client has, so the app opens on
--    Shely rather than on whichever client name sorts first alphabetically.
-- 2. v_client_prices falls back to the checkout stage price for journeys that
--    have no 'preview' stage (ecommerce), so their Selling Price row isn't blank.
-- Safe to re-run. Nothing else changes.

-- Configured unit prices, one row per client.
-- A journey whose purchase stage is 'checkout' rather than 'preview' (ecommerce)
-- still records its sales as product = 'preview' — the first purchase in the
-- journey — so the checkout price stands in as the preview price for that client.
create or replace view v_client_prices as
select
  client_id,
  coalesce(
    max(unit_price) filter (where stage_slug = 'preview'),
    max(unit_price) filter (where stage_slug = 'checkout')
  ) as preview_price,
  max(unit_price) filter (where stage_slug = 'middle')   as middle_price,
  max(unit_price) filter (where stage_slug = 'checkout') as checkout_price
from client_journey_config
group by client_id;

-- Clients, for the switcher. Derived from the journey config — client is a
-- dimension, and the journey is what makes a client real to this app.
--
-- Ordered by how much history each client has, so the app opens on the account
-- with something to look at rather than on whichever name sorts first.
create or replace view v_clients as
select
  j.client_id,
  min(j.client_name)        as client_name,
  min(j.client_note)        as client_note,
  count(*)                  as stage_count,
  coalesce(r.round_count, 0) as round_count
from client_journey_config j
left join (
  select client_id, count(*) as round_count from rounds group by client_id
) r on r.client_id = j.client_id
group by j.client_id, r.round_count
order by coalesce(r.round_count, 0) desc, j.client_id;


grant select on v_clients, v_client_prices to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0005_import.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- Funnel OS — patch 0005: the import pipeline
--
-- The workflow the brief specifies is gated and one-way:
--
--   imported ──→ matched ──→ attributed ──→ diffed ──→ committed
--                    │
--                    ├──→ auto-resolved  (confident match, counted, no review)
--                    └──→ parked         (unmatched_rows, not counted, revenue held)
--
-- "Show the diff before committing" means a batch has to exist in a staged state
-- with its parsed rows attached, so nothing is written to events / ads_performance
-- until someone approves it. That's what staged_payload and status are for.
--
-- Safe to re-run.
-- ═══════════════════════════════════════════════════════════════════════════

alter table import_batches
  add column if not exists status         text not null default 'committed'
    check (status in ('staged', 'committed', 'discarded')),
  add column if not exists file_name      text,
  add column if not exists staged_payload jsonb,   -- parsed rows, dropped on commit
  add column if not exists diff_summary   jsonb,   -- what the commit did / would do
  add column if not exists committed_at   timestamptz;

-- Everything seeded before this patch is already committed history.
update import_batches set status = 'committed' where status is null;

-- Which contact an unmatched row was finally tied to, when a human accepts the
-- best guess. Keeps the audit trail: the parked row is resolved, never deleted.
alter table unmatched_rows
  add column if not exists resolved_contact_id uuid references contacts (contact_id),
  add column if not exists resolved_by         text;

create index if not exists idx_import_batches_status on import_batches (status);
create index if not exists idx_unmatched_open
  on unmatched_rows (client_id) where resolved_at is null and auto_resolved = false;

-- The column mapping remembered per source: the most recent committed batch's map
-- is what the next import is checked against, so a renamed column breaks loudly
-- instead of importing a blank.
create or replace view v_column_map as
select distinct on (client_id, source)
  client_id, source, column_map, imported_at
from import_batches
where status = 'committed' and column_map is not null
order by client_id, source, imported_at desc;

-- Batches waiting for approval, for the Import screen.
create or replace view v_staged_batches as
select batch_id, client_id, source, file_name, row_count, imported_at,
       column_map, diff_summary
from import_batches
where status = 'staged'
order by imported_at desc;

grant select on v_column_map, v_staged_batches to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0006_source.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY SOURCE  — Overview / By source
--
-- The master sheet splits every round into Total · Paid Ads · Previous Paid Ads
-- · AOAI · Organic. This is that split, as columns on the same spine as every
-- other view — same 29 metrics, same order, same blank-vs-zero rule.
--
-- The bucket is not a new concept: v_events already derives attribution_bucket,
-- including the Previous Paid Ads rule (a Paid Ads person whose closing round
-- isn't the round that produced the lead). This view only groups by it.
--
-- SPEND BELONGS TO PAID ADS, AND ONLY TO PAID ADS.
-- An AOAI member costs nothing to acquire and an organic lead costs nothing to
-- acquire, so their spend is not zero — it does not exist. fo_metrics is told
-- has_ads = false for those columns, which blanks spend, CPM, CPC, CPL, CPA and
-- both ROAS rows rather than dividing by zero. That matches the master sheet,
-- where those cells are empty and the ratios read #DIV/0!.
--
-- Run in the Supabase SQL editor. Creates views only — no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

-- Column order is fixed rather than data-driven: a column that appears and
-- disappears as rows land would move the others sideways between page loads.
create or replace view v_source_buckets as
select * from (values
  ('Paid Ads',          1, 'utm captured at opt-in'),
  ('Previous Paid Ads', 2, 'paid lead from an earlier round'),
  ('AOAI',              3, 'community member'),
  ('AI Community',      4, 'community member'),
  ('Organic',           5, 'no utm, no community tag'),
  ('Unattributed',      6, 'source not recorded')
) as t(bucket, ord, note);

create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

grant select on v_source_buckets to anon, authenticated;
grant select on v_metrics_by_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0007_round_source.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE  — Overview / Round × source
--
-- The master sheet's actual layout: rounds across the top, each split into
-- Total · Paid Ads · Previous Paid Ads · AOAI · Organic. Two dimensions at
-- once, on the same 29-metric spine as every other view.
--
-- Requires 0006_source.sql (v_source_buckets). Creates a view — no table is
-- touched.
--
-- The per-round Total column is selected straight out of v_metrics_by_round
-- rather than re-aggregated here. That isn't laziness: it makes the Total
-- column reconcile with the By round tab by construction, so the two screens
-- can never drift apart.
--
-- The same asymmetry as v_metrics_by_round is preserved deliberately:
--   leads + attendance count on round_id       — whose class was this?
--   revenue + purchases count on lead_round_id — whose spend produced it?
-- Splitting by bucket must not quietly change which round a sale belongs to.
--
-- Spend attaches to the Paid Ads column only, for the reason given in 0006:
-- an organic lead's acquisition cost is absent, not zero.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    ev.leads, ev.attendance,
    sales.prev_buy, sales.mid_buy, sales.prev_rev, sales.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0 or (m->>'rev')::numeric > 0 or (m->>'spend') is not null;

grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0008_absent_not_zero.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ABSENT IS NOT ZERO — for sales, and for spend that names no audience.
--
-- The footer of every screen promises "blank means absent, not zero". fo_metrics
-- kept that promise for ads (p_has_ads blanks spend, CPM, CPC, CPL) and broke it
-- for everything else, because it coalesced the people and money inputs to 0
-- before doing any arithmetic.
--
-- What that produced, on real data, with no payments file ever imported:
--
--     0526-02 → spend 1378.24 · rev 0 · roas 0 · cpa null
--
-- CPA went blank, correctly — no denominator. Revenue and ROAS read a hard ZERO,
-- which is a measurement: it says the round earned nothing. The master sheet says
-- that round returned 6.0×. Nobody had loaded a sale yet; the app was reporting a
-- number about data that did not exist, and reporting it in the direction that
-- makes the work look worthless.
--
-- Compare an empty round under the old rule and you can see the inconsistency in
-- one row: spend is null so it renders "—", rev is 0 so it renders "0.00". Two
-- absences, two different answers.
--
-- Two changes, same idea:
--
--   1. fo_metrics no longer coalesces. NULL in, NULL out — and because SQL
--      arithmetic propagates NULL, every rate and ratio derived from a missing
--      input goes blank on its own. Each view now decides for itself where 0 is
--      a real measurement, and passes coalesce(x, 0) only there.
--
--   2. Ad rows that name no ad set stop being an audience called "". They were
--      appearing on Targeted views as a column with an empty header holding
--      every dollar and zero leads — and a Lead Gen % of 0.00%, which claims
--      those 856 clicks produced nobody. They produced 306 people; we just can't
--      say which audience they came from. That column is now labelled, and its
--      people-derived rows are blank rather than zero.
--
-- Requires 0003, 0006, 0007. Creates views and replaces one function — no table
-- is touched, and no signature changes, so nothing needs dropping.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── The spine ──────────────────────────────────────────────────────────────
-- Same 13 parameters as before, so this is a body-only replacement and the
-- dependent views survive it.
create or replace function fo_metrics(
  p_has_ads           boolean,          -- does this cut have ANY ads_performance rows?
  p_spend             numeric,
  p_reach             bigint,
  p_impressions       bigint,
  p_clicks            bigint,
  p_leads             bigint,
  p_attendance        bigint,
  p_preview_purchases bigint,
  p_middle_purchases  bigint,
  p_preview_revenue   numeric,
  p_middle_revenue    numeric,
  p_preview_price     numeric,          -- configured unit price, from client_journey_config
  p_middle_price      numeric
) returns jsonb
language sql
immutable
as $$
  with m as (
    select
      -- blank-vs-zero: no ads rows for this cut => the ads metrics do not exist
      case when p_has_ads then p_spend       end as spend,
      case when p_has_ads then p_reach       end as reach,
      case when p_has_ads then p_impressions end as impressions,
      case when p_has_ads then p_clicks      end as clicks,
      -- NO coalesce. A caller that means zero passes zero; a caller that means
      -- "this was never measured" passes NULL and every metric below it blanks
      -- itself, because NULL + anything is NULL and NULL / anything is NULL.
      p_leads             as leads,
      p_attendance        as attendance,
      p_preview_purchases as prev_buy,
      p_middle_purchases  as mid_buy,
      p_preview_revenue   as prev_rev,
      p_middle_revenue    as mid_rev
  )
  select jsonb_build_object(
    -- ── METRICS (1–14) ────────────────────────────────────────────────────
    'spend',      spend,
    'reach',      reach,
    'freq',       impressions::numeric / nullif(reach, 0),
    'impr',       impressions,
    'clicks',     clicks,
    'leads',      leads,
    'att',        attendance,
    'prevBuy',    prev_buy,
    'midBuy',     mid_buy,
    'prevRev',    prev_rev,
    'midRev',     mid_rev,
    -- selling price is the configured unit price, shown only where the cut
    -- actually has purchases of that product ('—' otherwise, per the mockup)
    'prevPrice',  case when prev_buy > 0 then p_preview_price end,
    'midPrice',   case when mid_buy  > 0 then p_middle_price  end,
    'rev',        prev_rev + mid_rev,

    -- ── FUNNEL METRICS (15–19) ────────────────────────────────────────────
    'ctr',        clicks::numeric  * 100 / nullif(impressions, 0),
    'leadgen',    leads::numeric   * 100 / nullif(clicks, 0),
    'attPct',     attendance::numeric * 100 / nullif(leads, 0),
    'prevPct',    prev_buy::numeric   * 100 / nullif(attendance, 0),
    'midPct',     mid_buy::numeric    * 100 / nullif(prev_buy, 0),

    -- ── UNIT OF ECONOMICS (20–29) ─────────────────────────────────────────
    'cpm',        spend * 1000 / nullif(impressions, 0),
    'cpc',        spend / nullif(clicks, 0),
    'cpl',        spend / nullif(leads, 0),
    'cpAtt',      spend / nullif(attendance, 0),
    -- CPA is cost per *acquired customer*, and the mockup measures that against
    -- preview purchases (12,897.14 / 39 = 330.70), not preview+middle. The middle
    -- offer is sold to people already acquired by the preview.
    'cpa',        spend / nullif(prev_buy, 0),
    'prevAov',    prev_rev / nullif(prev_buy, 0),
    'prevRoas',   prev_rev / nullif(spend, 0),
    'midAov',     mid_rev / nullif(mid_buy, 0),
    'midRoas',    mid_rev / nullif(spend, 0),
    'roas',       (prev_rev + mid_rev) / nullif(spend, 0)
  )
  from m;
$$;

-- Has this client ever had a sale land? Not "did this cut sell anything" — once
-- a payments file is in, a round that sold nothing really did sell nothing and
-- should read 0. Until then there is no evidence either way, and 0 is a lie.
--
-- Deliberately keyed on events rather than import_batches: a sales file whose
-- every row parked in Unmatched has been imported but has told us nothing.
create or replace view v_sales_seen as
select distinct client_id from v_events where event_type = 'sale';

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    -- leads and attendance are known: the files are in, this round had none
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- sales are known only once a sale exists for this client
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS
--
-- The bridge is events.utm_campaign -> ads_performance.ad_set. Two things get
-- normalised here that didn't before:
--
--   '' is not an ad set. A blank cell in a Meta export means the export didn't
--   say, and "didn't say" is not the name of an audience. Rows like that now
--   group into one labelled column instead of a column with an empty header.
--
--   That column gets NULL people, not zero. It has spend and clicks and no way
--   to know which leads they produced — so leads, attendance, CPL and Lead Gen %
--   are blank there. Reading 0 leads against 856 clicks would say the money
--   bought nobody, when what happened is that the export didn't record which
--   audience bought them.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
ev as (
  select client_id, nullif(btrim(utm_campaign), '') as ad_set,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  where nullif(btrim(utm_campaign), '') is not null
  group by client_id, nullif(btrim(utm_campaign), '')
)
select
  coalesce(ads.client_id, ev.client_id)                     as client_id,
  coalesce(ads.ad_set, ev.ad_set, '(unsplit)')              as cut_key,
  coalesce(ads.ad_set, ev.ad_set, 'Unsplit spend')          as cut_label,
  case when coalesce(ads.ad_set, ev.ad_set) is null
       then 'ads that name no ad set' end                   as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.leads, 0)      end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.attendance, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_buy, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_buy, 0)  end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_rev, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_rev, 0)  end,
    p.preview_price, p.middle_price
  ) as m,
  -- the app sorts on this descending; unsplit spend is real but it isn't an
  -- audience, so it sits after every named one however large it is
  case when coalesce(ads.ad_set, ev.ad_set) is null then -1
       else coalesce(ads.spend, 0) end                      as sort_spend
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_sales_seen s on s.client_id = coalesce(ads.client_id, ev.client_id)
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, sort_spend desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY SOURCE — spend still belongs to Paid Ads and only to Paid Ads.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_sales_seen s on s.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE — per-round Total still lifted whole out of By round, so the
-- two tabs cannot drift.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_baseline as
select distinct on (client_id)
  client_id, cut_key, cut_label, cut_sub, m
from v_metrics_by_round
where (m->>'spend') is not null and coalesce((m->>'rev')::numeric, 0) > 0
order by client_id, start_date;

grant select on v_sales_seen to anon, authenticated;
grant select on v_metrics_by_round to anon, authenticated;
grant select on v_metrics_by_adset to anon, authenticated;
grant select on v_metrics_total to anon, authenticated;
grant select on v_metrics_baseline to anon, authenticated;
grant select on v_metrics_by_source to anon, authenticated;
grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0009_audience_and_reasons.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- WHICH AUDIENCE CONVERTS — and saying why a row was parked.
--
-- Three fixes, found by checking the live app after the first real sales import.
--
-- 1. TARGETED VIEWS DIED BELOW THE LEADS ROW.
--
--        lead        306 rows, 292 with utm_campaign
--        attendance   40 rows,   0 with utm_campaign
--        sale          2 rows,   0 with utm_campaign
--
--    The importer writes utm_campaign onto lead events and nowhere else, so
--    joining attendance and sales on the event's own utm found nothing and every
--    audience reported 0 attendees and 0 buyers. Those 44 Cold_Broad leads
--    certainly produced some of the 40 attendees; printing 0 claims otherwise.
--
--    The app already solved this problem once. lead_round_id exists because a
--    sale belongs to the round that ACQUIRED the person, not the round it
--    happened in. Audiences get the same treatment here: a person's attendance
--    and purchases are attributed to the audience their lead came from. Without
--    it the tab can only ever report cost per lead, when the question it is
--    named for is which audience converts.
--
-- 2. THE COLUMNS SHUFFLED BETWEEN PAGE LOADS. With no per-audience spend,
--    sort_spend was 0 for all eight audiences and Postgres returned them in
--    whatever order it liked. v_metrics_by_source fixes its column order on
--    purpose so a column doesn't slide sideways; this view now does too, via an
--    explicit `ord` the app reads instead of a spend that is often a tie.
--
-- 3. "NAME ONLY, NO CONTACT DETAIL" WAS GROUPING ROWS THAT HAD CONTACT DETAIL.
--    The importer reused reason = 'name_only' for rows it couldn't use for
--    completely different causes — no opt-in date, no round, an unrecognised
--    product. limpljanet@gmail.com sat under "no contact detail" with its email
--    right there in the row. Two new reasons split that apart, and they map to
--    two different actions: fix the file, or create the round.
--
-- Requires 0008. Adds a check constraint value and re-labels 9 existing rows;
-- creates no tables.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 3. Reasons ─────────────────────────────────────────────────────────────
alter table unmatched_rows drop constraint if exists unmatched_rows_reason_check;
alter table unmatched_rows add constraint unmatched_rows_reason_check
  check (reason in (
    'same_person_two_addresses',
    'phone_format',
    'name_only',          -- we know the row, we don't know the person
    'bought_without_lead',
    'incomplete_row',     -- the row is missing something the app needs
    'no_matching_round',  -- the row is fine; there is no round to attach it to
    'unknown_person'      -- contact detail we have, a person we don't
  ));

-- Re-label only rows whose guess_method already names the real cause. Rows
-- parked by the identity matcher have a null guess_method and really are
-- name_only — the 121 Zoom attendees with no email, and the 7 sales rows with
-- no email, are correctly filed and are left alone.
update unmatched_rows
   set reason = 'incomplete_row'
 where reason = 'name_only'
   and guess_method in ('no usable opt-in date', 'missing date or amount');

update unmatched_rows
   set reason = 'no_matching_round'
 where reason = 'name_only'
   and (guess_method like 'no round covers%' or guess_method like 'no round matches%');

-- ═══════════════════════════════════════════════════════════════════════════
-- 1 + 2. TARGETED VIEWS
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs that
-- carries a utm. A contact with no tagged lead has no audience and stays out of
-- every audience column, which is the existing rule and still correct — an
-- organic lead cost nothing, so it belongs to no ad set.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id, nullif(btrim(utm_campaign), '') as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and nullif(btrim(utm_campaign), '') is not null
  order by client_id, contact_id, event_date
),
-- A LEAD is counted on its OWN tag, not on the acquiring lead's. The two differ
-- for anyone who opted in twice: 40 contacts here have a second lead, and
-- routing those through the first audience inflated the lead total from 828 to
-- 868. That second opt-in genuinely came from the second ad set — it is the
-- events with no tag of their own that need the detour.
ev_leads as (
  select client_id, nullif(btrim(utm_campaign), '') as ad_set, count(*) as leads
  from v_events
  where event_type = 'lead' and nullif(btrim(utm_campaign), '') is not null
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
)
select
  coalesce(ads.client_id, ev.client_id)                     as client_id,
  coalesce(ads.ad_set, ev.ad_set, '(unsplit)')              as cut_key,
  coalesce(ads.ad_set, ev.ad_set, 'Unsplit spend')          as cut_label,
  case when coalesce(ads.ad_set, ev.ad_set) is null
       then 'ads that name no ad set' end                   as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.leads, 0)      end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.attendance, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_buy, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_buy, 0)  end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_rev, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_rev, 0)  end,
    p.preview_price, p.middle_price
  ) as m,
  case when coalesce(ads.ad_set, ev.ad_set) is null then -1
       else coalesce(ads.spend, 0) end                      as sort_spend,
  -- Fixed column order. Spend first because that's the size of the bet, leads
  -- as the tiebreaker when no spend is attributable, then the name so the order
  -- is total rather than merely mostly-decided. Unsplit spend always last: it is
  -- real money but it isn't an audience.
  row_number() over (
    partition by coalesce(ads.client_id, ev.client_id)
    order by
      case when coalesce(ads.ad_set, ev.ad_set) is null then 1 else 0 end,
      coalesce(ads.spend, 0) desc,
      coalesce(ev.leads, 0) desc,
      coalesce(ads.ad_set, ev.ad_set)
  )::int                                                    as ord
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_sales_seen s on s.client_id = coalesce(ads.client_id, ev.client_id)
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0010_price_and_untagged_paid.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE MIDDLE OFFER HAS NO SINGLE PRICE — and untagged paid leads are not free.
--
-- 1. middle_price was configured as 3,000. The master sheet shows May's middle
--    ticket closing at 1,197 · 1,298.50 · 1,400 · 1,700 · 2,000 and never once
--    at 3,000. There is no single number that is right, so the honest value is
--    no number: Middle Selling Price renders '—' and Middle Offer AOV, which is
--    computed from money that actually moved, carries the truth.
--
--    Preview stays 297. That one really is fixed for everyone.
--
--    If the business does have a list price it discounts from, set it here and
--    Middle Selling Price starts reading again. Absent is a statement, not a
--    placeholder.
--
-- 2. FOURTEEN PAID LEADS WITH NO AD SET WERE FALLING OUT OF TARGETED VIEWS
--    ENTIRELY — including both buyers.
--
--        SALE 297 preview → their lead: {"utm_campaign": null, "source": "Paid Ads"}
--        SALE 297 preview → their lead: {"utm_campaign": null, "source": "Paid Ads"}
--
--    They are Paid Ads because their GoHighLevel campaign says so
--    (DF_SG_Preview_Sprint1_0526_02 is a Meta campaign). They have no ad set
--    because 23 people in the master export never appear in either round file,
--    and utm_term only exists there. No ad set is not the same as no ad.
--
--    Calling them Organic would say they cost nothing to acquire, which would
--    move 594.00 of revenue out of Paid Ads, blank the paid ROAS and invent an
--    organic return on spend that never happened. So they stay Paid Ads — but
--    they stop vanishing. The 'Unsplit spend' column already holds ad money
--    that names no audience; it now holds the paid people who name none either.
--    Same column, same reason: real, paid, unsplittable.
--
--    Organic and community leads still belong to no audience column, because
--    for them there genuinely was no ad.
--
-- Requires 0009. Changes one config value and one view.
-- ═══════════════════════════════════════════════════════════════════════════

update client_journey_config
   set unit_price = null
 where stage_slug = 'middle' and client_id = 'shely';

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- a utm. Paid leads with no utm resolve to the unsplit bucket instead of to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(utm_campaign), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(utm_campaign), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD is counted on its OWN tag, not on the acquiring lead's. The two differ
-- for anyone who opted in twice, and routing those through the first audience
-- inflated the lead total. That second opt-in really did come from the second
-- ad set — it is the events with no tag of their own that need the detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(utm_campaign), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(utm_campaign), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
-- ads with no ad set and paid people with no ad set are the same column
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
-- sum() widens bigint to numeric, and fo_metrics is typed on bigint for the
-- counts. Cast back explicitly rather than letting the call fail to resolve.
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend, r.reach, r.impressions, r.clicks,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  -- Fixed column order: spend, then leads, then name, so it is total rather
  -- than merely mostly-decided. Unsplit always last — real money, not an
  -- audience.
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0011_lead_adset_and_ad.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- A LEAD CARRIES AN AUDIENCE AND AN AD, NOT ONE FIELD DOING BOTH JOBS.
--
-- GoHighLevel writes three tracking tags at opt-in and they mean three
-- different things:
--
--   utm_term     the AUDIENCE   Cold_BusinessOwners
--   utm_content  the AD         Static_LetAISellYourProducts
--   utm_campaign the ROUND      DF_SG_Preview_Sprint1_0526_02
--
-- The app only ever read one column, called it utm_campaign, and expected the
-- AUDIENCE in it. So the raw GHL export imported perfectly and attributed
-- nothing: every lead arrived carrying a round name where an ad set was
-- expected, matched no audience, and silently fell back to date-window
-- attribution. The only reason the numbers are right today is that leads.csv
-- was hand-edited to move utm_term into the utm_campaign column — a manual step
-- that would eventually be forgotten with nothing to warn anyone.
--
-- events now stores what it actually has: ad_set and ad, named after the same
-- things ads_performance names them, so both sides of the bridge match.
--
-- The 17 leads whose utm_content is a raw numeric Ad ID rather than a name are
-- stored as-is. An id is a better key than a name — names get edited in Ads
-- Manager and silently break the join — and this is where that will be resolved
-- when ad-level Meta data arrives.
--
-- Requires 0010. Adds two columns, backfills them, replaces one view.
-- ═══════════════════════════════════════════════════════════════════════════

alter table events add column if not exists ad_set text;
alter table events add column if not exists ad     text;

create index if not exists idx_events_adset on events (ad_set);

-- Everything already imported put the audience in utm_campaign, because that is
-- the only column the importer read. Move it, don't reinterpret it: whatever is
-- in there today IS what the audience bridge has been matching on, so copying it
-- across preserves every number on screen exactly.
update events
   set ad_set = nullif(btrim(utm_campaign), '')
 where event_type = 'lead'
   and ad_set is null
   and nullif(btrim(utm_campaign), '') is not null;

-- v_events was written as `select r.client_id, e.*, … as attribution_bucket`,
-- and `e.*` is expanded ONCE, when the view is created. Adding a column to
-- events therefore does not reach the view — every downstream query would fail
-- with "column ad_set does not exist" while the column plainly exists.
--
-- The columns are listed out here rather than starred, in their table order,
-- with the two new ones appended AFTER attribution_bucket. Appending is the only
-- edit CREATE OR REPLACE VIEW accepts; had they landed mid-list (where `*` would
-- have put them) this would need a drop-cascade and a rebuild of all seven
-- dependent views.
create or replace view v_events as
select
  r.client_id,
  e.event_id, e.contact_id, e.round_id, e.event_type, e.event_date,
  e.lead_round_id, e.close_round_id, e.attribution_method, e.utm_campaign,
  e.source, e.match_status, e.product, e.minutes_watched,
  e.amount, e.refund_amount, e.refund_date, e.is_lead, e.import_batch_id,
  case
    when e.source = 'Paid Ads'
     and coalesce(e.close_round_id, e.round_id) is distinct from e.lead_round_id
      then 'Previous Paid Ads'
    else e.source
  end as attribution_bucket,
  e.ad_set,
  e.ad
from events e
join rounds r on r.round_id = e.round_id;

grant select on v_events to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS — same view as 0010, bridging on ad_set instead of on a
-- column named after a different tag.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend, r.reach, r.impressions, r.clicks,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0012_by_month.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY MONTH — management's first question, and the last unwired overview tab.
--
-- Every other comparison view already exists; this one was the only tab whose
-- SQL had never been written, so the app said "not wired yet" rather than
-- showing an answer to the question it is most often asked.
--
-- The cut is rounds.start_date grouped to a calendar month. A month is not a
-- new dimension — it is rounds, rolled up one level. That matters, because it
-- means every number on this tab is the same number as on By round, added the
-- same way, and the two tabs cannot disagree.
--
-- Three decisions worth stating, because each one could reasonably have gone
-- the other way:
--
--   1. A round belongs to the month it STARTED in, not to the month each ad
--      impression or opt-in happened in. 0526-02 ran 13–19 May and is May.
--      A round straddling a month boundary lands whole in its opening month
--      rather than being split — splitting it would put spend in one month and
--      the class that spend paid for in another, and every closing rate would
--      then be measured against a denominator from a different column.
--
--   2. Revenue counts on the month of the round that PRODUCED the lead, exactly
--      as By round counts it on lead_round_id. A June buyer whose lead came from
--      a May ad is May's return on May's spend. This is the whole reason the app
--      exists, and it must not change just because the columns got wider.
--
--   3. Reach is summed across the rounds in a month, which double-counts anyone
--      Meta showed the ads to in both. That is already true of the Total column
--      on every other tab — reach cannot be added, and Meta only reports it
--      per query. Consistent-and-known beats a different wrong number here.
--
-- A month appears if it contains a round, even when that round has no data yet:
-- By round shows the empty rounds, so By month shows the empty months. A tab
-- that quietly hid them would be claiming those months don't exist.
--
-- Requires 0008 (fo_metrics without coalesce, v_sales_seen). Creates one view.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_month as
with months as (
  select client_id,
         date_trunc('month', start_date)::date as month_start,
         count(*)::int                         as round_count
  from rounds
  group by 1, 2
),
ads as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend)       as spend,
         sum(a.reach)       as reach,
         sum(a.impressions) as impressions,
         sum(a.clicks)      as clicks,
         count(*)           as ad_rows
  from v_ads a
  join rounds r on r.round_id = a.round_id
  group by 1, 2
),
ev as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e
  join rounds r on r.round_id = e.round_id
  group by 1, 2
),
-- lead_round_id, not round_id: see decision 2 above.
sales as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e
  join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')                       as cut_key,
  to_char(m.month_start, 'Mon YYYY')                      as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    -- leads and attendance are known: the files are in, this month had none
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- sales are known only once a sale exists for this client
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s   on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0013_unsplit_has_no_delivery.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- "UNSPLIT SPEND" HAS NO CTR, BECAUSE IT IS NOT AN AUDIENCE.
--
-- Targeted views ends in a column called Unsplit spend. It holds the money that
-- moved without naming an ad set — a campaign exported without an ad-set
-- breakdown, or a round-level correction row. The column exists so that spend
-- lands SOMEWHERE rather than vanishing, and its label says exactly that.
--
-- It was also printing delivery metrics, and they were nonsense:
--
--     Unsplit spend    reach 22,803   impressions 1,566   clicks 856
--                      Outbound CTR 54.66%   Lead Gen % 1.05%   Frequency 0.07
--
-- 54.66% is not a click-through rate anyone has ever seen. It is 856 clicks —
-- the whole account's outbound clicks for two rounds — divided by 1,566
-- impressions, which belong only to the one campaign that had no ad-set
-- breakdown. Two different populations, one fraction. Frequency 0.07 says every
-- person saw the ad a fourteenth of a time.
--
-- The cause is not arithmetic. Meta's ad-set-level export gives spend and
-- impressions per ad set and does NOT give reach (deduplicated people cannot be
-- summed) or outbound clicks (the Outbound CTR column comes back empty on every
-- row). So those two figures are only available for the account as a whole and
-- have to enter as rows that name no ad set — landing, correctly, in the only
-- bucket for rows that name no ad set.
--
-- Every other view is unaffected and already right: By round, By source and the
-- Total column group by round, so they read reach 12,672 and clicks 479 for
-- 0526-02, matching the master sheet to the unit.
--
-- The rule this applies:
--
--   Reach, impressions and clicks describe how an AUDIENCE was delivered to.
--   Spend describes a payment. In the bucket whose entire meaning is "we cannot
--   say which audience", the delivery metrics have no subject, so they are
--   absent rather than zero and rather than wrong. Spend, leads, attendance and
--   revenue stay — those are real facts about the bucket.
--
-- After this the column reads: spend 84.20 · leads 9 · CPL 9.36 · attendance 2
-- · CP Attendance 42.10 · revenue 594.00 · ROAS 7.1, and a dash everywhere the
-- number would have been a fabrication.
--
-- THE REAL FIX IS UPSTREAM. Re-export the ad-set report from Meta with Reach
-- and Outbound clicks included as columns. Then every audience carries its own
-- CTR and CPC, the correction rows stop being necessary, and this bucket goes
-- back to holding nothing but genuinely unattributable spend.
--
-- Requires 0011. Replaces one view; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0014_import_status_is_one_row.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE IMPORT TAB SHOULD DESCRIBE THE LAST IMPORT, NOT EVERY ATTEMPT AT ONE.
--
-- v_import_status read `from import_batches` with no filter and no grouping,
-- so it returned every batch a client had ever produced — one row per source
-- was the intent, nine rows was the result:
--
--     ads         committed   03:11
--     ads         committed   03:28
--     attendance  DISCARDED   03:13     <-- an import that was cancelled
--     attendance  committed   03:13
--     attendance  committed   03:28
--     ...
--
-- Two things wrong with that, and the second is the serious one.
--
--   Which row wins is undefined. The Import tab and the header staleness pills
--   both read this view and take what arrives first. PostgREST does not promise
--   a view's own ORDER BY survives, so "Last import" could name an older batch
--   than the one whose rows are actually in the database.
--
--   A DISCARDED batch is reported as an import. Someone drops a file, reads the
--   diff, decides it is wrong and presses Discard — and the tab then tells them
--   that source was imported, with that file's row count and coverage. The one
--   action whose entire meaning is "this did not happen" was being recorded as
--   though it had. v_column_map already filtered on status; this view did not.
--
-- Now: one row per client and source, the newest COMMITTED batch, chosen by
-- distinct on rather than by hope.
--
-- ─── And a second fix, to what "stale" means ───────────────────────────────
--
-- It was: the last import is older than twice its expected cadence. Since the
-- cadence is written as '1 day' for every source, that reduced to "nothing has
-- been imported in the last two days" — which for an account whose most recent
-- round ended in May is true, permanent, and useless. The header read
--
--     Ads 2d stale · Attendance 2d stale · Leads 2d stale · Sales 2d stale
--
-- on a database whose figures were completely up to date. Four warnings that
-- are always on are the same as no warning at all, and they crowd out the one
-- that matters.
--
-- Stale now means: THIS SOURCE STOPS BEFORE THE ROUNDS DO. A source is stale
-- when its coverage ends before the last round that has already finished — that
-- is, when there is a round on the books for which we are missing data. Time
-- passing is not the signal; missing data is.
--
-- On the current database that turns four permanent warnings into one true one:
-- sales covers to 20 May while rounds run to 27 May, so 0526-03 has no sales
-- data — which is exactly the thing worth saying, and it was invisible before
-- because everything was shouting.
--
-- days_since is kept as it was, for the "3 days ago" label. It is a fact about
-- the clock and makes no claim.
--
-- Requires 0005 (status column). Replaces one view; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_import_status as
with latest as (
  -- one batch per source: the most recent one that actually landed
  select distinct on (client_id, source)
    client_id, source, imported_at, coverage_start, coverage_end,
    row_count, column_map, expected_cadence, stale_flag
  from import_batches
  where status = 'committed'
  order by client_id, source, imported_at desc
),
-- The last round that has already ended. A round still running is not evidence
-- of missing data — its files are not due yet.
horizon as (
  select client_id, max(end_date) as covered_through
  from rounds
  where end_date <= current_date
  group by client_id
)
select
  l.client_id, l.source, l.imported_at, l.coverage_start, l.coverage_end,
  l.row_count, l.column_map, l.expected_cadence,
  -- stale_flag stays respected: a batch explicitly marked stale is stale
  -- whatever the dates say.
  l.stale_flag
    or l.coverage_end is null
    or (h.covered_through is not null and l.coverage_end < h.covered_through)
    as is_stale,
  extract(day from now() - l.imported_at)::int as days_since
from latest l
left join horizon h on h.client_id = l.client_id
order by l.client_id, l.source;

grant select on v_import_status to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0015_wire_the_stage_tabs.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE JOURNEY-STAGE TABS, WIRED TO THE CUTS THE JOURNEY CONFIG ALREADY NAMES.
--
-- client_journey_config has carried a compare_dimension for every stage since
-- Sprint 2. Five of them had no view behind them, so the tabs said "not wired
-- yet" while the database already knew what they were supposed to cut by:
--
--     ads       ads_performance.ad        the creative
--     lp        (none)                    <- still nothing to cut by
--     class     rounds.session_label      Class A vs Class B
--     preview   events.round_id           rounds, preview offer only
--     middle    events.round_id           rounds, middle offer only
--
-- Landing page stays unwired, and deliberately. Its compare_dimension is null —
-- no dimension has been decided and no column exists to hold one. Guessing it
-- would put a number on screen that nobody chose.
--
-- Plus "This round", which is not a journey stage: the newest round that has
-- started, next to the one before it.
--
-- Every view here builds its columns with the same fo_metrics call as By round,
-- so a metric cannot mean one thing on one tab and something else on another,
-- and none of them touch a table. Requires 0013.
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ADS — the creative, not the audience.
--
-- Same bridge as Targeted views, one level down: events.ad against
-- ads_performance.ad. The people half is real — 18 creatives arrive on leads
-- from GoHighLevel's utm_content. The money half is empty, because the Meta
-- export we have is at ad-set level and its ad column is null on all 62 rows,
-- so every dollar lands in Unsplit spend until an ad-level export exists.
--
-- That is worth showing rather than hiding. "Which creative produced the most
-- leads" is answerable today; "what did it cost" is not, and a dash says so.
--
-- 17 leads carry a numeric Ad ID instead of a name, because a second tracking
-- template passes utm_content={{ad.id}}. They get their own columns rather than
-- being merged or dropped — an ID is a better join key than a name, and this is
-- where they resolve when ad-level spend arrives.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- ATTEND CLASS — rounds grouped by session_label, Class A against Class B.
--
-- Spend is kept, not blanked. A class variant does not buy traffic itself, but
-- the rounds that ran it did, and cost per attendee by class is the entire
-- reason this comparison is worth having: the old sheet protected the class
-- format and could not see what it cost. Reach is summed across the label's
-- rounds and double-counts anyone in both, exactly as it does on By month and
-- in every Total column — Meta only reports reach per query.
--
-- Both of Shely's May rounds are Class A, so this renders one column today and
-- splits the moment a Class B round is imported. One column is the true answer,
-- not a broken one.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend, sum(a.reach) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label                                                     as cut_key,
  l.label                                                     as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- PREVIEW OFFER and MIDDLE OFFER — rounds across, one offer at a time.
--
-- Same columns as By round. The difference is which offer's rows are filled:
-- on Preview the middle rows are NULL and on Middle the preview rows are, so
-- the take-up and ROAS lines read for the offer the tab is named after and
-- nothing else competes for attention.
--
-- NULL and not zero, deliberately. A round with no middle purchases and a round
-- whose middle numbers are simply not this tab's subject are different things,
-- and only one of them is a measurement. Both tabs' totals still agree with By
-- round because they are the same rows, filtered rather than recomputed.
--
-- Built as one view with a `product` column so the two tabs cannot drift apart.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- only this tab's offer carries numbers; the other is absent, not zero
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- THIS ROUND — the newest round that has started, beside the one before it.
--
-- "While it runs" is the intent, but a tab that empties itself the day a round
-- ends is a tab nobody trusts. The rule is the newest round whose start_date
-- has passed, which IS the live one while a round is running and is the one
-- just finished otherwise — and the previous round alongside it, because a
-- single number with nothing to compare it to is not analysis.
--
-- Rounds that have not started yet are excluded: a scheduled round has no
-- figures, and putting it here would answer "how is it going" with a blank.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_this_round as
select
  client_id, cut_key, cut_label, cut_sub, start_date, m,
  case when rn = 1 then 'this round' else 'previous' end as period,
  rn::int as ord
from (
  select b.*, row_number() over (partition by b.client_id order by b.start_date desc) as rn
  from v_metrics_by_round b
  join rounds r on r.round_id = b.cut_key
  where r.start_date <= current_date
) ranked
where rn <= 2
order by client_id, start_date;

grant select on v_metrics_this_round to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0016_reach_is_not_additive.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- REACH IS DEDUPLICATED PEOPLE, SO IT IS TAKEN FROM THE COARSEST ROW AVAILABLE
-- RATHER THAN ADDED UP.
--
-- Every other number in ads_performance is additive. Reach is not: it counts
-- distinct people, and the same person is reached by more than one ad set. The
-- May export proves the size of it —
--
--     DF_SG_Preview_Sprint1_0526_02   its six ad sets sum to  20,665
--                                     the campaign's own row   11,380
--
-- — so adding the ad-set rows overstates by 82%, and drags Frequency with it.
--
-- Until now the app avoided this by simply not having per-ad-set reach: the
-- daily export could not give a usable one, so reach entered on two hand-built
-- rows carrying the round totals and every audience showed a dash. The
-- period-level export changes that. Each ad set now has a real, deduplicated
-- reach for its own audience — 4,083 for Cold_Broad in 0526-02 — which is worth
-- having, and which must not be summed.
--
-- The rule, applied wherever rounds are rolled up:
--
--     A row that names no ad set is a COARSER measurement — a campaign or
--     account line. Where such rows exist they are the reach, because they are
--     already deduplicated across everything below them. Only when none exists
--     does the app fall back to adding the ad-set rows, and that sum is an
--     over-count it has no way to avoid.
--
-- Impressions, clicks and spend keep summing, because they are counts of events
-- rather than of people and adding them is correct.
--
-- Note this does NOT make a round's reach right when two campaigns ran in it —
-- 0526-03's two campaigns report 7,902 and 4,863 and the true figure is 10,131,
-- because the same person saw both. No per-campaign export can produce that; it
-- takes a query at the level you want the answer for. That is what the ads
-- file's round-level correction rows are, and why they still exist.
--
-- Requires 0015. Replaces four views; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY MONTH
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- ATTEND CLASS
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- AND ZERO SPEND IN THE UNSPLIT BUCKET IS NOT FREE LEADS.
--
-- The bucket that means "we cannot say which audience" now collects the
-- round-level reach rows, which carry no spend of their own. sum() of nothing
-- but zeroes is 0, so the column read
--
--     Unsplit spend    spend 0.00    leads 9    CPL 0.00
--
-- and CPL 0.00 says those nine leads were free. They were not; nobody knows
-- what they cost, which is the entire reason they are in this bucket.
--
-- Exactly-zero spend here becomes NULL, and CPL, CPA and ROAS blank themselves
-- with it. Real unsplit spend — a campaign exported without an ad-set
-- breakdown — is a positive number and still shows, which is the case this
-- column was built for. Same rule as 0013, applied to the one metric it left.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- 0 here means "no spend was recorded against unknown audiences", not
    -- "those leads cost nothing" — see the note above.
    case when r.ad_set = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0017_unsplit_has_no_spend_on_ads.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0017 — the Ads tab's Unsplit row must not claim it spent nothing.
--
-- 0016 taught v_metrics_by_adset that the (unsplit) bucket has no spend of its
-- own: the rows that land there are correction rows carrying reach and clicks
-- with spend 0.00, and 0.00 is not the same statement as "no spend recorded".
-- Left as 0.00 it also poisons CPL, which divided 0.00 by 9 leads and printed
-- "CPL 0.00" — a cost of nothing, on nine real people.
--
-- v_metrics_by_ad has exactly the same bucket and never got the same fix. Every
-- ad-set row and every round row in the ads file has a null `ad`, so all twenty
-- of them fold into (unsplit) there, and their spends are all 0.00.
--
-- The only change is nullif(spend, 0) on that one bucket, matching 0016 line
-- for line. Reach, impressions and clicks were already blanked in 0015 for the
-- same reason — delivery has no subject when nobody knows which creative it
-- was — so this closes the last column that was still answering.
--
-- Named creatives are untouched: a creative that genuinely spent 0.00 in a
-- round still reports 0.00, because it has ad rows and the bucket test is on
-- the literal '(unsplit)' key, not on the amount.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0018_leads_are_absent_not_zero.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0018 — two things the screen was stating that nobody had measured.
--
-- ONE. Reach was still being added up in three views.
--
-- 0016 established that reach cannot be summed — it counts deduplicated people,
-- so adding two rows counts anyone in both twice — and taught By round, Total,
-- By month and Attend class to read it off the coarsest row instead. Three
-- views never got the rule: Preview offer, Middle offer (one view), By source
-- and Round × source. They were reading 33,337 for a round whose real reach is
-- 12,672, and 62,279 for a client whose real reach is 22,803.
--
-- The tell was Frequency, which is impressions ÷ reach and therefore cannot be
-- below 1: nobody sees an ad less than once. Those tabs were printing 0.86 and
-- 0.78. An impossible number is the cheapest kind of bug to believe, because it
-- looks like a small one.
--
-- TWO. Leads and attendance read 0 before their file had ever been imported.
--
-- The app already knows the difference between a measurement and an absence,
-- and already applies it to money: revenue reads "—" rather than 0.00 until
-- some sale exists, because "this round earned nothing" is a claim nobody has
-- evidence for. Leads and attendance were exempt from their own rule. With only
-- the ads file imported, every tab showed "Leads 0" and "Lead Gen % 0.00%" —
-- which does not say "no leads file yet", it says the advertising produced
-- nobody. That is the strongest claim on the screen and it was made up.
--
-- v_leads_seen and v_attendance_seen mirror v_sales_seen exactly, keyed on
-- events rather than on import_batches for the same reason given there: a file
-- whose every row parked in Unmatched has been imported and has told us
-- nothing. Once one lead lands, a cut with no leads correctly reads 0 again.
--
-- The journey strip needs no change: it reads v_metrics_total, so its cards go
-- blank and its rates disappear along with the tab they summarise.
-- ═══════════════════════════════════════════════════════════════════════════

-- Has a lead ever landed for this client? Same shape and same reasoning as
-- v_sales_seen in 0008 — see the note there.
create or replace view v_leads_seen as
select distinct client_id from v_events where event_type = 'lead';

grant select on v_leads_seen to anon, authenticated;

-- Has an attendance row ever landed? Gated separately from leads, because the
-- Zoom export can be missing while the CRM export is not.
create or replace view v_attendance_seen as
select distinct client_id from v_events where event_type = 'attendance';

grant select on v_attendance_seen to anon, authenticated;

create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;

create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = c.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = c.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;

create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- 0 here means "no spend was recorded against unknown audiences", not
    -- "those leads cost nothing" — see the note above.
    case when r.ad_set = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    -- only this tab's offer carries numbers; the other is absent, not zero
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend,
         -- 0016's rule, which this view never got — see the note in By round.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = ev.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = ev.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_sales_seen s on s.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE — per-round Total still lifted whole out of By round, so the
-- two tabs cannot drift.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_source to anon, authenticated;

create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0019_stale_counts_the_gap_not_the_clock.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0019 — "Sales 0d stale" is a sentence that argues with itself.
--
-- 0014 got the RULE right: a source is stale when its coverage ends before the
-- last round that has already finished, because time passing is not evidence of
-- missing data — missing data is. Sales covers 20 May, rounds run to 27 May, so
-- 0526-03 has no sales and the flag is correct.
--
-- The header then printed that flag next to `days_since`, which counts days
-- since the file was imported. Import it this morning and the pill reads
-- "Sales 0d stale": stale, and zero days so. Two true facts about two different
-- clocks, glued into one number that means nothing. It has now sent two people
-- looking for a bug that isn't there.
--
-- days_behind is the number the sentence was always trying to say: how many
-- days of finished rounds this source says nothing about. It is exactly the
-- distance the staleness test itself measures, so the pill and the rule can no
-- longer disagree.
--
-- NULL when the source is not behind. A source that is stale only because
-- someone set stale_flag by hand has no gap to report, and the header prints
-- "Sales stale" with no number rather than inventing a zero — the same reason
-- every other absent figure on the screen reads "—".
--
-- days_since stays exactly as it was. It is a fact about the clock, it makes no
-- claim, and the Import tab still shows it as "Last import".
--
-- Appended, not replaced: create or replace view only permits adding columns at
-- the end, so days_behind goes last and every existing reader is untouched.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_import_status as
with latest as (
  -- one batch per source: the most recent one that actually landed
  select distinct on (client_id, source)
    client_id, source, imported_at, coverage_start, coverage_end,
    row_count, column_map, expected_cadence, stale_flag
  from import_batches
  where status = 'committed'
  order by client_id, source, imported_at desc
),
-- The last round that has already ended. A round still running is not evidence
-- of missing data — its files are not due yet.
horizon as (
  select client_id, max(end_date) as covered_through
  from rounds
  where end_date <= current_date
  group by client_id
)
select
  l.client_id, l.source, l.imported_at, l.coverage_start, l.coverage_end,
  l.row_count, l.column_map, l.expected_cadence,
  -- stale_flag stays respected: a batch explicitly marked stale is stale
  -- whatever the dates say.
  l.stale_flag
    or l.coverage_end is null
    or (h.covered_through is not null and l.coverage_end < h.covered_through)
    as is_stale,
  extract(day from now() - l.imported_at)::int as days_since,
  -- how far short of the finished rounds this source stops, in days
  case
    when h.covered_through is not null
     and l.coverage_end is not null
     and l.coverage_end < h.covered_through
    then (h.covered_through - l.coverage_end)::int
  end as days_behind
from latest l
left join horizon h on h.client_id = l.client_id
order by l.client_id, l.source;

grant select on v_import_status to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0020_roas_counts_only_what_ads_produced.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0020 — ROAS and CPA must divide ad spend into what advertising produced.
--
-- 0526-03 spent 1,153.22 and reported ROAS 3.62, highlighted green as a win.
-- Every cent of that round's 4,176.00 came from two AOAI members and four AI
-- Community members — people already in the room, who cost nothing to acquire.
-- Not one ad-sourced person bought in that round. The true answer is 0.00, and
-- the screen was saying the opposite as loudly as it could.
--
-- The rule already exists everywhere else. 0006 established that spend belongs
-- to Paid Ads and only to Paid Ads, which is why the AOAI column carries no
-- CPM, no CPL and no ROAS. The round tabs were the one place it was never
-- applied, so one app printed 2.07 and 0.36 for the same period on two tabs.
--
-- WHAT COUNTS AS AD-PRODUCED. Paid Ads and Previous Paid Ads — both are paid
-- leads, and on By round a Previous Paid Ads sale already lands on the round
-- whose spend produced the lead. Unattributed does NOT count: nothing evidences
-- it was paid, and this app understates rather than overstates.
--
-- CPA GOES WITH IT, by the same argument. It is ad spend divided by acquired
-- customers, and counting customers the ads did not acquire makes acquisition
-- look cheaper than it was. 0526-03 read CPA 192.20 as though advertising had
-- bought six customers. It bought none, so that cell now reads '—'.
--
-- WHAT DOES NOT CHANGE. Total Revenue, Preview/Middle Offer Revenue, the
-- purchase counts and both AOV rows still count every sale — they are facts
-- about the round, not about advertising. So ROAS can no longer be derived from
-- the revenue row above it. That is a real cost of this change, and the reason
-- the round tabs now say in words which revenue ROAS is counting.
--
-- HOW. fo_metrics is left alone — eleven views depend on it, so its signature
-- cannot change without dropping every one of them. Instead the four affected
-- keys are recomputed by one helper, in one place, and only the six views that
-- can tell paid revenue from community revenue call it. By audience and By
-- creative need no change: a person with no ad set and no creative has no
-- column there, so their revenue is already ad-only.
-- ═══════════════════════════════════════════════════════════════════════════

-- The four figures whose denominator is ad spend, recomputed against the slice
-- of revenue advertising actually produced.
--
-- Reads spend back out of the metrics object rather than taking it as its own
-- argument, so it cannot disagree with the Ads Spent row on the same screen.
-- When a cut has no ads at all, spend is NULL there and all four of these blank
-- themselves — the same behaviour as before, arrived at the same way.
create or replace function fo_paid_returns(
  m               jsonb,
  p_paid_prev_buy bigint,     -- customers advertising acquired
  p_paid_prev_rev numeric,    -- preview revenue advertising produced
  p_paid_mid_rev  numeric     -- middle revenue advertising produced
) returns jsonb
language sql
immutable
as $$
  select m || jsonb_build_object(
    'cpa',      (m->>'spend')::numeric / nullif(p_paid_prev_buy, 0),
    'prevRoas', p_paid_prev_rev / nullif((m->>'spend')::numeric, 0),
    'midRoas',  p_paid_mid_rev  / nullif((m->>'spend')::numeric, 0),
    'roas',     (p_paid_prev_rev + p_paid_mid_rev) / nullif((m->>'spend')::numeric, 0)
  );
$$;

grant execute on function fo_paid_returns(jsonb, bigint, numeric, numeric) to anon, authenticated;

create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;


create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
    -- the ad-produced slice, for ROAS and CPA (0020)
    count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_paid_returns(
    fo_metrics(
      c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
      case when c.bucket = 'Paid Ads' then ads.spend       end,
      case when c.bucket = 'Paid Ads' then ads.reach       end,
      case when c.bucket = 'Paid Ads' then ads.impressions end,
      case when c.bucket = 'Paid Ads' then ads.clicks      end,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;


create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;


create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;


create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where event_type = 'sale' and product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = c.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = c.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(ev.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.paid_mid_rev,  0) end
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;


create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_buys,
         sum(amount - coalesce(refund_amount, 0)) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      -- only this tab's offer carries numbers; the other is absent, not zero
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.paid_rev,  0) end
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0021_untracked_ads_get_one_column.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0021 — one column for the untracked ads, instead of twelve.
--
-- Twelve ads carry an ID instead of a name, because a second tracking template
-- writes {{ad.id}} where the others write {{ad.name}}. Each got its own column
-- on the Ads tab: twelve columns of dashes holding 16 leads between them, and
-- the six creatives that actually spent money were pushed off the right edge.
--
-- They are collapsed into one bucket, not deleted. Every one of those 16 leads
-- is a real person, and the tab already reads short of Total because community
-- leads have no creative — quietly dropping 16 more would widen that gap with
-- nothing on screen to explain it. There is also a finding in them: 16 leads,
-- zero attendance, zero revenue. Ads nobody can name produced nobody who came.
--
-- The bucket is keyed on the ID pattern, so an ad splits back out on its own
-- the moment Meta exports one answering to that ID. cut_sub counts them, so
-- "12 ads, no name in the export" stays true without anyone maintaining it.
--
-- Delivery and spend are blanked here for the same reason as Unsplit spend: no
-- export names these ads, so there is no spend to attribute and no reach to
-- claim. Sorting puts the bucket after the named creatives and before Unsplit.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id,
         -- twelve columns of dashes, one per untracked ad, pushed the six real
         -- creatives off the right edge. They are collapsed into one bucket and
         -- split back out on their own the moment Meta exports an ad answering
         -- to one of those IDs — nothing is thrown away to make room.
         case when ad ~ '^[0-9]+$' then '(ad ids)' else ad end as ad,
         count(distinct ad) filter (where ad ~ '^[0-9]+$')::int as id_count,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, case when ad ~ '^[0-9]+$' then '(ad ids)' else ad end
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend'
       when r.ad = '(ad ids)'  then 'Ad ID only'
       else r.ad end                                            as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad = '(ad ids)'  then r.id_count || ' ads, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad in ('(unsplit)', '(ad ids)') then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.reach       end,
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.impressions end,
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 2 when r.ad = '(ad ids)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0022_products_and_channels.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0022 — a client sells more than one thing, and buys traffic in more than
-- one place.
--
-- Both dimensions are missing entirely today. Every round belongs to a client
-- and nothing narrower, and every ads row is assumed to be Meta because Meta is
-- the only export anyone has sent. Neither assumption survives a second client.
--
-- This migration adds the two columns and backfills what is already known. It
-- deliberately changes NO metric: every view still reads the same rows, so
-- spend stays 2,447.26, leads stay 313, attendance stays 40 and revenue stays
-- 5,067.00. Wiring the filters is the next step; this one only makes the
-- dimensions exist.
--
-- ── PRODUCT hangs off the round ────────────────────────────────────────────
-- Rounds are the spine: ads point at a round, events point at a round, and both
-- offers are sold inside one. Putting the product on the round means every
-- other table inherits it for free and no existing join changes.
--
-- ── CHANNEL is not SOURCE, and the difference matters ──────────────────────
-- The app already has `source`: Paid Ads, AOAI, AI Community, Organic. That is
-- WHERE THE PERSON CAME FROM. Channel is WHERE THE MONEY WAS SPENT — Meta,
-- Google, TikTok. They are independent: a Paid Ads lead can arrive from either
-- platform, and one platform can produce both paid and organic leads.
--
-- Because the two are easy to confuse, the leads importer's alias list is
-- corrected in the same change: a column headed "channel" in a GoHighLevel
-- export used to be read as the lead's SOURCE. From here it is not read at all
-- rather than read as the wrong thing. Shely's remembered mapping uses
-- `source → source`, so nothing re-maps.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── PRODUCTS ───────────────────────────────────────────────────────────────
-- One client, many products. `ord` fixes the column order in the filter so a
-- product doesn't move sideways between page loads as rows land.
create table if not exists products (
  product_id   text primary key,
  client_id    text not null,
  product_name text not null,
  product_note text,
  ord          int  not null default 1
);

create index if not exists idx_products_client on products (client_id);

alter table products enable row level security;
drop policy if exists "demo read" on products;
create policy "demo read" on products for select using (true);
grant select on products to anon, authenticated;

-- Shely sells one thing today: the webinar that leads to the two offers. Named
-- for what it is rather than "Product 1", so a second one has to be named too.
insert into products (product_id, client_id, product_name, product_note, ord)
values ('shely-webinar', 'shely', 'Webinar → offer',
        'Live class, SGD 297 preview offer, 1,197 middle offer', 1)
on conflict (product_id) do nothing;

-- ── ROUNDS GAIN A PRODUCT ──────────────────────────────────────────────────
alter table rounds add column if not exists product_id text references products(product_id);
create index if not exists idx_rounds_product on rounds (product_id);

update rounds set product_id = 'shely-webinar'
where client_id = 'shely' and product_id is null;

-- ── ADS GAIN A CHANNEL ─────────────────────────────────────────────────────
-- No database default. A default would silently stamp 'meta' on a Google export
-- the day one arrives, which is exactly the kind of quiet wrongness the rest of
-- this app refuses. The importer decides, and says which channel it used.
alter table ads_performance add column if not exists channel text;
create index if not exists idx_ads_channel on ads_performance (channel);

-- Every existing row came out of a Meta export — that is evidenced by the
-- column map on the committed batch, not assumed.
update ads_performance set channel = 'meta' where channel is null;

-- ── CHANNEL REFERENCE ──────────────────────────────────────────────────────
-- Fixed order, same reasoning as v_source_buckets in 0006: a column that
-- appears and disappears as rows land would shove the others sideways.
create or replace view v_channels as
select * from (values
  ('meta',   1, 'Facebook and Instagram'),
  ('google', 2, 'Search, Display and YouTube'),
  ('tiktok', 3, 'TikTok'),
  ('other',  9, 'Anything else')
) as t(channel, ord, note);

grant select on v_channels to anon, authenticated;

-- ── WHAT THE APP READS ─────────────────────────────────────────────────────
-- Products a client actually has, with the round count behind each so the
-- filter can grey out one that has nothing in it yet.
create or replace view v_products as
select
  p.product_id,
  p.client_id,
  p.product_name,
  p.product_note,
  p.ord,
  count(r.round_id)::int as round_count
from products p
left join rounds r on r.product_id = p.product_id
group by p.product_id, p.client_id, p.product_name, p.product_note, p.ord
order by p.client_id, p.ord, p.product_name;

grant select on v_products to anon, authenticated;

-- Channels a client actually has spend in. Same rule: a channel with no rows
-- gets no entry, rather than a column of zeroes that were never measured.
create or replace view v_client_channels as
select
  r.client_id,
  coalesce(a.channel, 'other')     as channel,
  coalesce(c.ord, 9)               as ord,
  c.note,
  count(*)::int                    as ad_rows,
  sum(a.spend)::numeric            as spend
from ads_performance a
join rounds r     on r.round_id = a.round_id
left join v_channels c on c.channel = a.channel
group by r.client_id, coalesce(a.channel, 'other'), coalesce(c.ord, 9), c.note
order by r.client_id, coalesce(c.ord, 9);

grant select on v_client_channels to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0023_filters.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0023 — product, channel and period, applied before anything is added up.
--
-- A filter that arrives after aggregation is no filter at all: you cannot
-- average a ROAS or re-derive a cost per lead from six rounds that have already
-- been summed. So it has to bite at the bottom, on the rows.
--
-- Every metric view reads its facts through exactly two views — v_ads and
-- v_events — and the three that don't read them directly derive from ones that
-- do. Filtering there means all eleven inherit it and NOT ONE of them changes.
--
-- ── HOW THE FILTER GETS IN ────────────────────────────────────────────────
-- A view takes no arguments, so the choice travels as three transaction-local
-- settings. fo_cut() sets them and reads the view in the same transaction; the
-- `true` on set_config makes them die with that transaction, so one request can
-- never leak its filter into another.
--
-- Unset means unfiltered. Reading any of these views directly — psql, the
-- Supabase table editor, a future dashboard — behaves exactly as it did before
-- this migration, because current_setting(..., true) returns NULL when nobody
-- has set it.
--
-- ── PERIOD FILTERS ROUNDS, NOT ROWS ───────────────────────────────────────
-- The tempting version filters each row on its own date. It quietly breaks the
-- funnel: a sale on 20 May whose lead came in on 14 May would keep its revenue
-- and lose the lead that produced it, and every rate built on that pair would
-- be wrong in a way nobody could see.
--
-- So a period selects ROUNDS that overlap it, and a round brings all of its
-- rows with it. Leads, attendance and sales always travel together, which is
-- the only way the funnel stays internally consistent. Slightly generous at the
-- edges — asking for 1–15 May includes a round that ran 13–19 — and that is the
-- right trade against a funnel that silently doesn't add up.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── THE FILTER, IN ONE PLACE ───────────────────────────────────────────────
-- Two functions rather than one with a nullable channel, because NULL is not
-- "doesn't apply" in SQL — it is unknown, and `null = 'meta'` is NULL, which
-- fails the AND and silently deletes every row. That mistake removed all 313
-- leads the first time this ran. Named functions make the difference unmissable.

-- Rows that belong to a platform: ads.
create or replace function fo_filter_ok(
  p_product      text,
  p_channel      text,
  p_round_start  date,
  p_round_end    date
) returns boolean
language sql
stable
as $$
  -- Settings are read into a row first. Inline, the empty string reaches ::date
  -- before the `is null` guard can stop it — SQL does not promise to
  -- short-circuit an OR — and every read fails with "invalid input syntax for
  -- type date". nullif() has to happen before the cast.
  with f as (
    select
      nullif(current_setting('funnel.product', true), '')        as product,
      nullif(current_setting('funnel.channel', true), '')        as channel,
      nullif(current_setting('funnel.from',    true), '')::date  as from_date,
      nullif(current_setting('funnel.to',      true), '')::date  as to_date
  )
  select
      (f.product is null or p_product = f.product)
  and (f.channel is null or p_channel = f.channel)
  -- overlap, not containment: a round that started before the window and ran
  -- into it is part of that window's story
  and (f.from_date is null or p_round_end   >= f.from_date)
  and (f.to_date   is null or p_round_start <= f.to_date)
  from f;
$$;

-- Rows that belong to a person: leads, attendance, sales.
--
-- A person is not bought on a platform — their click is. Nothing in the leads
-- export says whether someone came from Meta or Google, so a channel filter
-- CANNOT narrow people, and pretending otherwise would either delete leads that
-- exist or credit them to a platform that didn't produce them. It narrows spend
-- and delivery; the screen says so.
create or replace function fo_filter_people_ok(
  p_product      text,
  p_round_start  date,
  p_round_end    date
) returns boolean
language sql
stable
as $$
  with f as (
    select
      nullif(current_setting('funnel.product', true), '')        as product,
      nullif(current_setting('funnel.from',    true), '')::date  as from_date,
      nullif(current_setting('funnel.to',      true), '')::date  as to_date
  )
  select
      (f.product is null or p_product = f.product)
  and (f.from_date is null or p_round_end   >= f.from_date)
  and (f.to_date   is null or p_round_start <= f.to_date)
  from f;
$$;

grant execute on function fo_filter_ok(text, text, date, date) to anon, authenticated;
grant execute on function fo_filter_people_ok(text, date, date) to anon, authenticated;

-- ── THE TWO VIEWS EVERYTHING READS ─────────────────────────────────────────
-- product_id and channel are exposed as columns as well as filtered on, so the
-- filter bar can show what actually exists rather than a fixed list.
-- product_id goes LAST, and channel arrives inside a.*: create or replace view
-- may only append columns, never insert one. Same reason product_id trails the
-- event columns below.
create or replace view v_ads as
select r.client_id, a.*, r.product_id
from ads_performance a
join rounds r on r.round_id = a.round_id
where fo_filter_ok(r.product_id, a.channel, r.start_date, r.end_date);

grant select on v_ads to anon, authenticated;

-- Events carry no channel of their own — a person is not bought on a platform,
-- their click is. Passing NULL means a channel filter never removes people,
-- only spend. That is deliberate: filtering to Google should not delete the
-- leads Meta produced, it should show Google's spend against no leads until
-- Google leads carry a platform of their own.
create or replace view v_events as
select
  r.client_id,
  e.event_id, e.contact_id, e.round_id, e.event_type, e.event_date,
  e.lead_round_id, e.close_round_id, e.attribution_method, e.utm_campaign,
  e.source, e.match_status, e.product, e.minutes_watched,
  e.amount, e.refund_amount, e.refund_date, e.is_lead, e.import_batch_id,
  case
    when e.source = 'Paid Ads'
     and coalesce(e.close_round_id, e.round_id) is distinct from e.lead_round_id
      then 'Previous Paid Ads'
    else e.source
  end as attribution_bucket,
  e.ad_set,
  e.ad,
  r.product_id
from events e
join rounds r on r.round_id = e.round_id
where fo_filter_people_ok(r.product_id, r.start_date, r.end_date);

grant select on v_events to anon, authenticated;

-- ── ONE WAY IN ─────────────────────────────────────────────────────────────
-- Sets the filter and reads the cut in the same transaction, returning each row
-- as jsonb so a single function serves eleven views of different shapes.
--
-- p_view is whitelisted rather than escaped. A whitelist can only ever return
-- one of eleven known views; escaping is a promise that the next person to edit
-- this has to keep.
--
-- Ordering lives here too. PostgREST does not promise a view's own ORDER BY
-- survives, and these rows arrive as opaque jsonb with nothing left to sort on,
-- so the order is applied inside and is part of the contract.
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null      -- v_metrics_by_offer only: 'preview' | 'middle'
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order text;
  v_where text := '';
begin
  v_order := case p_view
    when 'v_metrics_by_month'       then 'month_start'
    when 'v_metrics_by_round'       then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'       then 'start_date'
    when 'v_metrics_by_source'      then 'ord'
    when 'v_metrics_by_adset'       then 'ord'
    when 'v_metrics_by_ad'          then 'ord'
    when 'v_metrics_by_session'     then 'ord'
    when 'v_metrics_this_round'     then 'ord'
    when 'v_metrics_total'          then 'cut_key'
    when 'v_metrics_baseline'       then 'cut_key'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('select to_jsonb(t) from %I t where client_id = $1%s order by %s', p_view, v_where, v_order)
      using p_client, p_offer;
  else
    return query execute
      format('select to_jsonb(t) from %I t where client_id = $1 order by %s', p_view, v_order)
      using p_client;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0024_rounds_respect_the_filter.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0024 — a round outside the filter must not leave an empty column behind.
--
-- 0023 filtered the facts and forgot the frame. Six views build their columns
-- by scanning `rounds` and then left-joining the numbers onto them, so
-- filtering to 0526-03 still produced a 0526-02 column — reading leads 0,
-- attendance 0, revenue 0.
--
-- Those zeroes are the exact lie the rest of this app is built to refuse. A
-- measured zero says "we looked and there was nothing". These say "this round
-- is not in the window you asked for", which is a different fact, and the
-- screen had no way to tell them apart.
--
-- v_rounds carries the same filter as v_ads and v_events, and the six views
-- read it instead of the table. A round outside the period now has no column at
-- all, which is the honest answer — and a round INSIDE the period with no data
-- yet still gets its column of dashes, which is the other honest answer, and
-- the two stop being the same picture.
--
-- Deliberately the PEOPLE filter, not the ads one: a round does not belong to a
-- channel. Filtering to Google narrows spend and leaves every round standing,
-- which is what the bar says it does.
--
-- Everything else that reads `rounds` is left alone on purpose — the staleness
-- horizon in v_import_status asks "what is the last round that ended", and that
-- question has nothing to do with what anyone is looking at.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_rounds as
select * from rounds
where fo_filter_people_ok(product_id, start_date, end_date);

grant select on v_rounds to anon, authenticated;

create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from v_rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;


create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from v_rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;


create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from v_rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;


create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_buys,
         sum(amount - coalesce(refund_amount, 0)) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      -- only this tab's offer carries numbers; the other is absent, not zero
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.paid_rev,  0) end
  ) as m
from v_rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;


create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
    -- the ad-produced slice, for ROAS and CPA (0020)
    count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_paid_returns(
    fo_metrics(
      c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
      case when c.bucket = 'Paid Ads' then ads.spend       end,
      case when c.bucket = 'Paid Ads' then ads.reach       end,
      case when c.bucket = 'Paid Ads' then ads.impressions end,
      case when c.bucket = 'Paid Ads' then ads.clicks      end,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from cells c
join v_rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;


create or replace view v_metrics_this_round as
select
  client_id, cut_key, cut_label, cut_sub, start_date, m,
  case when rn = 1 then 'this round' else 'previous' end as period,
  rn::int as ord
from (
  select b.*, row_number() over (partition by b.client_id order by b.start_date desc) as rn
  from v_metrics_by_round b
  join v_rounds r on r.round_id = b.cut_key
  where r.start_date <= current_date
) ranked
where rn <= 2
order by client_id, start_date;

grant select on v_metrics_this_round to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0025_sessions_and_weeks.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0025 — a round holds however many classes it holds, and weeks always exist.
--
-- Two changes that belong together, because they answer the same problem: the
-- class schedule is not predictable. Some months run four rounds, some run
-- none, and a round can run one class or several.
--
-- ── SESSIONS ──────────────────────────────────────────────────────────────
-- rounds.session_date has been a single date since 0001, where the comment
-- said: "1:1 with round today. If a client needs 1:many later, split into a
-- sessions table." A round that runs classes on the 5th and the 7th has nowhere
-- to put the second one, so it is invented here rather than assumed away.
--
-- The old columns are NOT dropped. Every existing row is copied into the new
-- table and the columns stay as they were, so nothing that still reads them
-- breaks mid-migration. They stop being the source of truth, not the truth.
--
-- ── ONE LABEL PER ROUND, OR AN HONEST ADMISSION ───────────────────────────
-- Attend class compares class FORMATS, so the label belongs to the session, not
-- the round. That creates a case that didn't exist before: a round whose
-- sessions carry two different labels. Its attendance is recorded against the
-- round, not the session, so it cannot be split between them.
--
-- Rather than pick one or count it twice, such a round reports '(mixed)'. The
-- number stays right and the screen says why it can't be broken down — the
-- alternative is a Class A column quietly containing Class B's attendees.
--
-- ── WEEKS ─────────────────────────────────────────────────────────────────
-- Rounds only exist when someone runs one; weeks are always there. A week view
-- gives every chart and comparison a spine that doesn't disappear in a quiet
-- month, and it is By month with one word changed — a round belongs to the week
-- it STARTED in, for the same reason it belongs to the month it started in:
-- splitting it would put the spend in one column and the class that spend paid
-- for in the next.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists round_sessions (
  session_id    text primary key,
  round_id      text not null references rounds(round_id) on delete cascade,
  session_date  date not null,
  session_label text,
  ord           int  not null default 1
);

create index if not exists idx_round_sessions_round on round_sessions (round_id);
create index if not exists idx_round_sessions_date  on round_sessions (session_date);

alter table round_sessions enable row level security;
drop policy if exists "demo read" on round_sessions;
create policy "demo read" on round_sessions for select using (true);
grant select on round_sessions to anon, authenticated;

-- Carry every existing class across. A round with no session_date has no class
-- recorded, which is a fact about the data and not a reason to invent one.
insert into round_sessions (session_id, round_id, session_date, session_label, ord)
select r.round_id || '·1', r.round_id, r.session_date, r.session_label, 1
from rounds r
where r.session_date is not null
on conflict (session_id) do nothing;

-- ── WHAT THE APP READS ─────────────────────────────────────────────────────
-- Sessions of rounds that survive the current filter, so a class outside the
-- period disappears with its round.
create or replace view v_round_sessions as
select s.session_id, s.round_id, r.client_id, r.product_id,
       s.session_date, s.session_label, s.ord
from round_sessions s
join v_rounds r on r.round_id = s.round_id;

grant select on v_round_sessions to anon, authenticated;

-- One row per round: its class label, or '(mixed)' when it ran more than one
-- and its attendance cannot be attributed between them.
create or replace view v_round_labels as
select
  s.round_id,
  s.client_id,
  case
    when count(distinct coalesce(nullif(btrim(s.session_label), ''), '(unlabelled)')) = 1
      then max(coalesce(nullif(btrim(s.session_label), ''), '(unlabelled)'))
    else '(mixed)'
  end                                as label,
  count(*)::int                      as session_count,
  min(s.session_date)                as first_session,
  max(s.session_date)                as last_session
from v_round_sessions s
group by s.round_id, s.client_id;

grant select on v_round_labels to anon, authenticated;

create or replace view v_metrics_by_week as
with weeks as (
  select client_id, date_trunc('week', start_date)::date as week_start,
         count(*)::int as round_count
  from v_rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.week_start, 'IYYY-"W"IW')       as cut_key,
  to_char(m.week_start, 'DD Mon') || ' – ' || to_char(m.week_start + 6, 'DD Mon') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.week_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from weeks m
left join ads   on ads.client_id   = m.client_id and ads.week_start   = m.week_start
left join ev    on ev.client_id    = m.client_id and ev.week_start    = m.week_start
left join sales on sales.client_id = m.client_id and sales.week_start = m.week_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.week_start;

grant select on v_metrics_by_week to anon, authenticated;
create or replace view v_metrics_by_session as
with labels as (
  -- the label is the SESSION's now, and a round that ran two different formats
  -- reports '(mixed)' rather than being counted under either — see 0025
  select r.client_id, rl.label,
         count(*)::int as round_count, min(r.start_date) as first_start
  from v_rounds r join v_round_labels rl on rl.round_id = r.round_id
  group by 1, 2
),
ads as (
  select r.client_id, rl.label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id
       join v_round_labels rl on rl.round_id = r.round_id group by 1, 2
),
ev as (
  select r.client_id, rl.label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id
       join v_round_labels rl on rl.round_id = r.round_id group by 1, 2
),
sales as (
  select r.client_id, rl.label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
       join v_round_labels rl on rl.round_id = r.round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;
-- ── fo_cut learns the week ────────────────────────────────────────────────
-- The whitelist is the only thing standing between p_view and dynamic SQL, so
-- a new cut is a new line here rather than a looser check.
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null      -- v_metrics_by_offer only: 'preview' | 'middle'
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order text;
  v_where text := '';
begin
  v_order := case p_view
    when 'v_metrics_by_month'       then 'month_start'
    when 'v_metrics_by_week'        then 'week_start'
    when 'v_metrics_by_round'       then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'       then 'start_date'
    when 'v_metrics_by_source'      then 'ord'
    when 'v_metrics_by_adset'       then 'ord'
    when 'v_metrics_by_ad'          then 'ord'
    when 'v_metrics_by_session'     then 'ord'
    when 'v_metrics_this_round'     then 'ord'
    when 'v_metrics_total'          then 'cut_key'
    when 'v_metrics_baseline'       then 'cut_key'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('select to_jsonb(t) from %I t where client_id = $1%s order by %s', p_view, v_where, v_order)
      using p_client, p_offer;
  else
    return query execute
      format('select to_jsonb(t) from %I t where client_id = $1 order by %s', p_view, v_order)
      using p_client;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0026_cadence_belongs_to_the_product.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0026 — a campaign runs by week or by round, and that is a property of the
-- thing being sold, not a decision the app gets to make once.
--
-- 0025 built the week cut, and then the By week TAB was removed on the grounds
-- that Shely runs in rounds and every one of her weeks holds exactly one round.
-- Both halves of that were true and the conclusion was still wrong: deleting
-- the tab moved a per-client fact into the source code, where the next client
-- cannot change it. A workshop that runs in rounds and an evergreen funnel that
-- runs continuously are both normal, and one of them has no rounds to report.
--
-- So cadence becomes data. Each product says how its campaigns run, the sidebar
-- offers the spine that product actually has, and neither answer is compiled in:
--
--   cadence = 'round'  →  By round.  Rounds are the unit; weeks would repeat it.
--   cadence = 'week'   →  By week.   Traffic is continuous; there is no round.
--
-- With no product filter set, a client selling both gets both tabs, because at
-- that point both are true at once.
--
-- Default is 'round' because every product in this database today is one, and a
-- default that matches the existing rows is the only one that changes nothing.
--
-- ── AND THE PRODUCT GETS ITS REAL NAME ────────────────────────────────────
-- 0022 seeded it as 'Webinar → offer', which describes the JOURNEY SHAPE, not
-- the product. The thing Shely sells is the Memi AI Workshop — that is the name
-- on the creative, the name the client uses, and the name a supervisor reading
-- the filter will be looking for. 'Webinar → offer' stays as the client_note,
-- where a journey description belongs.
--
-- Changes no metric. Spend stays 2,447.26, leads 313, attendance 40,
-- revenue 5,067.00.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── CADENCE ────────────────────────────────────────────────────────────────
alter table products add column if not exists cadence text not null default 'round';

-- Constrained, because a typo here silently removes a client's only Overview
-- tab — the sidebar would just be missing an entry, with nothing to say why.
alter table products drop constraint if exists products_cadence_check;
alter table products add constraint products_cadence_check
  check (cadence in ('round', 'week'));

-- ── THE PRODUCT'S REAL NAME ────────────────────────────────────────────────
update products
set product_name = 'Memi AI Workshop',
    product_note = 'Live webinar → SGD 297 preview offer → SGD 1,197 middle offer'
where product_id = 'shely-webinar';

-- ── WHAT THE APP READS ─────────────────────────────────────────────────────
-- cadence is appended LAST. `create or replace view` may add columns to the end
-- and may not insert, rename or reorder them — putting it anywhere else fails
-- with "cannot change name of view column", which is how 0022 learned this.
create or replace view v_products as
select
  p.product_id,
  p.client_id,
  p.product_name,
  p.product_note,
  p.ord,
  count(r.round_id)::int as round_count,
  p.cadence
from products p
left join rounds r on r.product_id = p.product_id
group by p.product_id, p.client_id, p.product_name, p.product_note, p.ord, p.cadence
order by p.client_id, p.ord, p.product_name;

grant select on v_products to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0027_two_numbers_nobody_measured.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0027 — two numbers nobody measured, both found by the imaginary product.
--
-- A second product was loaded to prove the Product and Channel filters narrow
-- anything, which one option can never prove. It did that, and it also exposed
-- two figures the app was printing as if they had been observed. Neither was
-- reachable with a single product on a single platform, which is exactly why
-- they survived this long.
--
-- ── 1. ATTENDANCE READ 0 FOR A CLASS THAT NEVER HAPPENED ──────────────────
-- The same round reported two different things depending on the filter:
--
--     DEMO-W1, no product filter   ->  attendance 0
--     DEMO-W1, filtered to it      ->  attendance —
--
-- The gate asks "does this CLIENT report attendance at all?". With the filter
-- off, Shely does — the workshop's 40 — so the gate opens and an evergreen
-- round with no class reports a measured zero. Nobody measured it. There was
-- no class to attend.
--
-- Fixed by requiring both: the client reports attendance AND the rounds in this
-- bucket actually held a class. round_sessions has said which since 0025, so
-- the question is now answerable where before it was not. Strictly more blanks
-- and never fewer — a round that held a class and drew nobody still reads 0,
-- because that zero was observed.
--
-- v_metrics_this_round needs no change: it reads v_metrics_by_round.
--
-- ── 2. FILTERING BY CHANNEL INVENTED ROAS ─────────────────────────────────
-- Revenue carries no platform. Sales and leads arrive from GoHighLevel and
-- Zoom, which do not know whether the ad was on Meta or Google, so a channel
-- filter narrows spend and leaves revenue whole — deliberately, and the filter
-- bar says so. What it did not say is what happens to everything DERIVED from
-- the two together. On the demo product:
--
--     meta      spend 1,200   rev 2,376   ROAS 1.98
--     google    spend   800   rev 2,376   ROAS 2.97
--     truth     spend 2,000   rev 2,376   ROAS 1.19
--
-- Each channel is credited with all of the revenue, so both beat the blended
-- figure and neither is real. Someone reads 2.97 and moves budget to Google.
--
-- Every ratio that divides an unattributed numerator by channel-scoped spend
-- now goes blank while a channel filter is on: roas, prevRoas, midRoas, cpa,
-- cpl, cpAtt, and leadgen (leads per click — clicks are per-channel, leads are
-- not). Nothing else changes. spend, impressions, reach, clicks, ctr, cpm, cpc
-- and frequency are all ads-side and all correctly narrowed. Revenue, leads,
-- attendance and the rates BETWEEN them are unattributed on both sides of the
-- division, so a channel filter leaves them alone.
--
-- Done in fo_cut rather than in twelve views: it is the one door every read
-- goes through, and it already knows what the filter is set to.
--
-- Changes nothing with no channel filter set. Shely's unfiltered numbers stay
-- spend 2,447.26, leads 313, attendance 40, revenue 5,067.00.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 1. ATTENDANCE ──────────────────────────────────────────────────────────

create or replace view v_metrics_by_round as
with cls as (
  -- classes actually recorded against each round. A round with none had no
  -- class, so its attendance was never measured and must not read 0.
  select client_id, round_id, count(*) as sessions
  from v_round_sessions group by client_id, round_id
),
ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from v_rounds r
left join cls   on cls.client_id = r.client_id and cls.round_id = r.round_id
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;

create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from v_rounds group by 1, 2
),
cls as (
  -- see v_metrics_by_round: a month whose rounds held no class has no
  -- attendance to report, as distinct from having had nobody turn up.
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) as sessions
  from v_round_sessions s join v_rounds r on r.round_id = s.round_id
  group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from months m
left join cls   on cls.client_id   = m.client_id and cls.month_start   = m.month_start
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

create or replace view v_metrics_by_week as
with weeks as (
  select client_id, date_trunc('week', start_date)::date as week_start,
         count(*)::int as round_count
  from v_rounds group by 1, 2
),
cls as (
  -- see v_metrics_by_round: a week whose rounds held no class has no
  -- attendance to report, as distinct from having had nobody turn up.
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         count(*) as sessions
  from v_round_sessions s join v_rounds r on r.round_id = s.round_id
  group by 1, 2
),
ads as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join v_rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('week', r.start_date)::date as week_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.week_start, 'IYYY-"W"IW')       as cut_key,
  to_char(m.week_start, 'DD Mon') || ' – ' || to_char(m.week_start + 6, 'DD Mon') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.week_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from weeks m
left join cls   on cls.client_id   = m.client_id and cls.week_start   = m.week_start
left join ads   on ads.client_id   = m.client_id and ads.week_start   = m.week_start
left join ev    on ev.client_id    = m.client_id and ev.week_start    = m.week_start
left join sales on sales.client_id = m.client_id and sales.week_start = m.week_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.week_start;

grant select on v_metrics_by_week to anon, authenticated;

create or replace view v_metrics_by_round_source as
with cls as (
  -- see v_metrics_by_round. The round decides this, not the source: a source
  -- cannot have brought people to a class that never happened.
  select client_id, round_id, count(*) as sessions
  from v_round_sessions group by client_id, round_id
),
ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
    -- the ad-produced slice, for ROAS and CPA (0020)
    count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_paid_returns(
    fo_metrics(
      c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
      case when c.bucket = 'Paid Ads' then ads.spend       end,
      case when c.bucket = 'Paid Ads' then ads.reach       end,
      case when c.bucket = 'Paid Ads' then ads.impressions end,
      case when c.bucket = 'Paid Ads' then ads.clicks      end,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from cells c
join v_rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join cls
  on cls.client_id = c.client_id and cls.round_id = c.round_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;

-- ── 2. CHANNEL-BLIND RATIOS ────────────────────────────────────────────────
-- Returns the metric object with every channel-incoherent ratio removed, or
-- unchanged when no channel filter is set.
--
-- Setting a key to null rather than dropping it is deliberate: the spine renders
-- a null as a dash and a missing key as nothing at all, and a row that silently
-- loses its label reads as a rendering bug rather than as an honest blank.
create or replace function fo_channel_blind(m jsonb)
returns jsonb
language sql
immutable
as $$
  select case
    when nullif(current_setting('funnel.channel', true), '') is null then m
    else m
      || jsonb_build_object(
           'roas',     null,   -- revenue ÷ this channel's spend
           'prevRoas', null,
           'midRoas',  null,
           'cpa',      null,   -- this channel's spend ÷ all buyers
           'cpl',      null,   -- this channel's spend ÷ all leads
           'cpAtt',    null,   -- this channel's spend ÷ all attendees
           'leadgen',  null    -- all leads ÷ this channel's clicks
         )
  end;
$$;

grant execute on function fo_channel_blind(jsonb) to anon, authenticated;

-- ── ONE WAY IN, NOW ALSO THE ONE PLACE THAT BLANKS ─────────────────────────
-- Unchanged from 0025 except for the jsonb_set on the way out.
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null      -- v_metrics_by_offer only: 'preview' | 'middle'
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order text;
  v_where text := '';
  v_sel   text := 'select jsonb_set(to_jsonb(t), ''{m}'', fo_channel_blind(to_jsonb(t)->''m''))';
begin
  v_order := case p_view
    when 'v_metrics_by_month'       then 'month_start'
    when 'v_metrics_by_week'        then 'week_start'
    when 'v_metrics_by_round'       then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'       then 'start_date'
    when 'v_metrics_by_source'      then 'ord'
    when 'v_metrics_by_adset'       then 'ord'
    when 'v_metrics_by_ad'          then 'ord'
    when 'v_metrics_by_session'     then 'ord'
    when 'v_metrics_this_round'     then 'ord'
    when 'v_metrics_total'          then 'cut_key'
    when 'v_metrics_baseline'       then 'cut_key'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('%s from %I t where client_id = $1%s order by %s', v_sel, p_view, v_where, v_order)
      using p_client, p_offer;
  else
    return query execute
      format('%s from %I t where client_id = $1 order by %s', v_sel, p_view, v_order)
      using p_client;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0028_blank_only_when_the_filter_took_something.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0028 — blank the channel ratios only when the channel filter removed spend.
--
-- 0027 blanked ROAS, CPA, CPL and Lead gen % whenever ANY channel was selected.
-- The reasoning held — revenue carries no platform, so dividing all of it by
-- one channel's spend credits that channel with the other's results — but the
-- rule was blunter than the reasoning, and it showed the moment it met the real
-- account:
--
--     workshop, no channel    spend 2,447.26 | ROAS 0.364  CPA 815.75  CPL 7.82
--     workshop, channel=meta  spend 2,447.26 | ROAS —      CPA —       CPL —
--
-- Identical spend. The workshop only ever ran on Meta, so filtering to Meta
-- removed nothing, and four correct numbers vanished for no reason. That is its
-- own kind of dishonesty: a blank claims "this cannot be known", and here it
-- could.
--
-- The test is now whether the filter actually took something — more than one
-- channel with spend inside the CURRENT scope, which means product and period
-- count too. Filter the account to May, when only Meta ran, and the ratios come
-- back even though June has Google in it. Ask for all products across all time
-- with Meta selected, and they blank, because Google's spend really was removed
-- while its revenue stayed.
--
-- The count deliberately ignores channels with no spend: a channel that never
-- cost anything cannot have been subtracted.
--
-- fo_channel_blind loses its current_setting() lookup and becomes what its name
-- says — a function that removes four ratios from a metric object. WHETHER to
-- call it is fo_cut's decision, which is where the filter is known. Being
-- genuinely immutable now, rather than immutable-but-reading-a-GUC, is a
-- correctness fix in its own right: the planner was within its rights to fold a
-- call that quietly depended on session state.
--
-- Costs one extra query per read, and only when a channel is selected.
-- Changes nothing when no channel filter is set.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── THE RATIOS THAT CANNOT SURVIVE A CHANNEL SPLIT ─────────────────────────
-- Each one divides something unattributed by something channel-scoped. Nulled
-- rather than dropped, so the spine renders a dash instead of losing the row.
create or replace function fo_channel_blind(m jsonb)
returns jsonb
language sql
immutable
as $$
  select m || jsonb_build_object(
    'roas',     null,   -- all revenue ÷ one channel's spend
    'prevRoas', null,
    'midRoas',  null,
    'cpa',      null,   -- one channel's spend ÷ all buyers
    'cpl',      null,   -- one channel's spend ÷ all leads
    'cpAtt',    null,   -- one channel's spend ÷ all attendees
    'leadgen',  null    -- all leads ÷ one channel's clicks
  );
$$;

grant execute on function fo_channel_blind(jsonb) to anon, authenticated;

-- ── ONE WAY IN ─────────────────────────────────────────────────────────────
-- Unchanged from 0027 except that the blanking is now conditional.
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null      -- v_metrics_by_offer only: 'preview' | 'middle'
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order  text;
  v_where  text := '';
  v_sel    text;
  v_shared int;
begin
  v_order := case p_view
    when 'v_metrics_by_month'       then 'month_start'
    when 'v_metrics_by_week'        then 'week_start'
    when 'v_metrics_by_round'       then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'       then 'start_date'
    when 'v_metrics_by_source'      then 'ord'
    when 'v_metrics_by_adset'       then 'ord'
    when 'v_metrics_by_ad'          then 'ord'
    when 'v_metrics_by_session'     then 'ord'
    when 'v_metrics_this_round'     then 'ord'
    when 'v_metrics_total'          then 'cut_key'
    when 'v_metrics_baseline'       then 'cut_key'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  -- Did selecting this channel actually take spend away? Counted with the
  -- channel setting momentarily cleared, so v_ads answers for the whole
  -- product-and-period scope rather than for the one channel already chosen.
  -- Transaction-local, and put straight back.
  v_sel := 'select to_jsonb(t)';
  if p_channel is not null then
    perform set_config('funnel.channel', '', true);
    select count(distinct coalesce(channel, 'other'))
      into v_shared
      from v_ads
     where client_id = p_client
       and coalesce(spend, 0) <> 0;
    perform set_config('funnel.channel', p_channel, true);

    if coalesce(v_shared, 0) > 1 then
      v_sel := 'select jsonb_set(to_jsonb(t), ''{m}'', fo_channel_blind(to_jsonb(t)->''m''))';
    end if;
  end if;

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('%s from %I t where client_id = $1%s order by %s', v_sel, p_view, v_where, v_order)
      using p_client, p_offer;
  else
    return query execute
      format('%s from %I t where client_id = $1 order by %s', v_sel, p_view, v_order)
      using p_client;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0029_what_the_round_can_be_asked.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0029 — the three things "This round" needs and cannot currently ask for.
--
-- The CRO process compares a round against the previous one, against the month
-- to date, and against a TARGET, then asks what changed upstream to explain any
-- metric that moved. Two of those three the app can already answer. This adds
-- the missing pieces, and adds nothing else — no metric changes here.
--
-- ── 1. HOW FAR THROUGH THE ROUND IS ────────────────────────────────────────
-- v_metrics_this_round carries start_date and not end_date, so the screen can
-- say which round is running and not whether it is on day 2 or day 12. "CPL is
-- 7.83" means something different on each, and a round two days old should not
-- be judged at all. end_date is appended — `create or replace view` may add
-- columns at the end and may not insert them.
--
-- ── 2. A TARGET TO COMPARE AGAINST ─────────────────────────────────────────
-- "Comparisons are against previous months/rounds/weeks & target." There is no
-- target anywhere in this database, and there never has been — the project note
-- has said "no objective is set" since the first sprint. So the table is
-- created EMPTY. Not seeded with a guess, not defaulted to last round's number:
-- a target nobody set is not a target, and a screen that invents one teaches
-- people to trust invented numbers.
--
-- Until a row exists the screen says which metrics have no target and compares
-- against the previous round and the all-round baseline instead, saying so.
-- Setting one is a single INSERT, the same way unit prices are set.
--
-- ── 3. WHAT CHANGED UPSTREAM ───────────────────────────────────────────────
-- Step 3 of the process asks, when a rate falls: was there a new ad, did the
-- budget split move, did targeting change. All three are answerable from what
-- is already imported — they are questions about which audiences and creatives
-- carried money in this round versus the one before. v_round_assets puts one
-- row per round per asset so the two rounds can be diffed.
--
-- It deliberately does NOT answer "did the landing page change". No
-- landing-page dimension exists (the LP tab has been parked for that reason
-- since 0015), and Clarity data covers no round in this database. That question
-- stays unanswered and the screen says so rather than quietly dropping it.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 1. END DATE ────────────────────────────────────────────────────────────
create or replace view v_metrics_this_round as
select
  client_id, cut_key, cut_label, cut_sub, start_date, m,
  case when rn = 1 then 'this round' else 'previous' end as period,
  rn::int as ord,
  end_date
from (
  select b.*, r.end_date,
         row_number() over (partition by b.client_id order by b.start_date desc) as rn
  from v_metrics_by_round b
  join v_rounds r on r.round_id = b.cut_key
  where r.start_date <= current_date
) ranked
where rn <= 2
order by client_id, start_date;

grant select on v_metrics_this_round to anon, authenticated;

-- ── 2. TARGETS ─────────────────────────────────────────────────────────────
-- One row per metric a client has actually agreed a number for. `metric` is a
-- spine key ('cpl', 'attPct', 'roas', …) so the screen can look a target up by
-- the same name it renders the row under.
create table if not exists client_targets (
  client_id text    not null,
  metric    text    not null,
  target    numeric not null,
  note      text,                       -- who set it and when, in words
  primary key (client_id, metric)
);

alter table client_targets enable row level security;
drop policy if exists "demo read" on client_targets;
create policy "demo read" on client_targets for select using (true);
grant select on client_targets to anon, authenticated;

create or replace view v_client_targets as
select client_id, metric, target, note from client_targets;

grant select on v_client_targets to anon, authenticated;

-- Intentionally no INSERT. See the header.

-- ── 3. WHAT CARRIED MONEY, PER ROUND ───────────────────────────────────────
-- Audiences and creatives side by side, one row each per round, with the share
-- of that round's spend. Share is what makes "budget distribution changed"
-- answerable: an audience holding 12% of a round and 34% of the next one is a
-- redistribution even when neither amount looks unusual on its own.
--
-- Leads are joined on because an asset that took money and returned nothing is
-- the case worth surfacing, and it cannot be seen from spend alone.
create or replace view v_round_assets as
with spend as (
  select r.client_id, a.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(a.ad_set), ''), '(unsplit)') as name,
         sum(a.spend) as spend
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
  union all
  select r.client_id, a.round_id, 'creative',
         coalesce(nullif(btrim(a.ad), ''), '(unsplit)'),
         sum(a.spend)
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
),
got as (
  select r.client_id, e.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(e.ad_set), ''), '(unsplit)') as name,
         count(*) as leads
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
  union all
  select r.client_id, e.round_id, 'creative',
         coalesce(nullif(btrim(e.ad), ''), '(unsplit)'),
         count(*)
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
),
joined as (
  select
    coalesce(s.client_id, g.client_id) as client_id,
    coalesce(s.round_id,  g.round_id)  as round_id,
    coalesce(s.kind,      g.kind)      as kind,
    coalesce(s.name,      g.name)      as name,
    s.spend,
    g.leads
  from spend s
  full outer join got g
    on  g.client_id = s.client_id and g.round_id = s.round_id
    and g.kind = s.kind           and g.name    = s.name
)
select
  client_id, round_id, kind, name,
  spend,
  coalesce(leads, 0)::int as leads,
  -- share of the round's spend, in percent. Null when the round has no spend at
  -- all — a share of nothing is not zero percent, it is nothing.
  round(
    100 * spend / nullif(sum(spend) over (partition by client_id, round_id, kind), 0),
    1
  ) as spend_share
from joined
order by client_id, round_id, kind, spend desc nulls last, name;

grant select on v_round_assets to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0030_the_round_diff_reads_the_named_assets.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0030 — step 3 was reporting twelve changes that are one tracking fault.
--
-- The first look at "This round" against real data showed this under "what
-- changed upstream":
--
--     added    120248589768770425   new this round · 1 lead
--     added    120248589768820425   new this round · 1 lead
--     added    120249100531290425   new this round · 2 leads
--     … nine of them, then three more dropped …
--     reweighted  Static_ContentAtScale_StructuredText  88.5% → 35.4%
--
-- Every one of those numbers is an untracked ad. A second GoHighLevel tracking
-- template writes {{ad.id}} where the others write the ad's name, so those
-- leads carry an ID that appears in no Meta export — which is why they have no
-- spend, and why they look "new" in any round where a different set of them
-- happened to fire. 0021 already collapsed them into one column on the Ads tab
-- for exactly this reason; v_round_assets was written afterwards and read the
-- raw column, so the same fault came back on a different screen.
--
-- Twelve lines of noise pushed the one real change — an audience going from 88%
-- of the round's spend to 35% — to the bottom of the list. A diff that reports
-- everything reports nothing.
--
-- They are bucketed, not dropped: those leads are real people, and '(ad ids)'
-- appearing or disappearing is still a fact about the round. It is now one line
-- carrying its own count instead of nine lines carrying one lead each.
--
-- Changes no metric. This view feeds one screen and no total.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_round_assets as
with named as (
  -- One name for every creative whose utm_content was an ID rather than a name.
  -- Same test as 0021: all digits, nothing else.
  select r.client_id, a.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(a.ad_set), ''), '(unsplit)') as name,
         sum(a.spend) as spend, 0 as ids
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
  union all
  select r.client_id, a.round_id, 'creative',
         case when btrim(a.ad) ~ '^[0-9]+$' then '(ad ids)'
              else coalesce(nullif(btrim(a.ad), ''), '(unsplit)') end,
         sum(a.spend),
         count(distinct a.ad) filter (where btrim(a.ad) ~ '^[0-9]+$')::int
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
),
got as (
  select r.client_id, e.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(e.ad_set), ''), '(unsplit)') as name,
         count(*) as leads, 0 as ids
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
  union all
  select r.client_id, e.round_id, 'creative',
         case when btrim(e.ad) ~ '^[0-9]+$' then '(ad ids)'
              else coalesce(nullif(btrim(e.ad), ''), '(unsplit)') end,
         count(*),
         count(distinct e.ad) filter (where btrim(e.ad) ~ '^[0-9]+$')::int
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
),
joined as (
  select
    coalesce(s.client_id, g.client_id) as client_id,
    coalesce(s.round_id,  g.round_id)  as round_id,
    coalesce(s.kind,      g.kind)      as kind,
    coalesce(s.name,      g.name)      as name,
    s.spend,
    g.leads,
    greatest(coalesce(s.ids, 0), coalesce(g.ids, 0)) as ids
  from named s
  full outer join got g
    on  g.client_id = s.client_id and g.round_id = s.round_id
    and g.kind = s.kind           and g.name    = s.name
)
select
  client_id, round_id, kind, name,
  spend,
  coalesce(leads, 0)::int as leads,
  round(
    100 * spend / nullif(sum(spend) over (partition by client_id, round_id, kind), 0),
    1
  ) as spend_share,
  -- how many untracked ads the '(ad ids)' row stands for, so the screen can say
  -- so rather than presenting a bucket as if it were one creative
  nullif(ids, 0) as id_count
from joined
order by client_id, round_id, kind, spend desc nulls last, name;

grant select on v_round_assets to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0031_the_journey_strip_respects_the_filter.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0031 — the journey strip was showing unfiltered numbers above filtered tables.
--
-- Found by reading the deployed page with a product filter set. The URL said
-- Memi AI Workshop, the table said 313 leads, and the strip four inches above it
-- said 393:
--
--     strip    impressions 91,360 · clicks 1,632 · leads 393 · preview 17
--     table    impressions 51,360 · clicks   832 · leads 313 · preview  9
--
-- v_journey_strip is not the problem — it reads v_metrics_total, which is
-- filter-aware. The problem is HOW it was read. Every other number on the page
-- goes through fo_cut, which sets the filter and reads the view inside one
-- transaction. The strip was fetched straight from PostgREST, so the settings
-- fo_cut would have set were never set, and every read got the unfiltered total.
--
-- One read path or none. The view is added to fo_cut's whitelist and the app
-- switches to it.
--
-- ── AND THE RATES HAVE TO BE BLINDED WITH EVERYTHING ELSE ──────────────────
-- 0028 blanks ROAS, CPL and Lead gen % when a channel filter removes spend that
-- the revenue and leads keep. Those blanks are applied to the `m` object on the
-- way out of fo_cut — and the strip carried its own flattened `value` and `rate`
-- columns, which nothing would have blinded. Fixing only the filter would have
-- left the strip showing a channel-incoherent Lead Gen % directly above a table
-- that blanks it.
--
-- So the strip now also carries `m`, and the app derives the card from that —
-- the same object, through the same door, blinded by the same rule. The old
-- flat columns stay because `create or replace view` cannot drop them; nothing
-- reads them.
--
-- ── A VIEW WITHOUT AN `m` COLUMN MUST NOT BE WIPED ─────────────────────────
-- fo_cut's blinding did `jsonb_set(to_jsonb(t), '{m}', …)` unconditionally.
-- jsonb_set returns NULL when its new value is NULL, so pointing fo_cut at any
-- view with no `m` column would have returned a set of NULLs rather than an
-- error — rows silently vanishing instead of failing loudly. Guarded here
-- before a future view finds it the hard way.
--
-- Changes no metric.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── THE STRIP CARRIES THE WHOLE METRIC OBJECT ──────────────────────────────
create or replace view v_journey_strip as
select
  j.client_id, j.stage_order, j.stage_name, j.stage_slug, j.stage_rate_label,
  case j.stage_metric
    when 'impressions'       then (t.m->>'impr')
    when 'clicks'            then (t.m->>'clicks')
    when 'leads'             then (t.m->>'leads')
    when 'attendance'        then (t.m->>'att')
    when 'preview_purchases' then (t.m->>'prevBuy')
    when 'middle_purchases'  then (t.m->>'midBuy')
  end as value,
  case j.stage_metric
    when 'clicks'            then (t.m->>'ctr')
    when 'leads'             then (t.m->>'leadgen')
    when 'attendance'        then (t.m->>'attPct')
    when 'preview_purchases' then (t.m->>'prevPct')
    when 'middle_purchases'  then (t.m->>'midPct')
  end as rate,
  -- appended: which metric this card is for, and the object it comes from
  j.stage_metric,
  t.m
from v_journey j
left join v_metrics_total t on t.client_id = j.client_id
order by j.client_id, j.stage_order;

grant select on v_journey_strip to anon, authenticated;

-- ── ONE WAY IN, AND IT NOW SERVES THE STRIP TOO ────────────────────────────
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null      -- v_metrics_by_offer only: 'preview' | 'middle'
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order  text;
  v_where  text := '';
  v_sel    text;
  v_shared int;
begin
  v_order := case p_view
    when 'v_metrics_by_month'       then 'month_start'
    when 'v_metrics_by_week'        then 'week_start'
    when 'v_metrics_by_round'       then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'       then 'start_date'
    when 'v_metrics_by_source'      then 'ord'
    when 'v_metrics_by_adset'       then 'ord'
    when 'v_metrics_by_ad'          then 'ord'
    when 'v_metrics_by_session'     then 'ord'
    when 'v_metrics_this_round'     then 'ord'
    when 'v_metrics_total'          then 'cut_key'
    when 'v_metrics_baseline'       then 'cut_key'
    when 'v_journey_strip'          then 'stage_order'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  -- Did selecting this channel actually take spend away? Counted with the
  -- channel setting momentarily cleared, and put straight back.
  v_sel := 'select to_jsonb(t)';
  if p_channel is not null then
    perform set_config('funnel.channel', '', true);
    select count(distinct coalesce(channel, 'other'))
      into v_shared
      from v_ads
     where client_id = p_client
       and coalesce(spend, 0) <> 0;
    perform set_config('funnel.channel', p_channel, true);

    if coalesce(v_shared, 0) > 1 then
      -- `? 'm'` guards a view that has no metric object: jsonb_set returns NULL
      -- when handed one, which would drop every row without raising anything.
      v_sel := 'select case when to_jsonb(t) ? ''m'''
            || ' then jsonb_set(to_jsonb(t), ''{m}'', fo_channel_blind(to_jsonb(t)->''m''))'
            || ' else to_jsonb(t) end';
    end if;
  end if;

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('%s from %I t where client_id = $1%s order by %s', v_sel, p_view, v_where, v_order)
      using p_client, p_offer;
  else
    return query execute
      format('%s from %I t where client_id = $1 order by %s', v_sel, p_view, v_order)
      using p_client;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;


-- ══════════════════════════════════════════════════════════════════════════
-- 0032_the_page_gets_a_dimension.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0032 — the landing page becomes something the database can hold.
--
-- Step 3c of the CRO process asks whether a page section changed and whether
-- the section above it affected the one below, and 0029 said plainly that the
-- question could not be answered: "no landing-page dimension exists … that
-- question stays unanswered and the screen says so rather than quietly dropping
-- it." This is that dimension.
--
-- ── WHY IT IS ITS OWN PAIR OF TABLES ───────────────────────────────────────
-- A scroll curve is not an event and it is not a metric. It has no person on
-- it, so it cannot go in `events`; it has no money on it, so it cannot go in
-- `ads_performance`; and its denominator is SESSIONS, which is not a
-- denominator any view in this schema already carries. Forcing it into an
-- existing table would mean one of those three lies.
--
-- Two tables rather than one because the file genuinely has two levels: one
-- export is one measurement of one page on one device over one window, and it
-- carries twenty readings. Repeating the window and the session count on all
-- twenty rows would let them disagree, and the session count is the number
-- every percentage on the curve is a percentage of.
--
-- ── WHAT IT DELIBERATELY DOES NOT DO ───────────────────────────────────────
-- No section names, no per-section conversion, no "the hero cost you 12 leads".
-- Clarity's export is a depth curve and nothing in it knows where a section
-- starts or ends. The app reads the curve against Lead Gen % to bound where the
-- form can be (lib/funnel/scroll.ts) and says where the audience is lost. It
-- does not pretend to know what was at that depth.
--
-- No scroll figures in the metric spine either. Sessions are a different
-- population from clicks — the ad account's clicks are what Lead Gen % divides
-- by, and Clarity sees organic traffic too — so a scroll row inside a column
-- that adds up spend and leads would be summing two different denominators.
-- The comparison happens on the This round screen, where both can be labelled.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 0. THE IMPORTER GAINS A FIFTH SOURCE ───────────────────────────────────
-- import_batches has carried a four-value check since 0001. A scroll import is
-- a real import — it is staged, previewed, committed and traceable like the
-- others — so it needs to be nameable here or it cannot be recorded at all.
alter table import_batches drop constraint if exists import_batches_source_check;
alter table import_batches add constraint import_batches_source_check
  check (source in ('ads', 'leads', 'attendance', 'sales', 'scroll'));

-- ── 1. ONE EXPORT ──────────────────────────────────────────────────────────
create table if not exists scroll_runs (
  run_id        uuid primary key default gen_random_uuid(),
  client_id     text not null,
  round_id      text not null references rounds (round_id),
  page_label    text,                    -- Clarity's "Project name"
  url_pattern   text,                    -- what it filtered on, kept for audit
  device        text not null default 'all'
                check (device in ('mobile', 'desktop', 'tablet', 'all')),
  /**
   * Clarity's own "Page views" line, recorded and NOT used.
   *
   * It disagrees with the curve's denominator — 60 against 58 on the export
   * this was built from — because a view that never fired a scroll event is a
   * view and is not in the scroll base. Storing both is what makes that
   * checkable later instead of arguable.
   */
  page_views    integer,
  sessions      integer not null check (sessions > 0),
  captured_from date,
  captured_to   date,
  source_file   text,
  imported_at   timestamptz not null default now(),
  import_batch_id uuid references import_batches (batch_id),
  /**
   * One curve per page per device per window. A re-export of the same window
   * replaces rather than doubles — the same rule the ads dedupe key follows,
   * and for the same reason: two copies of one measurement would read as twice
   * the traffic.
   */
  unique (client_id, round_id, device, captured_from, captured_to)
);
create index if not exists idx_scroll_runs_round on scroll_runs (round_id);

-- ── 2. THE READINGS ────────────────────────────────────────────────────────
create table if not exists scroll_depths (
  run_id       uuid not null references scroll_runs (run_id) on delete cascade,
  depth_pct    integer not null check (depth_pct between 0 and 100),
  visitors     integer not null check (visitors >= 0),
  /**
   * Clarity's own drop-off figure. Redundant with visitors ÷ sessions by
   * design: it is the second statement of the denominator, and the importer
   * uses the two together to derive `sessions` rather than trusting page views.
   */
  drop_off_pct numeric(6, 2),
  primary key (run_id, depth_pct)
);

alter table scroll_runs   enable row level security;
alter table scroll_depths enable row level security;
drop policy if exists "demo read" on scroll_runs;
drop policy if exists "demo read" on scroll_depths;
create policy "demo read" on scroll_runs   for select using (true);
create policy "demo read" on scroll_depths for select using (true);
grant select on scroll_runs, scroll_depths to anon, authenticated;

-- ── 3. WHAT THE APP READS ──────────────────────────────────────────────────
-- The run with its curve folded into one jsonb array, so a screen showing three
-- runs makes one request rather than one per run. Ordered by depth inside the
-- array, because a curve out of order is a curve nobody can read.
create or replace view v_scroll_runs as
select
  r.run_id,
  r.client_id,
  r.round_id,
  r.page_label,
  r.device,
  r.sessions,
  r.page_views,
  r.captured_from,
  r.captured_to,
  r.source_file,
  r.imported_at,
  coalesce(
    (select jsonb_agg(
              jsonb_build_object(
                'depth',        d.depth_pct,
                'visitors',     d.visitors,
                'drop_off_pct', d.drop_off_pct
              ) order by d.depth_pct)
     from scroll_depths d where d.run_id = r.run_id),
    '[]'::jsonb
  ) as points
from scroll_runs r
order by r.round_id, r.sessions desc, r.device;

grant select on v_scroll_runs to anon, authenticated;

-- The same data one row per reading, for anything that would rather have rows
-- than an array — a CSV export, a chart, a hand-written check in the SQL editor.
create or replace view v_scroll_curve as
select
  r.client_id,
  r.round_id,
  r.run_id,
  r.device,
  r.sessions,
  d.depth_pct,
  d.visitors,
  d.drop_off_pct,
  -- share of sessions still on the page at this depth
  round(100.0 * d.visitors / r.sessions, 1) as reached_pct
from scroll_runs r
join scroll_depths d on d.run_id = r.run_id
order by r.round_id, r.device, d.depth_pct;

grant select on v_scroll_curve to anon, authenticated;

-- ── 4. NO SEED ─────────────────────────────────────────────────────────────
-- Same rule as client_targets in 0029: a measurement nobody took is not a
-- measurement. The tables ship empty and the This round screen says the
-- landing-page question is unanswered until a real Clarity export is imported.


-- ══════════════════════════════════════════════════════════════════════════
-- 0033_an_asset_is_judged_on_the_objective.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0033 — what each audience and creative actually PRODUCED, not just collected.
--
-- This round has an OBJECTIVE picker with four settings, and until now it moved
-- one section of the screen. Step 7 proposed candidates on cost per lead
-- whatever you picked, which is the wrong question when the client's objective
-- is attendance: an audience can be the cheapest source of leads on the account
-- and the worst source of people who actually turn up.
--
-- Step 7 could not ask any other question, because v_round_assets carries spend
-- and leads and nothing else. This appends the three outcomes the other
-- objectives are judged on.
--
-- ── WHY IT HAS TO GO THROUGH THE LEAD ──────────────────────────────────────
-- An attendance row has no ad_set on it and neither does a sale — only leads
-- carry the audience and creative, because only the opt-in passed through a URL
-- with utm_term on it. So the outcome is attributed the way revenue already is
-- (see 0020): find the person's LEAD, and credit the asset that bought it.
--
-- On this database that resolves 37 of 40 attendances and 19 of 19 sales. The
-- three that don't are the three whose lead row is sitting in the unmatched
-- queue — they are missing from these counts for exactly the reason the queue
-- exists, and they are not invented here.
--
-- ── WHY lead_round_id AND NOT round_id ─────────────────────────────────────
-- A buyer can attend one round and buy in the next. round_id says where the
-- event happened; lead_round_id says which round's advertising produced the
-- person. The asset lives in the second one, and joining on it rather than on
-- contact alone is also what stops a returning contact's second lead row from
-- multiplying their attendance across two rounds.
--
-- ── WHAT THIS DOES NOT CHANGE ──────────────────────────────────────────────
-- Nothing that already reads this view moves. `spend`, `leads`, `spend_share`
-- and `id_count` are byte-for-byte what they were; the three new columns are
-- APPENDED, which is the only edit `create or replace view` permits.
--
-- And it makes no claim about whether the counts are big enough to rank on.
-- They mostly are not — in 0526-03 the best audience produced three attendees
-- and every preview purchase is untagged — so the screen reports the floor it
-- could not clear instead of ranking on threes. That is the point of measuring
-- it: you can now see that the data cannot answer the question, rather than
-- being shown a cost-per-lead answer to a question about attendance.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_round_assets as
with named as (
  select r.client_id, a.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(a.ad_set), ''), '(unsplit)') as name,
         sum(a.spend) as spend,
         0::int as ids
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
  union all
  select r.client_id, a.round_id, 'creative',
         case when btrim(a.ad) ~ '^[0-9]+$' then '(ad ids)'
              else coalesce(nullif(btrim(a.ad), ''), '(unsplit)') end,
         sum(a.spend),
         count(distinct a.ad) filter (where btrim(a.ad) ~ '^[0-9]+$')::int
  from v_ads a join v_rounds r on r.round_id = a.round_id
  group by 1, 2, 3, 4
),
/**
 * One row per person per round, carrying the asset that produced them.
 *
 * distinct on, because the lead dedupe key is (contact, round, DAY) — one
 * person can hold two lead rows in a round and joining on contact alone would
 * count their single attendance twice. The earliest opt-in wins: it is the one
 * that bought them.
 */
lead_asset as (
  select distinct on (e.contact_id, e.round_id)
         e.contact_id,
         e.round_id,
         coalesce(nullif(btrim(e.ad_set), ''), '(unsplit)') as audience,
         case when btrim(e.ad) ~ '^[0-9]+$' then '(ad ids)'
              else coalesce(nullif(btrim(e.ad), ''), '(unsplit)') end as creative
  from v_events e
  where e.event_type = 'lead'
  order by e.contact_id, e.round_id, e.event_date
),
/**
 * Leads per asset, and the untracked-ad count — LIFTED FROM 0030 UNCHANGED.
 *
 * Deliberately not folded into the outcome union below. `leads` and `id_count`
 * are columns the screen already reads, and the only safe way to append to a
 * view is to leave the existing columns computing exactly what they computed
 * before. Rewriting them to produce the same answer is a bet; not touching them
 * is not.
 */
got as (
  select r.client_id, e.round_id, 'audience'::text as kind,
         coalesce(nullif(btrim(e.ad_set), ''), '(unsplit)') as name,
         count(*) as leads,
         0::int as ids
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
  union all
  select r.client_id, e.round_id, 'creative',
         case when btrim(e.ad) ~ '^[0-9]+$' then '(ad ids)'
              else coalesce(nullif(btrim(e.ad), ''), '(unsplit)') end,
         count(*),
         count(distinct e.ad) filter (where btrim(e.ad) ~ '^[0-9]+$')::int
  from v_events e join v_rounds r on r.round_id = e.round_id
  where e.event_type = 'lead'
  group by 1, 2, 3, 4
),
/**
 * The three new outcomes, attributed through the person's lead row.
 *
 * An attendance or sale whose lead is parked has no asset to credit and drops
 * out here — the same understatement the unmatched queue already reports, in
 * the same direction. Nothing is invented to fill the gap.
 */
produced as (
  select r.client_id, e.lead_round_id as round_id, 'audience'::text as kind,
         la.audience as name,
         count(*) filter (where e.event_type = 'attendance') as att,
         count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buys,
         coalesce(sum(coalesce(e.amount, 0) - coalesce(e.refund_amount, 0))
                  filter (where e.event_type = 'sale'), 0) as rev
  from v_events e
  join v_rounds r on r.round_id = e.lead_round_id
  join lead_asset la on la.contact_id = e.contact_id and la.round_id = e.lead_round_id
  where e.event_type in ('attendance', 'sale')
  group by 1, 2, 3, 4
  union all
  select r.client_id, e.lead_round_id, 'creative', la.creative,
         count(*) filter (where e.event_type = 'attendance'),
         count(*) filter (where e.event_type = 'sale' and e.product = 'preview'),
         coalesce(sum(coalesce(e.amount, 0) - coalesce(e.refund_amount, 0))
                  filter (where e.event_type = 'sale'), 0)
  from v_events e
  join v_rounds r on r.round_id = e.lead_round_id
  join lead_asset la on la.contact_id = e.contact_id and la.round_id = e.lead_round_id
  where e.event_type in ('attendance', 'sale')
  group by 1, 2, 3, 4
),
joined as (
  select
    coalesce(s.client_id, g.client_id) as client_id,
    coalesce(s.round_id,  g.round_id)  as round_id,
    coalesce(s.kind,      g.kind)      as kind,
    coalesce(s.name,      g.name)      as name,
    s.spend,
    g.leads,
    greatest(coalesce(s.ids, 0), coalesce(g.ids, 0)) as ids
  from named s
  full outer join got g
    on  g.client_id = s.client_id and g.round_id = s.round_id
    and g.kind = s.kind           and g.name    = s.name
),
-- A separate pass rather than a third arm of the join above, so `joined` stays
-- character-for-character what 0030 produced.
with_outcomes as (
  select j.*, p.att, p.prev_buys, p.rev
  from joined j
  left join produced p
    on  p.client_id = j.client_id and p.round_id = j.round_id
    and p.kind      = j.kind      and p.name     = j.name
)
select
  client_id, round_id, kind, name,
  spend,
  coalesce(leads, 0)::int as leads,
  round(
    100 * spend / nullif(sum(spend) over (partition by client_id, round_id, kind), 0),
    1
  ) as spend_share,
  -- how many untracked ads the '(ad ids)' row stands for, so the screen can say
  -- so rather than presenting a bucket as if it were one creative
  nullif(ids, 0) as id_count,
  -- ── APPENDED BY 0033 ───────────────────────────────────────────────────
  -- Zero here is a measurement, not an absence: the asset is in this round — it
  -- has spend, or it has leads — and produced none of these. That is precisely
  -- the case step 7 exists to surface, so it must not read as null.
  --
  -- The one case where a zero would LIE is a round where attendance was never
  -- imported at all, which would make every audience look like it produced
  -- nobody. That is caught where it can be judged, in candidatesFrom(): an
  -- asset is never blamed for a nought the whole round shares.
  coalesce(att, 0)::int       as att,
  coalesce(prev_buys, 0)::int as prev_buys,
  coalesce(rev, 0)::numeric   as rev
from with_outcomes
order by client_id, round_id, kind, spend desc nulls last, name;

grant select on v_round_assets to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0034_native_data_integration.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- AcqOS owns the funnel definition; Funnel OS owns actuals. The API validates
-- the complete payload before this function replaces one known client's rows.

alter table client_journey_config
  add column if not exists source_type text,
  add column if not exists source_ref text,
  add column if not exists schema_source text,
  add column if not exists synced_at timestamptz;

alter table client_journey_config
  drop constraint if exists client_journey_config_source_type_chk;
alter table client_journey_config
  add constraint client_journey_config_source_type_chk
  check (source_type is null or source_type in ('meta', 'google', 'crm', 'csv'));

create or replace function replace_client_journey_schema(
  p_client_id text,
  p_client_name text,
  p_stages jsonb
) returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_client_note text;
begin
  select min(client_note) into v_client_note
  from client_journey_config
  where client_id = p_client_id;

  delete from client_journey_config where client_id = p_client_id;

  insert into client_journey_config (
    client_id, stage_order, stage_name, compare_dimension, client_name, client_note,
    stage_slug, stage_metric, stage_rate_label, unit_price,
    source_type, source_ref, schema_source, synced_at
  )
  select
    p_client_id,
    (stage->>'order')::integer,
    stage->>'name',
    nullif(stage->>'compareDimension', ''),
    p_client_name,
    v_client_note,
    stage->>'slug',
    stage->>'metric',
    nullif(stage->>'rateLabel', ''),
    nullif(stage->>'unitPrice', '')::numeric,
    stage->>'sourceType',
    stage->>'sourceRef',
    'acqos',
    now()
  from jsonb_array_elements(p_stages) as stage;
end;
$$;

revoke all on function replace_client_journey_schema(text, text, jsonb) from public, anon, authenticated;
grant execute on function replace_client_journey_schema(text, text, jsonb) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0035_a_push_does_not_erase_the_price.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- A push that carries no unitPrice keeps the price already stored, keyed on
-- stage_slug, and names what it kept. An explicit price wins; an explicit 0 is
-- a price, not an absence. Returns jsonb, so the function is dropped first.

drop function if exists replace_client_journey_schema(text, text, jsonb);

create function replace_client_journey_schema(
  p_client_id text,
  p_client_name text,
  p_stages jsonb
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_client_note text;
  v_prices jsonb;
  v_kept text[];
begin
  select min(client_note) into v_client_note
  from client_journey_config
  where client_id = p_client_id;

  -- slug → price, for the stages that have both. Read before the delete.
  select coalesce(jsonb_object_agg(stage_slug, unit_price), '{}'::jsonb)
    into v_prices
    from client_journey_config
   where client_id = p_client_id
     and stage_slug is not null
     and unit_price is not null;

  -- Which incoming stages will be taking a price they did not send.
  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'unitPrice', '') is null
     and v_prices ? (stage->>'slug');

  delete from client_journey_config where client_id = p_client_id;

  insert into client_journey_config (
    client_id, stage_order, stage_name, compare_dimension, client_name, client_note,
    stage_slug, stage_metric, stage_rate_label, unit_price,
    source_type, source_ref, schema_source, synced_at
  )
  select
    p_client_id,
    (stage->>'order')::integer,
    stage->>'name',
    nullif(stage->>'compareDimension', ''),
    p_client_name,
    v_client_note,
    stage->>'slug',
    stage->>'metric',
    nullif(stage->>'rateLabel', ''),
    -- nullif('') only strips an absent value; '0' survives it and stays 0.
    coalesce(
      nullif(stage->>'unitPrice', '')::numeric,
      (v_prices->>(stage->>'slug'))::numeric
    ),
    stage->>'sourceType',
    stage->>'sourceRef',
    'acqos',
    now()
  from jsonb_array_elements(p_stages) as stage;

  return jsonb_build_object(
    'stagesWritten', jsonb_array_length(p_stages),
    'pricesPreserved', to_jsonb(v_kept)
  );
end;
$$;

revoke all on function replace_client_journey_schema(text, text, jsonb) from public, anon, authenticated;
grant execute on function replace_client_journey_schema(text, text, jsonb) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0036_a_push_can_open_a_client.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- client_journey_config is the client register (v_clients is built from it),
-- so a push that cannot insert rows for a new client_id cannot open a client.
-- It can now; the route requires createClient: true before it will. p_client_note
-- joins it, preserved when omitted, and `created` is reported from in here.

drop function if exists replace_client_journey_schema(text, text, jsonb);
drop function if exists replace_client_journey_schema(text, text, jsonb, text);

create function replace_client_journey_schema(
  p_client_id text,
  p_client_name text,
  p_stages jsonb,
  p_client_note text default null
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_prior_rows integer;
  v_client_note text;
  v_prices jsonb;
  v_kept text[];
begin
  select count(*), min(client_note)
    into v_prior_rows, v_client_note
    from client_journey_config
   where client_id = p_client_id;

  -- A note in the payload wins; an omitted one keeps what is stored, which for
  -- a client being opened here is nothing.
  v_client_note := coalesce(nullif(btrim(p_client_note), ''), v_client_note);

  -- slug → price, for the stages that have both. Read before the delete.
  select coalesce(jsonb_object_agg(stage_slug, unit_price), '{}'::jsonb)
    into v_prices
    from client_journey_config
   where client_id = p_client_id
     and stage_slug is not null
     and unit_price is not null;

  -- Which incoming stages will be taking a price they did not send.
  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'unitPrice', '') is null
     and v_prices ? (stage->>'slug');

  delete from client_journey_config where client_id = p_client_id;

  insert into client_journey_config (
    client_id, stage_order, stage_name, compare_dimension, client_name, client_note,
    stage_slug, stage_metric, stage_rate_label, unit_price,
    source_type, source_ref, schema_source, synced_at
  )
  select
    p_client_id,
    (stage->>'order')::integer,
    stage->>'name',
    nullif(stage->>'compareDimension', ''),
    p_client_name,
    v_client_note,
    stage->>'slug',
    stage->>'metric',
    nullif(stage->>'rateLabel', ''),
    -- nullif('') only strips an absent value; '0' survives it and stays 0.
    coalesce(
      nullif(stage->>'unitPrice', '')::numeric,
      (v_prices->>(stage->>'slug'))::numeric
    ),
    stage->>'sourceType',
    stage->>'sourceRef',
    'acqos',
    now()
  from jsonb_array_elements(p_stages) as stage;

  return jsonb_build_object(
    'stagesWritten', jsonb_array_length(p_stages),
    'pricesPreserved', to_jsonb(v_kept),
    'created', v_prior_rows = 0
  );
end;
$$;

revoke all on function replace_client_journey_schema(text, text, jsonb, text) from public, anon, authenticated;
grant execute on function replace_client_journey_schema(text, text, jsonb, text) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0037_parked_rows_answer_the_same_window.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- The parked caveat must cover the same period as the numbers it qualifies.
-- unmatched_rows has no date of its own, so a row is placed by the coverage of
-- the batch it arrived in — the 0023 overlap test, one level up. `undated`
-- names the rows no window can place rather than losing them.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace function fo_unmatched_cut(
  p_client text,
  p_from   date default null,
  p_to     date default null
) returns jsonb
language sql
stable
as $$
  with waiting as (
    select
      u.reason,
      b.coverage_start,
      b.coverage_end
    from unmatched_rows u
    left join import_batches b on b.batch_id = u.import_batch_id
    where u.client_id = p_client
      and not coalesce(u.auto_resolved, false)
      and u.resolved_at is null
  ),
  placed as (
    select
      reason,
      (coverage_start is not null and coverage_end is not null) as datable,
      (
        coverage_start is not null and coverage_end is not null
        and (p_from is null or coverage_end   >= p_from)
        and (p_to   is null or coverage_start <= p_to)
      ) as in_window
    from waiting
  )
  select jsonb_build_object(
    'count',   (select count(*) from placed where in_window),
    'allTime', (select count(*) from placed),
    'undated', (select count(*) from placed where not datable),
    'reasons', coalesce((
      select jsonb_object_agg(coalesce(reason, 'unknown'), n)
      from (
        select reason, count(*) as n
        from placed
        where in_window
        group by reason
      ) grouped
    ), '{}'::jsonb)
  );
$$;

grant execute on function fo_unmatched_cut(text, date, date) to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0038_a_late_push_cannot_undo_a_newer_one.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- generatedAt and schemaVersion are stored, and a push strictly older than the
-- one on file is refused without writing. The check is in here because only
-- this transaction sees the stored timestamp and the write together. Equal
-- timestamps pass: a retry must be able to replay itself.

alter table client_journey_config
  add column if not exists schema_version integer,
  add column if not exists generated_at timestamptz;

drop function if exists replace_client_journey_schema(text, text, jsonb, text);
drop function if exists replace_client_journey_schema(text, text, jsonb, text, integer, timestamptz);

create function replace_client_journey_schema(
  p_client_id text,
  p_client_name text,
  p_stages jsonb,
  p_client_note text default null,
  p_schema_version integer default null,
  p_generated_at timestamptz default null
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_prior_rows integer;
  v_prior_generated timestamptz;
  v_client_note text;
  v_prices jsonb;
  v_kept text[];
begin
  select count(*), min(client_note), max(generated_at)
    into v_prior_rows, v_client_note, v_prior_generated
    from client_journey_config
   where client_id = p_client_id;

  -- Strictly older only: a replay of the same push is not a regression.
  if p_generated_at is not null
     and v_prior_generated is not null
     and p_generated_at < v_prior_generated then
    return jsonb_build_object(
      'written', false,
      'reason', 'stale_push',
      'storedGeneratedAt', v_prior_generated,
      'incomingGeneratedAt', p_generated_at
    );
  end if;

  -- A note in the payload wins; an omitted one keeps what is stored, which for
  -- a client being opened here is nothing.
  v_client_note := coalesce(nullif(btrim(p_client_note), ''), v_client_note);

  -- slug → price, for the stages that have both. Read before the delete.
  select coalesce(jsonb_object_agg(stage_slug, unit_price), '{}'::jsonb)
    into v_prices
    from client_journey_config
   where client_id = p_client_id
     and stage_slug is not null
     and unit_price is not null;

  -- Which incoming stages will be taking a price they did not send.
  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'unitPrice', '') is null
     and v_prices ? (stage->>'slug');

  delete from client_journey_config where client_id = p_client_id;

  insert into client_journey_config (
    client_id, stage_order, stage_name, compare_dimension, client_name, client_note,
    stage_slug, stage_metric, stage_rate_label, unit_price,
    source_type, source_ref, schema_source, synced_at,
    schema_version, generated_at
  )
  select
    p_client_id,
    (stage->>'order')::integer,
    stage->>'name',
    nullif(stage->>'compareDimension', ''),
    p_client_name,
    v_client_note,
    stage->>'slug',
    stage->>'metric',
    nullif(stage->>'rateLabel', ''),
    -- nullif('') only strips an absent value; '0' survives it and stays 0.
    coalesce(
      nullif(stage->>'unitPrice', '')::numeric,
      (v_prices->>(stage->>'slug'))::numeric
    ),
    stage->>'sourceType',
    stage->>'sourceRef',
    'acqos',
    now(),
    p_schema_version,
    p_generated_at
  from jsonb_array_elements(p_stages) as stage;

  return jsonb_build_object(
    'written', true,
    'created', v_prior_rows = 0,
    'stagesWritten', jsonb_array_length(p_stages),
    'pricesPreserved', to_jsonb(v_kept)
  );
end;
$$;

revoke all on function replace_client_journey_schema(text, text, jsonb, text, integer, timestamptz) from public, anon, authenticated;
grant execute on function replace_client_journey_schema(text, text, jsonb, text, integer, timestamptz) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0039_a_dimension_has_to_name_a_real_column.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- compare_dimension was validated as table.column and no further, so an
-- invented column stored quietly. It is not interpolated into a query — the
-- stage slug picks the view — so a wrong one never fails, it just sits there
-- claiming a cut that is not happening. Checked against pg_catalog, which
-- cannot drift the way a list in the app would.

create or replace function fo_unknown_dimensions(p_dimensions text[])
returns text[]
language sql
stable
as $$
  select coalesce(array_agg(distinct d), '{}'::text[])
  from unnest(coalesce(p_dimensions, '{}'::text[])) as d
  where d is not null
    and not exists (
      select 1
      from pg_attribute a
      where a.attrelid = to_regclass('public.' || quote_ident(split_part(d, '.', 1)))
        and a.attname  = split_part(d, '.', 2)
        and a.attnum > 0
        and not a.attisdropped
    );
$$;

revoke all on function fo_unknown_dimensions(text[]) from public, anon, authenticated;
grant execute on function fo_unknown_dimensions(text[]) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0040_a_push_keeps_the_breakdown_and_the_label.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- A push does not erase the breakdown or the rate label, for the same reason
-- it does not erase the price.
--
-- 0035 taught this function that a null unitPrice means "I have no opinion",
-- not "set it to nothing", because AcqOS does not know what a client charges.
-- compare_dimension and stage_rate_label are exactly the same kind of field and
-- were missed: they were written straight from the payload with no fallback.
--
--   compare_dimension  which column a stage is broken down by
--                      ('ads_performance.ad_set', 'rounds.session_label')
--   stage_rate_label   what the step-conversion column is called
--                      ('CTR', 'opt-in', 'show', 'take-up')
--
-- Both are Funnel OS's own concepts. AcqOS has no view on either and sends null
-- for both, deliberately — lib/funnel-os/translate.ts says so in as many words:
-- "a wrong guess would overwrite a real one. Null leaves what is stored."
--
-- That was true of the price and false of these two. Shely holds five dimensions
-- and six rate labels; the first real push would have taken all eleven, and the
-- loss is invisible — the funnel still renders, the tabs still open, the
-- breakdown control just quietly has nothing to break down by.
--
-- So: same rule, same mechanism, keyed on stage_slug and read before the delete.
--
-- What this gives up, knowingly and exactly as 0035 gave it up for the price: a
-- push can no longer CLEAR one of these fields by sending null. Clearing is a
-- Funnel OS action and belongs in Funnel OS. Send a non-empty value to change
-- one; sending nothing means you are not talking about it.
--
-- Signature is unchanged, so this is create-or-replace and safe to re-run.
--
-- ROLLBACK: re-run 0038; it is the same function without the two coalesces.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace function replace_client_journey_schema(
  p_client_id text,
  p_client_name text,
  p_stages jsonb,
  p_client_note text default null,
  p_schema_version integer default null,
  p_generated_at timestamptz default null
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_prior_rows integer;
  v_prior_generated timestamptz;
  v_client_note text;
  v_prices jsonb;
  v_dims jsonb;
  v_rates jsonb;
  v_kept text[];
  v_kept_dims text[];
  v_kept_rates text[];
begin
  select count(*), min(client_note), max(generated_at)
    into v_prior_rows, v_client_note, v_prior_generated
    from client_journey_config
   where client_id = p_client_id;

  -- Strictly older only: a replay of the same push is not a regression.
  if p_generated_at is not null
     and v_prior_generated is not null
     and p_generated_at < v_prior_generated then
    return jsonb_build_object(
      'written', false,
      'reason', 'stale_push',
      'storedGeneratedAt', v_prior_generated,
      'incomingGeneratedAt', p_generated_at
    );
  end if;

  -- A note in the payload wins; an omitted one keeps what is stored, which for
  -- a client being opened here is nothing.
  v_client_note := coalesce(nullif(btrim(p_client_note), ''), v_client_note);

  -- slug → value, for the stages that have one. All read before the delete.
  select coalesce(jsonb_object_agg(stage_slug, unit_price), '{}'::jsonb)
    into v_prices
    from client_journey_config
   where client_id = p_client_id and stage_slug is not null and unit_price is not null;

  select coalesce(jsonb_object_agg(stage_slug, compare_dimension), '{}'::jsonb)
    into v_dims
    from client_journey_config
   where client_id = p_client_id and stage_slug is not null and compare_dimension is not null;

  select coalesce(jsonb_object_agg(stage_slug, stage_rate_label), '{}'::jsonb)
    into v_rates
    from client_journey_config
   where client_id = p_client_id and stage_slug is not null and stage_rate_label is not null;

  -- Which incoming stages will be taking a value they did not send.
  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'unitPrice', '') is null and v_prices ? (stage->>'slug');

  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept_dims
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'compareDimension', '') is null and v_dims ? (stage->>'slug');

  select coalesce(array_agg(stage->>'slug' order by (stage->>'order')::integer), '{}')
    into v_kept_rates
    from jsonb_array_elements(p_stages) as stage
   where nullif(stage->>'rateLabel', '') is null and v_rates ? (stage->>'slug');

  delete from client_journey_config where client_id = p_client_id;

  insert into client_journey_config (
    client_id, stage_order, stage_name, compare_dimension, client_name, client_note,
    stage_slug, stage_metric, stage_rate_label, unit_price,
    source_type, source_ref, schema_source, synced_at,
    schema_version, generated_at
  )
  select
    p_client_id,
    (stage->>'order')::integer,
    stage->>'name',
    coalesce(
      nullif(stage->>'compareDimension', ''),
      v_dims->>(stage->>'slug')
    ),
    p_client_name,
    v_client_note,
    stage->>'slug',
    stage->>'metric',
    coalesce(
      nullif(stage->>'rateLabel', ''),
      v_rates->>(stage->>'slug')
    ),
    -- nullif('') only strips an absent value; '0' survives it and stays 0.
    coalesce(
      nullif(stage->>'unitPrice', '')::numeric,
      (v_prices->>(stage->>'slug'))::numeric
    ),
    stage->>'sourceType',
    stage->>'sourceRef',
    'acqos',
    now(),
    p_schema_version,
    p_generated_at
  from jsonb_array_elements(p_stages) as stage;

  return jsonb_build_object(
    'written', true,
    'created', v_prior_rows = 0,
    'stagesWritten', jsonb_array_length(p_stages),
    'pricesPreserved', to_jsonb(v_kept),
    'dimensionsPreserved', to_jsonb(v_kept_dims),
    'rateLabelsPreserved', to_jsonb(v_kept_rates)
  );
end;
$$;

revoke all on function replace_client_journey_schema(text, text, jsonb, text, integer, timestamptz) from public, anon, authenticated;
grant execute on function replace_client_journey_schema(text, text, jsonb, text, integer, timestamptz) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 0041_a_closed_period_keeps_the_reading_it_had.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- ROLLBACK: drop function freeze_period_insight(...) and period_insights;
-- this permanently removes frozen history.

create table if not exists period_insights (
  client_id text not null,
  period_kind text not null check (period_kind in ('round', 'month')),
  period_key text not null,
  version integer not null,
  is_current boolean not null default true,
  payload jsonb not null,
  frozen_at timestamptz not null default now(),
  frozen_by text,
  note text,
  primary key (client_id, period_kind, period_key, version)
);

create index if not exists period_insights_current_idx
  on period_insights (client_id, period_kind, period_key, version desc);

alter table period_insights enable row level security;

create or replace function freeze_period_insight(
  p_client_id text,
  p_period_kind text,
  p_period_key text,
  p_payload jsonb,
  p_frozen_by text default null,
  p_note text default null
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_next integer;
  v_prior integer;
begin
  perform pg_advisory_xact_lock(hashtext(p_client_id || ':' || p_period_kind || ':' || p_period_key));

  select max(version) into v_prior
  from period_insights
  where client_id = p_client_id and period_kind = p_period_kind and period_key = p_period_key;
  v_next := coalesce(v_prior, 0) + 1;

  update period_insights set is_current = false
  where client_id = p_client_id and period_kind = p_period_kind and period_key = p_period_key and is_current;

  insert into period_insights (
    client_id, period_kind, period_key, version, is_current, payload, frozen_by, note
  ) values (
    p_client_id, p_period_kind, p_period_key, v_next, true, p_payload, p_frozen_by, p_note
  );

  return jsonb_build_object('version', v_next, 'isFirst', v_prior is null, 'supersededVersion', v_prior);
end;
$$;

revoke all on function freeze_period_insight(text, text, text, jsonb, text, text) from public, anon, authenticated;
grant execute on function freeze_period_insight(text, text, text, jsonb, text, text) to service_role;

-- ═════════════════════════════════════════════════════════════════════════
-- 0042_the_imaginary_product_gets_its_own_client.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- The imaginary product moves out of a real client's account.
--
-- 'shely-demo-evergreen' carries its own confession in product_note: "IMAGINARY
-- — test data for the Product, Channel and cadence filters." It was put into
-- the live database by hand to exercise those filters and left inside Shely's
-- account, where every unfiltered view added it to her real numbers:
--
--   metric      REAL     IMAGINARY   SHOWN AS 'All'   invented
--   impressions 51,360      40,000           91,360      43.8%
--   clicks         832         800            1,632      49.0%
--   leads          313          80              393      20.4%
--   purchases        9           8               17      47.1%
--   revenue      5,067       2,376            7,443      31.9%
--
-- That is the dashboard's default view, and it is also what the integration
-- endpoints return when no product filter is passed — so AcqOS has been reading
-- the blended figure, and a monthly report built today would put 91,360
-- impressions in front of a client whose real answer is 51,360. June 2026 reads
-- worse still: all four of its rounds are imaginary, so the whole month is
-- invented while presenting itself as Shely's.
--
-- ── What this migration is NOT doing ──────────────────────────────────────
--
-- Not inventing a second client. 0002_seed.sql already defines northsea_supply
-- — four stages, an ecommerce journey, its own rounds — and app/page.tsx has
-- carried copy for its 'product' and 'checkout' tabs since before this file
-- existed. 0001_schema.sql line 26 names it in a comment: "e.g. 'shely',
-- 'northsea_supply'". The live database simply does not have it: someone
-- removed it and added the evergreen fixture inside Shely instead.
--
-- So the journey below is 0002's, copied, not a new design. The one change is
-- the checkout price: the seed says 298.00 and the rows actually arriving sell
-- at 297.00 (2,376 over 8 orders). The price is configuration and has to agree
-- with the money underneath it.
--
-- Not restoring the seed's NS-0726-01 and NS-0826-01 rounds, nor the 466 events
-- and 296 contacts behind them. Production has never held them, and this
-- migration exists to take invented rows OUT of the live database — adding
-- several hundred more in the same breath would be an odd way to do it. The
-- seed still has them for anyone who wants a fuller demo; that is a decision,
-- not a side effect of this one.
--
-- ── What moves ───────────────────────────────────────────────────────────
--   products         1 row  — reassigned and renamed to suit its new owner
--   rounds           4 rows — DEMO-W1..W4
--   contacts        80 rows — only those whose events are ALL on demo rounds
--   events          88 rows — no change needed; they hang off round_id
--   ads_performance  8 rows — no change needed; same reason
--
-- Checked before writing this: no contact appears in both a demo and a real
-- event, no real event references a demo round or the reverse, no demo event
-- carries an import_batch_id, and no round_session, scroll_run or client_target
-- touches a demo round. The two sets do not overlap anywhere.
--
-- Staying with Shely: the 142 unmatched rows and 9 import batches. They came
-- out of her real leads exports; the fixture was never imported.
--
-- Safe to re-run: the inserts take the conflict, and each update is keyed on
-- rows that stop matching once they have moved.
--
-- ROLLBACK: set client_id back to 'shely' on the product, the four DEMO rounds
-- and their 80 contacts; delete the northsea_supply rows from
-- client_journey_config and client_flags; re-run 0004 to restore v_clients.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── Which accounts are real, as a fact rather than a guess ─────────────────
-- Kept out of client_journey_config on purpose: AcqOS owns that table and its
-- push deletes every row for a client before re-inserting, so a flag stored
-- there would survive exactly until the next sync. This is Funnel OS's own note
-- about an account and nothing else writes it.
create table if not exists client_flags (
  client_id text primary key,
  is_demo   boolean not null default false,
  note      text
);
alter table client_flags enable row level security;

insert into client_flags (client_id, is_demo, note) values
  ('northsea_supply', true,
   'Fixture account. Holds the imaginary product that exercises the product, channel and weekly-cadence filters. No number under this client describes a real business.')
on conflict (client_id) do update
  set is_demo = excluded.is_demo, note = excluded.note;

-- ── The client, which is its journey ───────────────────────────────────────
-- v_clients is built from client_journey_config, so a client with no stages is
-- not a client. This is 0002's definition of northsea_supply, unchanged apart
-- from the price noted above.
insert into client_journey_config (
  client_id, stage_order, stage_name, compare_dimension,
  client_name, client_note, stage_slug, stage_metric, stage_rate_label, unit_price
) values
  ('northsea_supply', 1, 'Targeted views', 'ads_performance.ad_set',
   'Northsea Supply', 'Ecommerce · 3 stages + targeting · DEMO ACCOUNT',
   'targeting', 'impressions',       'impressions', null),
  ('northsea_supply', 2, 'Ads',            'ads_performance.ad',
   'Northsea Supply', 'Ecommerce · 3 stages + targeting · DEMO ACCOUNT',
   'ads',       'clicks',            'CTR',         null),
  ('northsea_supply', 3, 'Product page',   'ads_performance.ad_set',
   'Northsea Supply', 'Ecommerce · 3 stages + targeting · DEMO ACCOUNT',
   'product',   'leads',             'sessions',    null),
  ('northsea_supply', 4, 'Checkout',       'events.product',
   'Northsea Supply', 'Ecommerce · 3 stages + targeting · DEMO ACCOUNT',
   'checkout',  'preview_purchases', 'complete',    297.00)
on conflict (client_id, stage_order) do nothing;

-- ── The contacts, before the rounds ────────────────────────────────────────
-- Read first, while "which rounds are demo" is still answerable by prefix and
-- before anything else has moved. A contact goes only if EVERY event carrying
-- it sits on a demo round; one real event and it stays with Shely, because a
-- person who appears in both is one person and cannot be in two accounts.
update contacts
   set client_id = 'northsea_supply'
 where client_id = 'shely'
   and contact_id in (
     select contact_id from events
      where contact_id is not null and round_id like 'DEMO-%'
   )
   and contact_id not in (
     select contact_id from events
      where contact_id is not null
        and (round_id is null or round_id not like 'DEMO-%')
   );

-- ── The rounds ─────────────────────────────────────────────────────────────
update rounds
   set client_id = 'northsea_supply'
 where client_id = 'shely'
   and product_id = 'shely-demo-evergreen';

-- ── The product ────────────────────────────────────────────────────────────
-- Renamed as it moves. "Evergreen Course" under a supply company was coherent
-- only while it was hiding in someone else's account.
update products
   set client_id    = 'northsea_supply',
       product_name = 'Weekly Supply Plan (demo)',
       product_note = 'IMAGINARY — the fixture that exercises the product, channel and weekly-cadence filters. Runs weekly, no classes.'
 where product_id = 'shely-demo-evergreen';

-- ── The switcher must not open on the fixtures ─────────────────────────────
-- 0004 ordered clients by round count so the app "opens on the account with
-- something to look at rather than on whichever name sorts first". Round count
-- was standing in for "is a real account", and it stops standing in for it the
-- moment the fixture holds four rounds and Shely holds two — which is what the
-- statements above have just arranged. Left alone, the app would greet everyone
-- with the imaginary client.
--
-- is_demo is APPENDED, never inserted mid-list: the column order of a view is
-- part of its contract here.
create or replace view v_clients as
select
  j.client_id,
  min(j.client_name)         as client_name,
  min(j.client_note)         as client_note,
  count(*)                   as stage_count,
  coalesce(r.round_count, 0) as round_count,
  coalesce(f.is_demo, false) as is_demo
from client_journey_config j
left join (
  select client_id, count(*) as round_count from rounds group by client_id
) r on r.client_id = j.client_id
left join client_flags f on f.client_id = j.client_id
group by j.client_id, r.round_count, f.is_demo
order by
  coalesce(f.is_demo, false),          -- real accounts first, whatever they hold
  coalesce(r.round_count, 0) desc,
  j.client_id;

grant select on client_flags to anon, authenticated, service_role;
grant select on v_clients to anon, authenticated, service_role;

-- ═════════════════════════════════════════════════════════════════════════
-- 0043_the_wire_is_visible_from_both_ends.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- The wire is visible from both ends.
--
-- AcqOS shows a "Send this funnel to Funnel OS" panel, so the push is visible
-- from the sending side. Nothing on this side said the wire existed at all: a
-- funnel arrives, the stages change, and the only evidence is that the sidebar
-- reads differently than it did yesterday.
--
-- The inbound half is already recorded — 0034 and 0038 put schema_source,
-- schema_version, generated_at and synced_at on client_journey_config, and the
-- anon read policy from 0001 covers that table. This adds the outbound half:
-- which periods AcqOS has taken a reading of and kept.
--
-- A view rather than a read policy on period_insights, for two reasons. The
-- table holds whole API responses and the panel wants four scalars, so pulling
-- the payload across to count it would be wasteful. And RLS on the base table
-- stays exactly as closed as 0041 left it — a view owned by the database owner
-- answers on its own privileges, which is the same route v_clients already
-- takes over the RLS'd tables underneath it.
--
-- ROLLBACK: drop view v_frozen_insights;
--   Nothing else reads it and no data lives in it.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_frozen_insights as
select
  client_id,
  period_kind,
  period_key,
  count(*)::int  as versions,
  max(version)   as current_version,
  max(frozen_at) as frozen_at,
  min(frozen_at) as first_frozen_at
from period_insights
group by client_id, period_kind, period_key;

comment on view v_frozen_insights is
  'One row per period that has ever been frozen, without the payloads. '
  'versions counts every reading kept for that period; current_version is the one '
  'a caller gets by default and frozen_at is when it was taken.';

grant select on v_frozen_insights to anon, authenticated, service_role;

-- ═════════════════════════════════════════════════════════════════════════
-- 0044_a_week_is_seven_days_and_a_column_says_which_offer.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- Three things the integration proved wrong, from AcqOS's defect report.
--
-- 1. A week was a round wearing a week's label.
-- 2. The offer cut returned four columns and no way to tell them apart.
-- 3. CPA and ROAS could not be reconciled against the counts beside them.
--
-- ROLLBACK: re-run 0027's v_metrics_by_week, 0024's v_metrics_by_offer and
--   0020's fo_paid_returns, in that order. No data is touched by any of this;
--   all three objects are derived.
-- ═══════════════════════════════════════════════════════════════════════════


-- ───────────────────────────────────────────────────────────────────────────
-- 1. CPA and ROAS say what they divided by.
--
-- 0020 made CPA and ROAS count only what advertising produced, which is right
-- and is the reason 0526-03 reads '—' rather than a triumphant 3.62 for six
-- sales its ads did not make. What it never did was SAY so in the data.
--
-- The month reports prevBuy 9 and cpa 815.75. 2447.26 / 9 is 271.92, so the
-- number on screen is unreconcilable against the number beside it — you have to
-- know that only 3 of those 9 customers came from an ad. AcqOS read the two
-- together, found they did not divide, and filed it as an arithmetic bug. It
-- isn't one; it is a denominator nobody was shown.
--
-- So the three ad-produced figures ride along in the same object. Nothing that
-- exists changes value. Same signature, so the six views calling this do not
-- need dropping, and the SPINE ignores keys it does not list.
-- ───────────────────────────────────────────────────────────────────────────
create or replace function fo_paid_returns(
  m               jsonb,
  p_paid_prev_buy bigint,     -- customers advertising acquired
  p_paid_prev_rev numeric,    -- preview revenue advertising produced
  p_paid_mid_rev  numeric     -- middle revenue advertising produced
) returns jsonb
language sql
immutable
as $$
  select m || jsonb_build_object(
    'cpa',      (m->>'spend')::numeric / nullif(p_paid_prev_buy, 0),
    'prevRoas', p_paid_prev_rev / nullif((m->>'spend')::numeric, 0),
    'midRoas',  p_paid_mid_rev  / nullif((m->>'spend')::numeric, 0),
    'roas',     (p_paid_prev_rev + p_paid_mid_rev) / nullif((m->>'spend')::numeric, 0),
    -- The denominators, so the four above can be checked rather than trusted.
    -- Absent, not zero, wherever the four are: a cut that cannot tell paid
    -- revenue from community revenue passes NULL here and must not claim it
    -- measured none.
    'paidPrevBuy', p_paid_prev_buy,
    'paidPrevRev', p_paid_prev_rev,
    'paidMidRev',  p_paid_mid_rev
  );
$$;


-- ───────────────────────────────────────────────────────────────────────────
-- 2. A week is seven days.
--
-- Every figure in this view was bucketed by date_trunc('week', ROUND START) —
-- so a round's whole total landed in the single week its first day fell in, and
-- then got a label naming that week's seven days. Shely's 0526-03 ran 23–27 May
-- and was filed under "18 May – 24 May", a window beginning five days before
-- the round did and ending four days before it finished. Week 22, which the
-- round actually spent three days in, did not appear at all. The week spends
-- were byte-identical to the round spends, which is the tell: nothing was ever
-- aggregated by day.
--
-- Now every row is placed on the week of ITS OWN date, in the client's own
-- calendar — the same +8 localDay() buckets imports by, so a 4am opt-in lands
-- on the day the person thinks they opted in.
--
-- ADS ARE THE EXCEPTION, and refusing rather than guessing is the whole point.
-- A Meta export with no day breakdown carries one row per ad set for the entire
-- reporting window, dated to the START of that window — all 76 of Shely's ad
-- rows say 2026-05-01, a date inside neither round. Bucketing on it would put
-- every cent of May in the week of 27 April, which is worse than what this view
-- did before. So an ads row is placeable only if its date falls inside its own
-- round, and unless EVERY row for a client is placeable the ads figures are
-- withheld from every week — spend, reach, impressions, clicks, and each ratio
-- built on them.
--
-- All-or-nothing per client, not row-by-row: half the spend under a week
-- heading is a wrong number, and a wrong number reads exactly like a right one.
-- A dash does not. Northsea's four weekly rounds each carry an ads row dated to
-- their own start, so they pass and their weeks are complete.
--
-- The rule is data-driven and self-clearing. The day a real day-broken-down
-- export lands, that client's weeks fill in with no change here.
-- ───────────────────────────────────────────────────────────────────────────
create or replace view v_metrics_by_week as
with
-- Can this client's ad rows be placed on a day at all? A row dated outside the
-- round it belongs to is a reporting-window marker, not the day money moved.
ads_placeable as (
  select client_id, bool_and(dated) as day_level
  from (
    select r.client_id, (a.date between r.start_date and r.end_date) as dated
    from v_ads a join v_rounds r on r.round_id = a.round_id
  ) t
  group by client_id
),
ads as (
  select r.client_id,
         date_trunc('week', a.date)::date as week_start,
         sum(a.spend) as spend,
         -- 0016: reach is distinct people and cannot be added. Taken off the
         -- coarsest row available. A week holding several days of campaign rows
         -- still over-counts anyone reached on two of them — REACH_NOTE says so
         -- on every response, and that caveat is now more load-bearing here.
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a
  join v_rounds r on r.round_id = a.round_id
  join ads_placeable d on d.client_id = r.client_id and d.day_level
  group by 1, 2
),
-- The join to v_rounds is what applies the product and period filter — v_events
-- carries none of its own — while the bucket comes from the event's own instant.
ev as (
  select r.client_id,
         date_trunc('week', (e.event_date at time zone 'Asia/Singapore')::date)::date as week_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id
  group by 1, 2
),
-- A sale lands in the week the money arrived. On a calendar cut that is what a
-- week's revenue means; the round it is credited to is By round's question.
sales as (
  select r.client_id,
         date_trunc('week', (e.event_date at time zone 'Asia/Singapore')::date)::date as week_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
),
-- A week with no class has no attendance to report, as distinct from a week
-- where nobody turned up. Bucketed by the session's own date, like everything
-- else here.
cls as (
  select client_id, date_trunc('week', session_date)::date as week_start, count(*) as sessions
  from v_round_sessions
  where session_date is not null
  group by 1, 2
),
-- The spine is the weeks that HAVE something, not the weeks rounds start in.
weeks as (
  select client_id, week_start from ads
  union
  select client_id, week_start from ev
  union
  select client_id, week_start from sales
),
-- Which rounds this week overlaps — a week may touch two, and a round may touch
-- two weeks. That is the fact the old cut_sub, always "1 round", could not say.
spans as (
  select w.client_id, w.week_start,
         string_agg(distinct r.round_id, ', ' order by r.round_id) as rounds
  from weeks w
  join v_rounds r
    on r.client_id = w.client_id
   and r.start_date <= w.week_start + 6
   and r.end_date   >= w.week_start
  group by 1, 2
)
select
  w.client_id,
  to_char(w.week_start, 'IYYY-"W"IW')       as cut_key,
  to_char(w.week_start, 'DD Mon') || ' – ' || to_char(w.week_start + 6, 'DD Mon') as cut_label,
  sp.rounds                                 as cut_sub,
  w.week_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = w.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = w.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from weeks w
left join spans sp  on sp.client_id    = w.client_id and sp.week_start    = w.week_start
left join ads       on ads.client_id   = w.client_id and ads.week_start   = w.week_start
left join ev        on ev.client_id    = w.client_id and ev.week_start    = w.week_start
left join sales     on sales.client_id = w.client_id and sales.week_start = w.week_start
left join cls       on cls.client_id   = w.client_id and cls.week_start   = w.week_start
left join v_sales_seen s    on s.client_id = w.client_id
left join v_client_prices p on p.client_id = w.client_id
order by w.client_id, w.week_start;

grant select on v_metrics_by_week to anon, authenticated;


-- ───────────────────────────────────────────────────────────────────────────
-- 3. An offer column says which offer it is.
--
-- This view is rounds × offers and was only ever read one offer at a time —
-- fo_cut takes p_offer, the Preview and Middle tabs each pass one, and on
-- screen the duplicate was invisible. The integration reads it unfiltered, and
-- got four columns whose key, label and sub were identical in pairs:
--
--     key='0526-02'  label='0526-02'  sub='May 13 – 19'   (preview)
--     key='0526-02'  label='0526-02'  sub='May 13 – 19'   (middle)
--
-- The only thing telling them apart was which of prevBuy and midBuy was null,
-- which is not an identifier. Two identical headings over different numbers is
-- worse than no table — a reader reads across the wrong one.
--
-- Fixed the way v_metrics_by_round_source already does it, because AcqOS parses
-- that shape today: the key carries both dimensions joined by '·', and the
-- group names the one the columns share. Here the round varies and the offer is
-- the group, which keeps cut_label as the round — so the two tabs on screen are
-- unchanged, and gain a spanning header naming the offer they are about.
--
-- The offer's name comes from the client's own journey, so it reads "Paid
-- Workshop Purchase ($297)" rather than "preview". A client with no such stage
-- falls back to a generic name rather than to nothing.
--
-- The three group columns are APPENDED. create or replace view may add columns
-- at the end and may not reorder them, so the first seven stay exactly where
-- they were.
-- ───────────────────────────────────────────────────────────────────────────
create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev,
         count(*) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_buys,
         sum(amount - coalesce(refund_amount, 0)) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id || '·' || o.product              as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.paid_rev,  0) end
  ) as m,
  o.product                                   as group_key,
  coalesce(j.stage_name,
           case o.product when 'preview' then 'Preview offer' else 'Middle offer' end) as group_label,
  null::text                                  as group_sub
from v_rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
left join client_journey_config j
       on j.client_id = r.client_id and j.stage_slug = o.product
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

-- ═════════════════════════════════════════════════════════════════════════
-- 0045_a_month_is_a_calendar_month.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- A month is a calendar month, not the month a round happened to start in.
--
-- The same fault 0044 fixed in weeks, still sitting in months. Every figure was
-- bucketed by date_trunc('month', ROUND START), so a round running 28 April to
-- 4 May reported all of its May spend, leads, attendance and sales under April.
--
-- It is invisible in today's data — both of Shely's rounds start and end inside
-- May, and Northsea's four weekly rounds sit inside June — which is exactly why
-- it is worth fixing now. It costs nothing today and silently misfiles a whole
-- month the first time a round crosses a month boundary, which is an ordinary
-- thing for a round to do.
--
-- WHY THE ADS RULE IS NOT THE WEEK RULE. 0044 refuses to place an ad row on a
-- week unless its date falls inside its own round, because a period-level Meta
-- export dates the whole window to its first day and that day says nothing
-- about which week the money went out in. A month is a coarser question and the
-- same row often answers it with certainty: Shely's rows are dated 2026-05-01
-- and belong to rounds running 13–19 and 23–27 May. The day is useless; the
-- MONTH is not in doubt. Applying the week rule here would blank May's spend
-- on data that is perfectly capable of answering the question asked.
--
-- So an ad row is placed on a month when either
--   (a) its own date falls inside its round — real day-level data, believe it; or
--   (b) its round begins and ends in the same calendar month — the day cannot
--       matter, because every day of that round is in that month.
--
-- What is left is the genuinely ambiguous case: a round crossing a month
-- boundary whose ads carry no usable day. Nothing can say how that spend split,
-- and both halves of a guess would be wrong. Those months — and only those —
-- report ads as absent. Withheld per month rather than per client, unlike 0044:
-- a month is a reporting unit a client reads on its own, and blanking a year of
-- them because one round in March straddled would be a worse answer than the
-- question deserves.
--
-- People are simpler. Leads, attendance and sales all carry their own instant,
-- so they are bucketed by their own local day — the +8 the importer uses — and
-- need no rule at all.
--
-- VERIFIED NOT TO MOVE ANY EXISTING FIGURE. Every round in this database begins
-- and ends inside one month, so rule (b) reproduces the old bucketing exactly
-- and no frozen period's live counterpart changes.
--
-- ROLLBACK: re-run 0027's v_metrics_by_month. No data is touched.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_month as
with
-- Which month each ad row belongs to, or NULL when nothing can say.
ads_placed as (
  select
    r.client_id,
    case
      when a.date between r.start_date and r.end_date
        then date_trunc('month', a.date)::date
      when date_trunc('month', r.start_date) = date_trunc('month', r.end_date)
        then date_trunc('month', r.start_date)::date
    end as month_start,
    a.spend, a.reach, a.impressions, a.clicks, a.ad_set
  from v_ads a join v_rounds r on r.round_id = a.round_id
),
-- The months a straddling round with undated ads touches. Ads are withheld from
-- these, because the split between them is unknowable and a guess would put real
-- money in a month it was not spent in.
tainted as (
  select distinct r.client_id, gs::date as month_start
  from v_ads a
  join v_rounds r on r.round_id = a.round_id
  cross join lateral generate_series(
    date_trunc('month', r.start_date), date_trunc('month', r.end_date), interval '1 month'
  ) gs
  where not (a.date between r.start_date and r.end_date)
    and date_trunc('month', r.start_date) <> date_trunc('month', r.end_date)
),
ads as (
  select client_id, month_start,
         sum(spend) as spend,
         -- 0016: reach is distinct people and cannot be added; read off the
         -- coarsest row. A month spanning several rounds still over-counts
         -- anyone reached in two of them — REACH_NOTE says so on every response.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from ads_placed
  where month_start is not null
  group by 1, 2
),
-- The join to v_rounds applies the product and period filter — v_events carries
-- none of its own — while the bucket comes from the event's own instant.
ev as (
  select r.client_id,
         date_trunc('month', (e.event_date at time zone 'Asia/Singapore')::date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join v_rounds r on r.round_id = e.round_id
  group by 1, 2
),
sales as (
  select r.client_id,
         date_trunc('month', (e.event_date at time zone 'Asia/Singapore')::date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join v_rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
),
-- A month whose rounds held no class has no attendance to report, as distinct
-- from having had nobody turn up. Bucketed by the session's own date.
cls as (
  select client_id, date_trunc('month', session_date)::date as month_start, count(*) as sessions
  from v_round_sessions
  where session_date is not null
  group by 1, 2
),
-- Every month a round TOUCHES, not the one it starts in — that is the whole
-- point — plus any month carrying data of its own.
round_months as (
  select r.client_id, gs::date as month_start, r.round_id
  from v_rounds r
  cross join lateral generate_series(
    date_trunc('month', r.start_date), date_trunc('month', r.end_date), interval '1 month'
  ) gs
),
months as (
  select client_id, month_start from round_months
  union
  select client_id, month_start from ads
  union
  select client_id, month_start from ev
  union
  select client_id, month_start from sales
),
spans as (
  select client_id, month_start, count(distinct round_id)::int as round_count
  from round_months group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  coalesce(sp.round_count, 0) || ' round'
    || case when coalesce(sp.round_count, 0) = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
            and coalesce(cls.sessions, 0) > 0
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from months m
left join spans sp on sp.client_id = m.client_id and sp.month_start = m.month_start
-- Ads join is suppressed for a tainted month, which is what makes the ads
-- figures absent there rather than half-counted.
left join ads
       on ads.client_id = m.client_id and ads.month_start = m.month_start
      and not exists (
        select 1 from tainted t
         where t.client_id = m.client_id and t.month_start = m.month_start
      )
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join cls   on cls.client_id   = m.client_id and cls.month_start   = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

-- ═════════════════════════════════════════════════════════════════════════
-- 0046_an_august_round_for_the_demo_client.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- One August round on the demo client, so the loop's date matching is tested
-- against something other than the round it has been re-run against all day.
--
-- Requested by AcqOS: their experiment loop closes a finished campaign by
-- matching it to the Funnel OS round covering the same dates, then asking for
-- that round by id. It has only ever been exercised against 0526-03. A second
-- round, different dates, different client, tests the matching rather than the
-- memory of one case.
--
-- ON northsea_supply AND NOWHERE ELSE. shely is a real client: her figures are
-- the master record, they flow into a frozen monthly report, and nothing in that
-- record would mark an invented number as invented. northsea_supply is already
-- synthetic — every contact is @evergreen.invalid and the client carries is_demo
-- — which is exactly why it is the one that can carry this.
--
-- Shaped to match DEMO-W1..W4 exactly: spend 500, reach 7000, impressions
-- 10,000, clicks 200, 20 leads, 2 preview sales. So the new round is comparable
-- to the four before it rather than being a differently-sized outlier.
--
-- NO ATTENDANCE ROWS, though the request asked for them. northsea_supply's
-- journey is four stages — Targeted views, Ads, Product page, Checkout — with no
-- class in it, and none of DEMO-W1..W4 carries an attendance event either.
-- Inventing one would put a number under a stage this client does not have.
--
-- ADS ARE DAY-LEVEL, ON PURPOSE. The request said a single period-level date
-- would be fine. It would, but dating the rows across the window is strictly
-- more useful: 21–26 August straddles ISO weeks 34 and 35, so this round also
-- exercises 0044's week splitting — 250 of the spend and 11 of the leads land in
-- one week, 250 and 9 in the other. It does not straddle a month, so nothing
-- here tests 0045 and nothing here disturbs it.
--
-- Safe to re-run: every row it writes, it first removes.
--
-- ROLLBACK: run the four deletes at the top of this file on their own.
-- ═══════════════════════════════════════════════════════════════════════════

-- Refuses to run anywhere northsea_supply is not flagged demo. The whole point
-- of this file is that it writes fixture rows, and a fixture row in a real
-- account is the one outcome nobody could unpick later.
do $$
begin
  if not exists (select 1 from client_flags where client_id = 'northsea_supply' and is_demo) then
    raise exception
      'northsea_supply is not flagged as a demo client in this database. Refusing to write fixture rows into an account that may be real. Run 0042 first, or check where you are connected.';
  end if;
end $$;

-- ── Remove anything a previous run left, in foreign-key order ───────────────
delete from events          where round_id = 'DEMO-W9';
delete from ads_performance where round_id = 'DEMO-W9';
delete from contacts
 where client_id = 'northsea_supply'
   and email in (select 'demo+' || i || '@evergreen.invalid' from generate_series(81, 100) i);
delete from rounds          where round_id = 'DEMO-W9';

-- ── The round ───────────────────────────────────────────────────────────────
-- 21–26 August 2026. Real dates on the row, which is the only thing the loop's
-- matching actually needs. session_date stays null: this client runs no class.
insert into rounds (round_id, client_id, start_date, end_date, session_date, session_label, product_id)
values (
  'DEMO-W9', 'northsea_supply', date '2026-08-21', date '2026-08-26', null, null,
  /*
   * Read off this client's own most recent round rather than typed, so it
   * cannot name a product that does not exist here.
   *
   * Not keyed to DEMO-W4, which was the first attempt: production has the four
   * DEMO weeks because they were created by hand, and a database built from
   * ALL.sql has NS-0726-01 and NS-0826-01 instead. That lookup returned null
   * there and would have filed this round under no product at all — invisible
   * to the product filter, and to cadence. Asking the client is the question
   * that has an answer in both.
   */
  (select product_id from rounds
    where client_id = 'northsea_supply' and product_id is not null
    order by start_date desc limit 1)
);

-- ── Ads: two channels, two days ─────────────────────────────────────────────
-- ad_set and ad are null, as on every other demo row — this client's export is
-- campaign-level. Totals match one demo week exactly.
insert into ads_performance (round_id, date, campaign, ad_set, ad, spend, impressions, reach, clicks, channel, import_batch_id)
values
  ('DEMO-W9', date '2026-08-21', 'DEMO — Evergreen (Meta)',   null, null, 150.00, 3000, 2000,  60, 'meta',   null),
  ('DEMO-W9', date '2026-08-21', 'DEMO — Evergreen (Google)', null, null, 100.00, 2000, 1500,  40, 'google', null),
  ('DEMO-W9', date '2026-08-25', 'DEMO — Evergreen (Meta)',   null, null, 150.00, 3000, 2000,  60, 'meta',   null),
  ('DEMO-W9', date '2026-08-25', 'DEMO — Evergreen (Google)', null, null, 100.00, 2000, 1500,  40, 'google', null);

-- ── Twenty people ───────────────────────────────────────────────────────────
-- .invalid is reserved by RFC 2606 and can never be a real domain, so none of
-- these addresses can collide with a person or be mailed by accident.
insert into contacts (contact_id, client_id, email)
select gen_random_uuid(), 'northsea_supply', 'demo+' || i || '@evergreen.invalid'
from generate_series(81, 100) i;

-- ── Their opt-ins, spread across the window ─────────────────────────────────
-- Timestamped in the client's own zone so the day they land on is the day a
-- person would say they opted in — the same rule the importer buckets by.
-- One in four is Organic, matching the 15/5 split on the other demo weeks.
insert into events (
  contact_id, round_id, event_type, event_date, lead_round_id,
  attribution_method, source, match_status, is_lead, refund_amount
)
select
  c.contact_id, 'DEMO-W9', 'lead',
  ((case
      when g.i between 81 and 84 then date '2026-08-21'
      when g.i between 85 and 88 then date '2026-08-22'
      when g.i between 89 and 91 then date '2026-08-23'
      when g.i between 92 and 94 then date '2026-08-24'
      when g.i between 95 and 97 then date '2026-08-25'
      else                            date '2026-08-26'
    end + time '10:00') at time zone 'Asia/Singapore'),
  'DEMO-W9', 'date_window',
  case when g.i % 4 = 0 then 'Organic' else 'Paid Ads' end,
  'demo', true, 0
from generate_series(81, 100) as g(i)
join contacts c
  on c.client_id = 'northsea_supply'
 and c.email = 'demo+' || g.i || '@evergreen.invalid';

-- ── Two purchases ───────────────────────────────────────────────────────────
-- Both from Paid Ads leads deliberately: 0020 counts only what advertising
-- produced, so a sale credited to an Organic lead would leave CPA and ROAS
-- blank and the round would look like it returned nothing.
-- One in each ISO week, so the week cut has revenue on both sides of the split.
insert into events (
  contact_id, round_id, event_type, event_date, lead_round_id,
  source, match_status, product, amount, refund_amount, is_lead
)
select
  c.contact_id, 'DEMO-W9', 'sale',
  ((v.sold_on + time '15:00') at time zone 'Asia/Singapore'),
  'DEMO-W9', 'Paid Ads', 'demo', 'preview', 297.00, 0, true
from (values
  ('demo+82@evergreen.invalid', date '2026-08-22'),   -- ISO week 34
  ('demo+95@evergreen.invalid', date '2026-08-26')    -- ISO week 35
) as v(email, sold_on)
join contacts c on c.client_id = 'northsea_supply' and c.email = v.email;

-- ═════════════════════════════════════════════════════════════════════════
-- 0047_a_demo_round_that_produces_candidates.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- One demo round whose assets can actually be ranked.
--
-- AcqOS needs a real example of a non-empty candidates.shown rather than
-- guessing its shape — three defects on their side today came from writing code
-- against an imagined payload. Nothing they have can produce one: northsea's
-- rows carry no ad set and no creative, so cut=adset has no columns and cut=ad
-- has only 'Unsplit spend', and there is nothing to rank.
--
-- DEMO-W8, 10–16 August 2026 — a whole ISO week (33), entirely inside August,
-- and finished, so it can be frozen and closed like any other.
--
-- THEIR EXAMPLE FIGURES WOULD NOT HAVE WORKED, which is the useful part of
-- doing this rather than describing it. They proposed 8 / 5 / 1 purchases and
-- asked for numbers "comfortably above your thin floor". The floor is
-- MIN_ASSET_OUTCOME = 10 per asset, so at 8 the best creative is still below it,
-- nothing would be ranked, and tooThin would suppress the lot — the same dead
-- end shely already gives them. So the winner here produces 15 and the two
-- runners-up 10 each.
--
-- WHAT IT IS BUILT TO TRIGGER. candidatesFrom pools both partitions, so the
-- round's own rate is 2,100 / 70 = SGD 30.00 per purchase, and:
--
--   NS_Creative_1   spend  150   buys 15   10.00/buy   the winner, and silent
--   NS_Creative_2   spend  200   buys 10   20.00/buy   unremarkable, silent
--   NS_Creative_3   spend  500   buys 10   50.00/buy   1.7x the round → WATCH
--   NS_Creative_4   spend  200   buys  0        —      spent 6.7x a purchase → CUT
--   NS_Audience_A   spend  600   buys 20   30.00/buy   exactly the round's rate
--   NS_Audience_B   spend  450   buys 15   30.00/buy   exactly the round's rate
--
-- Both audiences clear the floor, so tooThin comes back NULL rather than
-- suppressing anything — which is the condition the request actually needs.
--
-- NOTE THE WINNER IS SILENT. candidatesFrom only ever emits 'cut' and 'watch';
-- the 'keep' kind exists in the type and is never produced. So shown will hold
-- two entries, both negative, and NS_Creative_1 will not be in it. That is a
-- gap between what AcqOS expects and what exists, and it is a code question,
-- not a data one — flagged in the reply rather than papered over here.
--
-- The spend matrix is arranged so both partitions sum to the same 1,050:
--
--            C1    C2    C3    C4  │  total
--   Aud A    90   120   270   120  │    600
--   Aud B    60    80   230    80  │    450
--   ─────────────────────────────────────
--   total   150   200   500   200  │  1,050
--
-- Leads and purchases are split the same way, so no cell asks more people to
-- buy than opted in.
--
-- Purchases attach through v_round_assets' lead_asset join — the person's
-- earliest lead in the round — so every buyer here has a lead in this round
-- carrying the ad set and creative that gets the credit. Creative names are
-- non-numeric on purpose: 0033 folds a numeric ad into '(ad ids)'.
--
-- Safe to re-run. Touches northsea_supply only, and refuses to run if that is
-- not a demo client. Does NOT touch DEMO-W1..W4, AcqOS's regression baseline.
--
-- ONE CONSEQUENCE WORTH KNOWING: this round starts before DEMO-W9, so
-- DEMO-W9's previousId becomes DEMO-W8 rather than DEMO-W4. Unavoidable —
-- a round after W9 could not also be closed today — and arguably better, since
-- the comparison is now against the nearer round.
--
-- ROLLBACK: the four deletes at the top of this file, on their own.
-- ═══════════════════════════════════════════════════════════════════════════

do $$
begin
  if not exists (select 1 from client_flags where client_id = 'northsea_supply' and is_demo) then
    raise exception
      'northsea_supply is not flagged as a demo client in this database. Refusing to write fixture rows into an account that may be real.';
  end if;
end $$;

-- ── Remove anything a previous run left, in foreign-key order ───────────────
delete from events          where round_id = 'DEMO-W8' or lead_round_id = 'DEMO-W8';
delete from ads_performance where round_id = 'DEMO-W8';
delete from contacts
 where client_id = 'northsea_supply' and email like 'demo+w8-%@evergreen.invalid';
delete from rounds          where round_id = 'DEMO-W8';

-- ── The round ───────────────────────────────────────────────────────────────
insert into rounds (round_id, client_id, start_date, end_date, session_date, session_label, product_id)
values (
  'DEMO-W8', 'northsea_supply', date '2026-08-10', date '2026-08-16', null, null,
  (select product_id from rounds
    where client_id = 'northsea_supply' and product_id is not null
    order by start_date desc limit 1)
);

-- ── Ads, in the three tiers a real Meta export arrives in ───────────────────
-- Ad level carries spend and impressions and no reach or clicks; ad-set level
-- carries reach and clicks; the campaign line carries the one reach figure that
-- is actually deduplicated. Same shape as shely's real export, so this round
-- exercises 0016 rather than sidestepping it.
insert into ads_performance (round_id, date, campaign, ad_set, ad, spend, impressions, reach, clicks, channel, import_batch_id)
values
  -- ad level: spend and impressions only, at a flat SGD 50 CPM
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_A', 'NS_Creative_1',  90.00, 1800, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_A', 'NS_Creative_2', 120.00, 2400, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_A', 'NS_Creative_3', 270.00, 5400, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_A', 'NS_Creative_4', 120.00, 2400, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_B', 'NS_Creative_1',  60.00, 1200, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_B', 'NS_Creative_2',  80.00, 1600, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_B', 'NS_Creative_3', 230.00, 4600, null, null, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_B', 'NS_Creative_4',  80.00, 1600, null, null, 'meta', null),
  -- ad-set level: reach and clicks, no spend to double-count
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_A', null, 0.00, null, 8000, 240, 'meta', null),
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', 'NS_Audience_B', null, 0.00, null, 6000, 180, 'meta', null),
  -- campaign level: the only reach figure that is deduplicated across the round
  ('DEMO-W8', date '2026-08-10', 'DEMO — Northsea (Meta)', null,            null, 0.00, null, 12000, null, 'meta', null);

-- ── The people, one per cell of the audience × creative matrix ──────────────
-- Emails encode their cell so the events below can find them again without
-- depending on insertion order.
insert into contacts (contact_id, client_id, email)
select gen_random_uuid(), 'northsea_supply',
       'demo+w8-' || c.aud || c.cre || '-' || g.i || '@evergreen.invalid'
from (values
  ('A', 'C1', 18), ('A', 'C2', 14), ('A', 'C3', 11), ('A', 'C4',  7),
  ('B', 'C1', 12), ('B', 'C2', 11), ('B', 'C3',  9), ('B', 'C4',  5)
) as c(aud, cre, n_leads)
cross join lateral generate_series(1, c.n_leads) as g(i);

-- ── Their opt-ins, each carrying the audience and creative that produced it ─
-- utm_campaign AND ad_set both hold the audience: the adset cut reads the utm,
-- v_round_assets reads ad_set, and a lead that answers one and not the other
-- would appear on one tab and vanish from the next.
insert into events (
  contact_id, round_id, event_type, event_date, lead_round_id,
  attribution_method, utm_campaign, ad_set, ad, source, match_status, is_lead, refund_amount
)
select
  ct.contact_id, 'DEMO-W8', 'lead',
  ((date '2026-08-10' + ((g.i - 1) % 7)) + time '10:00') at time zone 'Asia/Singapore',
  'DEMO-W8', 'utm',
  'NS_Audience_' || c.aud, 'NS_Audience_' || c.aud, 'NS_Creative_' || right(c.cre, 1),
  'Paid Ads', 'demo', true, 0
from (values
  ('A', 'C1', 18), ('A', 'C2', 14), ('A', 'C3', 11), ('A', 'C4',  7),
  ('B', 'C1', 12), ('B', 'C2', 11), ('B', 'C3',  9), ('B', 'C4',  5)
) as c(aud, cre, n_leads)
cross join lateral generate_series(1, c.n_leads) as g(i)
join contacts ct
  on ct.client_id = 'northsea_supply'
 and ct.email = 'demo+w8-' || c.aud || c.cre || '-' || g.i || '@evergreen.invalid';

-- ── The purchases, a subset of those same people ────────────────────────────
-- Credit reaches an asset through the buyer's own lead row, so these are the
-- first n_buys people of each cell and nobody else.
insert into events (
  contact_id, round_id, event_type, event_date, lead_round_id,
  source, match_status, product, amount, refund_amount, is_lead
)
select
  ct.contact_id, 'DEMO-W8', 'sale',
  ((date '2026-08-14' + (g.i % 3)) + time '15:00') at time zone 'Asia/Singapore',
  'DEMO-W8', 'Paid Ads', 'demo', 'preview', 297.00, 0, true
from (values
  ('A', 'C1', 9), ('A', 'C2', 6), ('A', 'C3', 5),
  ('B', 'C1', 6), ('B', 'C2', 4), ('B', 'C3', 5)
) as c(aud, cre, n_buys)
cross join lateral generate_series(1, c.n_buys) as g(i)
join contacts ct
  on ct.client_id = 'northsea_supply'
 and ct.email = 'demo+w8-' || c.aud || c.cre || '-' || g.i || '@evergreen.invalid';

-- ═════════════════════════════════════════════════════════════════════════
-- 0048_the_vocabulary_of_measurements_becomes_data.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- What a client can MEASURE stops being source code.
--
-- The journey is already dynamic in every way except one. How many stages a
-- client has, what they are called, what order they run in, what each breaks
-- down by and what a stage costs are all per client and all arrive by push —
-- which is why Shely's headings changed the moment AcqOS sent a funnel.
--
-- What was never dynamic is the VOCABULARY: six metrics, written into three
-- places that had to agree by hand.
--
--   JOURNEY_METRIC_KEYS   TypeScript — the push validator rejected anything else
--   the CASE in 0031/0003 the journey strip's value and rate
--   events.event_type     check (event_type in ('lead','attendance','sale'))
--
-- So "add Appointments" was never a naming problem. It was a schema change in
-- three files, which is the opposite of dynamic, and it is why SECOM's
-- Appointment and CPQL rows render '—' today.
--
-- This migration makes the vocabulary a table. Declaring a measurement becomes
-- an INSERT.
--
-- PHASE 1 OF 4, and it deliberately changes no number anywhere. It seeds
-- exactly the six that exist, marked core, so every view, every ratio and every
-- frozen payload reads precisely what it read before. What it buys is that a
-- seventh can now be DECLARED and validated; making a declared metric produce
-- figures in every cut is phase 2, the journey strip and diagnosis is phase 3,
-- and importing a new event type is phase 4.
--
-- Shipping the foundation on its own is the point: it is additive, it is
-- reversible, and it cannot move a figure in a report that has already gone to
-- a client.
--
-- ROLLBACK:
--   alter table events drop constraint if exists events_event_type_fk;
--   alter table events add constraint events_event_type_check
--     check (event_type in ('lead','attendance','sale'));
--   drop function if exists fo_unknown_metrics(text[]);
--   drop table if exists journey_metrics;
--   drop table if exists event_types;
-- ═══════════════════════════════════════════════════════════════════════════

-- ── The kinds of thing a person can do ──────────────────────────────────────
-- A table rather than a check constraint, because a check constraint is a
-- schema migration and this needs to be a row. `seq` is only a hint about where
-- the thing usually sits in a funnel; the client's own journey decides the real
-- order, and two clients may run the same events in a different sequence.
create table if not exists event_types (
  event_type text primary key,
  label      text not null,
  seq        integer not null default 100
);

insert into event_types (event_type, label, seq) values
  ('lead',       'Lead',       30),
  ('attendance', 'Attendance', 40),
  ('sale',       'Sale',       60)
on conflict (event_type) do nothing;

-- The constraint becomes a foreign key: the same three values are legal today,
-- and a fourth becomes legal by inserting it rather than by altering a table.
alter table events drop constraint if exists events_event_type_check;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'events_event_type_fk' and conrelid = 'events'::regclass
  ) then
    alter table events
      add constraint events_event_type_fk
      foreign key (event_type) references event_types (event_type);
  end if;
end $$;


-- ── The vocabulary of measurements ──────────────────────────────────────────
--
-- One row per thing a journey stage may be measured on.
--
-- `metric` is what a push names. `metric_key` is where the number lives inside
-- the metrics object fo_cut returns — the two differ because the wire is
-- readable and the object is terse, and that mapping was previously a constant
-- in TypeScript that nothing enforced.
--
-- `source` says where the count comes from. 'ads' is a delivery figure off the
-- Meta export and cannot be declared per client; 'events' is a count of people,
-- and that is the half a client can extend.
--
-- `product` exists because 'sale' is one event type carrying two stages. The
-- preview and the middle offer are both sales; only the product tells them
-- apart. A declared metric with a null product counts every event of its type.
create table if not exists journey_metrics (
  metric     text primary key,
  metric_key text not null,
  label      text not null,
  source     text not null check (source in ('ads', 'events')),
  event_type text references event_types (event_type),
  product    text,
  -- Core metrics are the six fo_metrics already computes. They are seeded here
  -- so the vocabulary is complete and queryable, NOT so they can be changed:
  -- their arithmetic lives in fo_metrics and the ratios built on them are named
  -- things with specific denominators, not generic divisions.
  is_core    boolean not null default false,
  seq        integer not null default 100,
  -- A metric off the ads export has no event type; a metric counted from events
  -- must name one, or nothing could count it.
  constraint journey_metrics_source_ok check (
    (source = 'ads'    and event_type is null) or
    (source = 'events' and event_type is not null)
  )
);

insert into journey_metrics (metric, metric_key, label, source, event_type, product, is_core, seq) values
  ('impressions',       'impr',    'Impressions',       'ads',    null,         null,      true, 10),
  ('clicks',            'clicks',  'Clicks',            'ads',    null,         null,      true, 20),
  ('leads',             'leads',   'Leads',             'events', 'lead',       null,      true, 30),
  ('attendance',        'att',     'Attendance',        'events', 'attendance', null,      true, 40),
  ('preview_purchases', 'prevBuy', 'Preview purchases', 'events', 'sale',       'preview', true, 50),
  ('middle_purchases',  'midBuy',  'Middle purchases',  'events', 'sale',       'middle',  true, 60)
on conflict (metric) do nothing;

comment on table journey_metrics is
  'The vocabulary a journey stage may be measured on. The six core rows mirror '
  'fo_metrics and must not be edited; additional rows declare a new measurement, '
  'which a client journey can then name.';


-- ── Does this metric exist? ─────────────────────────────────────────────────
--
-- The same shape as fo_unknown_dimensions, and for the same reason: the
-- validator can say a metric LOOKS like a metric, and only the database can say
-- whether anyone declared it. Returning the unknown ones rather than a boolean
-- lets the caller name the offending stage rather than fail the whole payload
-- with "something was wrong".
create or replace function fo_unknown_metrics(p_metrics text[])
returns text[]
language sql
stable
as $$
  select coalesce(array_agg(distinct m), '{}'::text[])
  from unnest(coalesce(p_metrics, '{}'::text[])) as m
  where m is not null
    and not exists (select 1 from journey_metrics jm where jm.metric = m);
$$;

revoke all on function fo_unknown_metrics(text[]) from public, anon, authenticated;
grant execute on function fo_unknown_metrics(text[]) to service_role;

-- Readable by the app: the journey strip and the integration will both need to
-- ask what a metric means once phase 2 lands.
alter table event_types     enable row level security;
alter table journey_metrics enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where tablename = 'event_types' and policyname = 'demo read') then
    create policy "demo read" on event_types for select using (true);
  end if;
  if not exists (select 1 from pg_policies where tablename = 'journey_metrics' and policyname = 'demo read') then
    create policy "demo read" on journey_metrics for select using (true);
  end if;
end $$;

grant select on event_types     to anon, authenticated, service_role;
grant select on journey_metrics to anon, authenticated, service_role;

-- ═════════════════════════════════════════════════════════════════════════
-- 0049_a_declared_metric_produces_figures.sql
-- ═════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- A declared metric stops being a name and starts being a number.
--
-- 0048 made the vocabulary a table: a client can DECLARE that it measures
-- appointments. Nothing counted them. This is phases 2 and 3 — a declared
-- metric now produces figures in every period cut, and the journey strip
-- renders it with a conversion rate, without a line of code knowing its name.
--
-- WHERE THE COUNTS ARE MERGED, AND WHY NOT INSIDE fo_metrics.
--
-- The obvious place is fo_metrics, and it is the wrong one. 0020 wrote the
-- reason down: "eleven views depend on it, so its signature cannot change
-- without dropping every one of them." Threading an extra argument through
-- twelve views to add a count is a large, risky edit to the most load-bearing
-- object in the schema, and it would have to be repeated for every future
-- metric — which is the hand-editing this work exists to end.
--
-- So the counts are merged at the READ boundary instead. fo_cut already
-- rewrites the metric object on its way out — 0028 blinds channel-incoherent
-- ratios there — and this uses the same seam. fo_metrics is untouched, the
-- eleven views are untouched, and every existing figure is computed by exactly
-- the code that computed it yesterday.
--
-- WHAT A DECLARED METRIC GETS. Its own count under its metric_key, and
-- `cp_<key>` — the round's spend divided by it. That is CPQL for a client whose
-- appointments stage is declared, derived generically rather than named.
--
-- Conversion rate is NOT put in the object, because a rate needs to know which
-- stage came before, and that is the client's journey rather than a property of
-- the metric. The strip computes it.
--
-- THE STRIP'S CASE EXPRESSION GOES, FOR EVERY STAGE. Its five core rates were
-- only ever stage N ÷ stage N-1 spelled out by hand — ctr is clicks over
-- impressions, leadgen is leads over clicks, and so on down. Checked before
-- replacing them: the generic rule reproduces all five as IDENTICAL TEXT, to
-- the last digit, on both clients.
--
-- Keeping the CASE for core stages was the first attempt and it was wrong in
-- exactly the case this work creates. Give a client an Appointment stage
-- between Leads and Attend class and prevPct still divides attendance by leads,
-- so the strip prints a chain whose fifth link skips the fourth.
--
-- It also fixes a live defect. Northsea runs Targeted views → Ads → Product
-- page → Checkout with no class in it, so prevPct divided by an attendance that
-- does not exist and its Checkout card showed no rate at all. It reads 51.4%
-- now — the number that stage has always had.
--
-- WHICH CUTS. Every cut whose column is a PERIOD: round, month, week, total,
-- baseline, and the strip. Asset cuts — by audience, by creative — are
-- deliberately not extended: crediting an appointment to an ad set means
-- joining through the acquiring lead, which is a different claim from counting
-- one, and inventing it here would put a number under a column that has not
-- earned it. Those cuts return the core six exactly as before.
--
-- Months and weeks bucket declared events by the event's OWN local day, the
-- same rule 0044 and 0045 established. A new metric does not get to be filed
-- differently from an old one.
--
-- Changes one existing figure, deliberately, and no other. Every cut for every
-- client was captured before and after and diffed: the sole difference is
-- Northsea's Checkout rate, null before and 51.3647642679900744 after. Extras
-- are only ever merged for metrics flagged is_core = false, and the seed has
-- none, so nothing else can move.
--
-- ROLLBACK: re-run 0031's v_journey_strip and fo_cut, then
--   drop function if exists fo_merge_stage(jsonb, jsonb, text);
--   drop function if exists fo_add_stage_costs(jsonb, jsonb);
--   drop function if exists fo_stage_extras(text, text);
-- ═══════════════════════════════════════════════════════════════════════════

-- ── Counts for every declared metric, bucketed the way the cut buckets ──────
--
-- Reads v_rounds and v_events, so the product, channel and period filters
-- fo_cut has already set apply here without being passed again — the same
-- session settings every metric view reads.
create or replace function fo_stage_extras(p_view text, p_client text)
returns jsonb
language sql
stable
as $$
  with counted as (
    select
      case p_view
        when 'v_metrics_by_round'  then e.round_id
        when 'v_metrics_baseline'  then e.round_id
        when 'v_metrics_by_month'  then to_char(date_trunc('month', (e.event_date at time zone 'Asia/Singapore')::date), 'YYYY-MM')
        when 'v_metrics_by_week'   then to_char(date_trunc('week',  (e.event_date at time zone 'Asia/Singapore')::date), 'IYYY-"W"IW')
        when 'v_metrics_total'     then 'TOTAL'
        when 'v_journey_strip'     then 'TOTAL'
      end as cut_key,
      jm.metric_key,
      count(*)::bigint as n
    from v_events e
    join v_rounds r on r.round_id = e.round_id
    join journey_metrics jm
      on  jm.source = 'events'
      and jm.is_core = false
      and jm.event_type = e.event_type
      and (jm.product is null or e.product = jm.product)
    where r.client_id = p_client
    group by 1, 2
  ),
  per_key as (
    select cut_key, jsonb_object_agg(metric_key, n) as x
    from counted where cut_key is not null
    group by cut_key
  )
  select coalesce(jsonb_object_agg(cut_key, x), '{}'::jsonb) from per_key;
$$;

-- ── Merge the counts, and derive what each one cost ─────────────────────────
--
-- cp_<key> is spend over the count — cost per appointment, cost per whatever
-- was declared. Absent rather than zero when the cut has no spend or produced
-- none of the thing: a cost per nothing is not free, it is unanswerable.
create or replace function fo_add_stage_costs(m jsonb, x jsonb)
returns jsonb
language sql
immutable
as $$
  select coalesce(m, '{}'::jsonb)
      || coalesce(x, '{}'::jsonb)
      || coalesce((
           select jsonb_object_agg(
             'cp_' || e.k,
             case
               when (m ->> 'spend') is not null and e.v ~ '^[0-9]+$' and e.v::numeric > 0
               then (m ->> 'spend')::numeric / e.v::numeric
             end)
           from jsonb_each_text(coalesce(x, '{}'::jsonb)) as e(k, v)
         ), '{}'::jsonb);
$$;

-- ── One row, with its declared metrics folded in ────────────────────────────
--
-- Guards the same thing 0031 guarded: a view with no metric object must pass
-- through untouched rather than have jsonb_set turn the whole row into NULL.
create or replace function fo_merge_stage(row_json jsonb, extras jsonb, cut_key text)
returns jsonb
language sql
immutable
as $$
  select case
    when row_json is null or extras is null or cut_key is null then row_json
    when not (row_json ? 'm') or not (extras ? cut_key) then row_json
    else jsonb_set(row_json, '{m}', fo_add_stage_costs(row_json -> 'm', extras -> cut_key))
  end;
$$;

grant execute on function fo_stage_extras(text, text)          to anon, authenticated, service_role;
grant execute on function fo_add_stage_costs(jsonb, jsonb)     to anon, authenticated, service_role;
grant execute on function fo_merge_stage(jsonb, jsonb, text)   to anon, authenticated, service_role;


-- ── The strip renders whatever the journey names ────────────────────────────
--
-- value comes from the metric's own key rather than a six-branch CASE. For the
-- core six that mapping is exactly what the CASE said — journey_metrics seeds
-- it — so every published value is unchanged.
--
-- rate is this stage over the one before it, in the client's journey order, for
-- every stage. See the header: verified identical to the published ratios.
create or replace view v_journey_strip as
with base as (
  select
    j.client_id, j.stage_order, j.stage_name, j.stage_slug, j.stage_rate_label,
    j.stage_metric,
    jm.metric_key,
    fo_add_stage_costs(t.m, fo_stage_extras('v_journey_strip', j.client_id) -> 'TOTAL') as mm
  from v_journey j
  left join v_metrics_total t on t.client_id = j.client_id
  left join journey_metrics jm on jm.metric = j.stage_metric
),
valued as (
  select *,
    -- Guarded cast: a metric object holds numbers, but a stage naming a metric
    -- nobody declared reads null here rather than failing the whole strip.
    case when (mm ->> metric_key) ~ '^-?[0-9]+(\.[0-9]+)?$'
         then (mm ->> metric_key)::numeric end as value_num
  from base
)
select
  client_id, stage_order, stage_name, stage_slug, stage_rate_label,
  (mm ->> metric_key) as value,
  /*
   * This stage over the one before it, in the client's own journey order —
   * for every stage, core or declared.
   *
   * Verified identical to the published ratios before replacing them: ctr,
   * leadgen, attPct, prevPct and midPct all reproduce to the last digit on both
   * clients, because each was only ever stage N ÷ stage N-1 written out by
   * hand. Nothing on any existing screen moves.
   *
   * Two things it fixes that the CASE could not.
   *
   * A stage inserted between two core ones. Give a client an Appointment stage
   * between Leads and Attend class and prevPct still divided attendance by
   * LEADS, so the strip printed a chain whose fifth link skipped the fourth —
   * "27.1% show" sitting under a stage it did not follow from.
   *
   * A journey that does not have the stage a published ratio assumes. Northsea
   * runs Targeted views → Ads → Product page → Checkout with no class in it, so
   * prevPct divided by an attendance that does not exist and its Checkout card
   * showed no rate at all. It reads 51.4% now, which is the number that stage
   * has always had.
   */
  (
    100 * value_num
    / nullif(lag(value_num) over (partition by client_id order by stage_order), 0)
  )::text as rate,
  stage_metric,
  mm as m
from valued
order by client_id, stage_order;

grant select on v_journey_strip to anon, authenticated;


-- ── fo_cut folds declared metrics into whatever it is asked for ─────────────
create or replace function fo_cut(
  p_view    text,
  p_client  text,
  p_product text default null,
  p_channel text default null,
  p_from    date default null,
  p_to      date default null,
  p_offer   text default null
) returns setof jsonb
language plpgsql
stable
as $$
declare
  v_order  text;
  v_where  text := '';
  v_row    text;
  v_sel    text;
  v_key    text;
  v_shared integer;
  v_extras jsonb;
begin
  v_order := case p_view
    when 'v_metrics_by_month'        then 'month_start'
    when 'v_metrics_by_week'         then 'week_start'
    when 'v_metrics_by_round'        then 'start_date'
    when 'v_metrics_by_round_source' then 'start_date, ord'
    when 'v_metrics_by_offer'        then 'start_date'
    when 'v_metrics_by_source'       then 'ord'
    when 'v_metrics_by_adset'        then 'ord'
    when 'v_metrics_by_ad'           then 'ord'
    when 'v_metrics_by_session'      then 'ord'
    when 'v_metrics_this_round'      then 'ord'
    when 'v_metrics_total'           then 'cut_key'
    when 'v_metrics_baseline'        then 'cut_key'
    when 'v_journey_strip'           then 'stage_order'
    else null
  end;

  if v_order is null then
    raise exception 'fo_cut: % is not a readable cut', p_view;
  end if;

  perform set_config('funnel.product', coalesce(p_product, ''), true);
  perform set_config('funnel.channel', coalesce(p_channel, ''), true);
  perform set_config('funnel.from',    coalesce(p_from::text, ''), true);
  perform set_config('funnel.to',      coalesce(p_to::text,   ''), true);

  v_row := 'to_jsonb(t)';

  -- Did selecting this channel actually take spend away? Counted with the
  -- channel setting momentarily cleared, and put straight back.
  if p_channel is not null then
    perform set_config('funnel.channel', '', true);
    select count(distinct coalesce(channel, 'other'))
      into v_shared
      from v_ads
     where client_id = p_client
       and coalesce(spend, 0) <> 0;
    perform set_config('funnel.channel', p_channel, true);

    if coalesce(v_shared, 0) > 1 then
      -- `? 'm'` guards a view that has no metric object: jsonb_set returns NULL
      -- when handed one, which would drop every row without raising anything.
      v_row := 'case when to_jsonb(t) ? ''m'''
            || ' then jsonb_set(to_jsonb(t), ''{m}'', fo_channel_blind(to_jsonb(t)->''m''))'
            || ' else to_jsonb(t) end';
    end if;
  end if;

  /*
   * Declared metrics, folded in after the blinding rather than before.
   *
   * Order matters and this is the safe way round: fo_channel_blind nulls the
   * ratios a channel filter cannot answer, and it knows the core keys. Merging
   * first would hand it an object holding keys it has never seen.
   *
   * The strip is keyed on TOTAL because it is always the whole filtered window
   * — it has no cut_key column to read, and asking for one would fail.
   */
  v_extras := fo_stage_extras(p_view, p_client);
  if v_extras <> '{}'::jsonb then
    v_key := case when p_view = 'v_journey_strip' then '''TOTAL''' else 't.cut_key' end;
    v_row := 'fo_merge_stage(' || v_row || ', $3, ' || v_key || ')';
  end if;
  v_sel := 'select ' || v_row;

  if p_view = 'v_metrics_by_offer' and p_offer is not null then
    v_where := ' and product = $2';
    return query execute
      format('%s from %I t where client_id = $1%s order by %s', v_sel, p_view, v_where, v_order)
      using p_client, p_offer, v_extras;
  else
    return query execute
      format('%s from %I t where client_id = $1 order by %s', v_sel, p_view, v_order)
      using p_client, p_offer, v_extras;
  end if;
end;
$$;

grant execute on function fo_cut(text, text, text, text, date, date, text) to anon, authenticated;
